-- Easy Professions (Forever): guide texts in zhTW (translated from wow-professions.com/forever)
local _, ns = ...
ns.AddTranslation("zhTW", {
  ["This WoW Forever Alchemy leveling guide will show you the fastest and cheapest way to level your Alchemy skill from 1 to 300. You will also find every trainer location and where to train Alchemy past 75, 150 and 225."] = "這份 WoW Forever 鍊金術升級指南將告訴你如何以最快、最省錢的方式將鍊金術技能從 1 升到 300。你也能找到每位訓練師的位置，以及在 75、150 和 225 之後要去哪裡繼續學習鍊金術。",
  ["Below you will find the full shopping list, the Alchemy trainers by starting zone and capital city, and the cheapest recipes for every skill range from Apprentice to Artisan. Alchemy is best combined with Herbalism, with these two you can save a lot of gold because you don't have to buy the herbs from the Auction House."] = "下方有完整的購物清單、依新手區與主城分類的鍊金術訓練師，以及從學徒到工匠每個技能區間最便宜的配方。鍊金術最適合搭配草藥學，兩者一起練可以省下大量金幣，因為你不必在拍賣場購買草藥。",
  ["This is based on the Forever beta. Leveling takes a long time, so testing the higher levels on live will take a while. If you find something that's off, send me feedback."] = "本指南以 Forever 測試版為基礎。升級需要很長時間，所以在正式伺服器上測試高等級部分還需要一段時間。如果你發現有誤，請告訴我。",
  ["Shopping List"] = "購物清單",
  ["These numbers are estimates. Once a recipe turns yellow you won't get a skill point from every craft, so you might need a few more or a few less."] = "這些數量都是估計值。配方變成黃色後，並非每次製作都會獲得技能點，所以你可能需要多做或少做幾個。",
  ["Alchemy Trainer Locations"] = "鍊金術訓練師位置",
  ["Apprentice Alchemy has no level requirement in Forever, so you can learn it on a fresh character."] = "在 Forever 中學習學徒鍊金術沒有等級需求，所以新角色也能學。",
  ["Every capital city has a trainer. You can also ask a guard, then it will be marked with a red flag on your map."] = "每座主城都有訓練師。你也可以詢問衛兵，地圖上就會用紅旗標出位置。",
  ["Horde"] = "部落",
  ["Alliance"] = "聯盟",
  ["Capital Cities"] = "主城",
  ["Orgrimmar: {n:0:horde:Whuut}"] = "奧格瑪：{n:0:horde:Whuut}",
  ["Undercity: {n:0:horde:Doctor Martin Felben}"] = "幽暗城：{n:0:horde:Doctor Martin Felben}",
  ["Thunder Bluff: {n:0:horde:Kray}"] = "雷霆崖：{n:0:horde:Kray}",
  ["Starting Zones"] = "新手區",
  ["Not every zone has a trainer, the table shows the closest one for each race."] = "並非每個區域都有訓練師，表格列出各種族最近的訓練師。",
  ["Race"] = "種族",
  ["Zone"] = "區域",
  ["Closest trainer"] = "最近的訓練師",
  ["Orc, Troll"] = "獸人、食人妖",
  ["Durotar"] = "杜洛塔",
  ["{n:0:horde:Miao'zan} in Sen'jin Village"] = "森金村的 {n:0:horde:Miao'zan}",
  ["Tauren"] = "牛頭人",
  ["Mulgore"] = "莫高雷",
  ["There is no Alchemy trainer in Mulgore, go to {n:0:horde:Kray} on the middle rise in Thunder Bluff"] = "莫高雷沒有鍊金術訓練師，請去雷霆崖中間高台找 {n:0:horde:Kray}",
  ["Undead"] = "不死族",
  ["Tirisfal Glades"] = "提里斯法林地",
  ["{n:0:horde:Carolai Anise} in the small house at the north-west end of Brill"] = "布瑞爾西北端小屋裡的 {n:0:horde:Carolai Anise}",
  ["Skyborne"] = "天裔族",
  ["Zephras Isle"] = "澤弗拉斯島",
  ["{n:0::Iaadaria Bitterwind} or {n:0::Valiena Swiftgale} in Valanaar, {n:0::Nyassa Swiftdraught} in Shen'dar Village"] = "瓦拉納爾的 {n:0::Iaadaria Bitterwind} 或 {n:0::Valiena Swiftgale}，申達爾村的 {n:0::Nyassa Swiftdraught}",
  ["Stormwind City: {n:0:alliance:Tel'Athir}"] = "暴風城：{n:0:alliance:Tel'Athir}",
  ["Ironforge: {n:0:alliance:Vosur Brakthel}"] = "鐵爐堡：{n:0:alliance:Vosur Brakthel}",
  ["Darnassus: {n:0:alliance:Milla Fairancora}"] = "達納蘇斯：{n:0:alliance:Milla Fairancora}",
  ["Human"] = "人類",
  ["Elwynn Forest"] = "艾爾文森林",
  ["{n:0:alliance:Alchemist Mallory} in a cottage in the hills between Stormwind and Northshire"] = "暴風城與北郡之間山丘上小屋裡的 {n:0:alliance:Alchemist Mallory}",
  ["Dwarf, Gnome"] = "矮人、地精",
  ["Dun Morogh"] = "丹莫洛",
  ["There is no Alchemy trainer in Dun Morogh, go to {n:0:alliance:Vosur Brakthel} in Tinker Town in Ironforge"] = "丹莫洛沒有鍊金術訓練師，請去鐵爐堡地精區找 {n:0:alliance:Vosur Brakthel}",
  ["Night Elf"] = "夜精靈",
  ["Teldrassil"] = "泰達希爾",
  ["{n:0:alliance:Cyndra Kindwhisper} in a small house east of the inn in Dolanaar"] = "多蘭納爾旅店東邊小屋裡的 {n:0:alliance:Cyndra Kindwhisper}",
  ["You can find every Alchemy trainer for Horde and Alliance on my WoW Forever Alchemy Trainers page."] = "你可以在我的 WoW Forever 鍊金術訓練師頁面找到部落和聯盟的所有鍊金術訓練師。",
  ["Apprentice Alchemy (1-55)"] = "學徒鍊金術 (1-55)",
  ["9x {s:1245250:inv_potion_77:Elixir of Minor Force} - 9 Silverleaf, 9 Empty Vial"] = "9x {s:1245250:inv_potion_77:Elixir of Minor Force} - 9 銀葉草、9 空瓶",
  ["The vials are sold by Alchemy Supply and Trade Supply vendors, most trainers have one nearby. In Undercity the closest one is {n:0:horde:Algernon}, in Dolanaar it's {n:0:alliance:Narret Shadowgrove}."] = "空瓶由鍊金術供應商和商業供應商出售，大多數訓練師附近都有一位。在幽暗城最近的是 {n:0:horde:Algernon}，在多蘭納爾則是 {n:0:alliance:Narret Shadowgrove}。",
  ["45x {s:7183:inv_potion_63:Elixir of Minor Defense} - 45 Silverleaf, 45 Peacebloom, 45 Empty Vial"] = "45x {s:7183:inv_potion_63:Elixir of Minor Defense} - 45 銀葉草、45 寧神花、45 空瓶",
  ["Journeyman Alchemy (55-150)"] = "熟手鍊金術 (55-150)",
  ["To train past 75, visit one of these trainers and learn Journeyman Alchemy. You need {b}Alchemy 50{/b} and {b}level 10{/b}:"] = "要學習 75 以上，請找以下任一位訓練師學習熟手鍊金術。你需要{b}鍊金術 50{/b}和{b}等級 10{/b}：",
  ["{b}Horde trainers:{/b}"] = "{b}部落訓練師：{/b}",
  ["Orgrimmar: {n:0:horde:Yelmak}"] = "奧格瑪：{n:0:horde:Yelmak}",
  ["Undercity: {n:0:horde:Doctor Marsh}"] = "幽暗城：{n:0:horde:Doctor Marsh}",
  ["Thunder Bluff: {n:0:horde:Bena Winterhoof}"] = "雷霆崖：{n:0:horde:Bena Winterhoof}",
  ["{b}Alliance trainers:{/b}"] = "{b}聯盟訓練師：{/b}",
  ["Stormwind City: {n:0:alliance:Lilyssia Nightbreeze}"] = "暴風城：{n:0:alliance:Lilyssia Nightbreeze}",
  ["Ironforge: {n:0:alliance:Tally Berryfizz}"] = "鐵爐堡：{n:0:alliance:Tally Berryfizz}",
  ["Darnassus: {n:0:alliance:Sylvanna Forestmoon}"] = "達納蘇斯：{n:0:alliance:Sylvanna Forestmoon}",
  ["10x {s:2331:inv_potion_70:Minor Mana Potion} - 10 Mageroyal, 10 Peacebloom, 10 Empty Vial"] = "10x {s:2331:inv_potion_70:Minor Mana Potion} - 10 魔皇草、10 寧神花、10 空瓶",
  ["28x {s:2334:inv_potion_42:Elixir of Minor Fortitude} - 56 Earthroot, 28 Peacebloom, 28 Empty Vial"] = "28x {s:2334:inv_potion_42:Elixir of Minor Fortitude} - 56 地根草、28 寧神花、28 空瓶",
  ["30x {s:3171:inv_potion_06:Elixir of Wisdom} - 30 Mageroyal, 60 Briarthorn, 30 Empty Vial"] = "30x {s:3171:inv_potion_06:Elixir of Wisdom} - 30 魔皇草、60 石南草、30 空瓶",
  ["Keep the elixirs if you also level Tailoring, you will need them for the Gloves of Meditation."] = "如果你也在練裁縫，請保留這些藥劑，製作冥想手套時會用到。",
  ["10x {s:3173:inv_potion_71:Lesser Mana Potion} - 10 Mageroyal, 10 Stranglekelp, 10 Empty Vial"] = "10x {s:3173:inv_potion_71:Lesser Mana Potion} - 10 魔皇草、10 荊棘藻、10 空瓶",
  ["20x {s:7837:inv_potion_38:Fire Oil} - 40 Firefin Snapper, 20 Empty Vial"] = "20x {s:7837:inv_potion_38:Fire Oil} - 40 火鱗鱔、20 空瓶",
  ["You get 2 oils from every craft. Keep 30 of them, you will need them for the Elixir of Fire Power in the next part."] = "每次製作會得到 2 瓶油。保留其中 30 瓶，下一部分製作火力藥劑時會用到。",
  ["Expert Alchemy (150-225)"] = "專家鍊金術 (150-225)",
  ["To train past 150, visit {n:0:horde:Doctor Herbert Halsey} in Undercity (Horde) or {n:0:alliance:Ainethil} in Darnassus (Alliance) and learn Expert Alchemy. You need {b}Alchemy 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "要學習 150 以上，請找幽暗城的 {n:0:horde:Doctor Herbert Halsey}（部落）或達納蘇斯的 {n:0:alliance:Ainethil}（聯盟）學習專家鍊金術。你需要{b}鍊金術 125{/b}和{b}等級 20{/b}，費用為 50 銀幣。",
  ["15x {s:7845:inv_potion_55:Elixir of Fire Power} - 30 Fire Oil, 15 Kingsblood, 15 Leaded Vial"] = "15x {s:7845:inv_potion_55:Elixir of Fire Power} - 30 火焰油、15 皇血草、15 鉛瓶",
  ["These are the Fire Oils you kept."] = "就是你保留下來的那些火焰油。",
  ["36x {s:3452:inv_potion_72:Mana Potion} - 36 Stranglekelp, 36 Kingsblood, 36 Leaded Vial"] = "36x {s:3452:inv_potion_72:Mana Potion} - 36 荊棘藻、36 皇血草、36 鉛瓶",
  ["36x {s:7259:inv_potion_06:Nature Protection Potion} - 36 Liferoot, 36 Stranglekelp, 36 Leaded Vial"] = "36x {s:7259:inv_potion_06:Nature Protection Potion} - 36 活根草、36 荊棘藻、36 鉛瓶",
  ["{i:6057:inv_scroll_03:Recipe: Nature Protection Potion} is sold by these vendors, it's bind on pickup, so buy it with the character that levels Alchemy:"] = "{i:6057:inv_scroll_03:Recipe: Nature Protection Potion} 由以下商人出售，它是拾取綁定，所以請用練鍊金術的角色購買：",
  ["{n:0:horde:Bronk} in Feralas"] = "菲拉斯的 {n:0:horde:Bronk}",
  ["{n:0:alliance:Logannas} in Feralas"] = "菲拉斯的 {n:0:alliance:Logannas}",
  ["{n:0::Glyx Brewright} in Stranglethorn Vale"] = "荊棘谷的 {n:0::Glyx Brewright}",
  ["{n:0::Alchemist Pestlezugg} in Tanaris"] = "塔納利斯的 {n:0::Alchemist Pestlezugg}",
  ["Artisan Alchemy (225-300)"] = "工匠鍊金術 (225-300)",
  ["To train past 225, visit {n:0:horde:Rogvar} in Stonard, Swamp of Sorrows (Horde) or {n:0:alliance:Kylanna Windwhisper} in Feathermoon Stronghold, Feralas (Alliance) and learn Artisan Alchemy. You need {b}Alchemy 200{/b} and {b}level 35{/b}."] = "要學習 225 以上，請找悲傷沼澤斯通納德的 {n:0:horde:Rogvar}（部落）或菲拉斯羽月要塞的 {n:0:alliance:Kylanna Windwhisper}（聯盟）學習工匠鍊金術。你需要{b}鍊金術 200{/b}和{b}等級 35{/b}。",
  ["26x {s:7259:inv_potion_06:Nature Protection Potion} - 26 Liferoot, 26 Stranglekelp, 26 Leaded Vial"] = "26x {s:7259:inv_potion_06:Nature Protection Potion} - 26 活根草、26 荊棘藻、26 鉛瓶",
  ["15x {s:11465:inv_potion_10:Elixir of Greater Intellect} - 15 Blindweed, 15 Khadgar's Whisker, 15 Crystal Vial"] = "15x {s:11465:inv_potion_10:Elixir of Greater Intellect} - 15 盲目草、15 卡德加的鬍鬚、15 水晶瓶",
  ["47x {s:17551:inv_potion_68:Stonescale Oil} - 47 Stonescale Eel, 47 Leaded Vial"] = "47x {s:17551:inv_potion_68:Stonescale Oil} - 47 石鱗鰻、47 鉛瓶",
  ["{b}Keep all of them{/b}, one craft makes 2 and the elixirs at 265 need all 94."] = "{b}全部保留{/b}，每次製作會得到 2 瓶，而 265 的藥劑需要全部 94 瓶。",
  ["Alternative recipe"] = "替代配方",
  ["If {i:13422:inv_misc_fish_11:Stonescale Eel} is expensive, skip this and keep making the Elixir of Greater Intellect until 265 (about 21), then make the Superior Mana Potions under 265-300."] = "如果 {i:13422:inv_misc_fish_11:Stonescale Eel} 很貴，就跳過這步，繼續製作強效智力藥劑直到 265（約 21 個），然後在 265-300 製作極效法力藥水。",
  ["10x {s:11465:inv_potion_10:Elixir of Greater Intellect} - 10 Blindweed, 10 Khadgar's Whisker, 10 Crystal Vial"] = "10x {s:11465:inv_potion_10:Elixir of Greater Intellect} - 10 盲目草、10 卡德加的鬍鬚、10 水晶瓶",
  ["47x {s:17554:inv_potion_66:Elixir of Greater Defense} - 94 Stonescale Oil, 47 Sungrass, 47 Crystal Vial"] = "47x {s:17554:inv_potion_66:Elixir of Greater Defense} - 94 石鱗油、47 太陽草、47 水晶瓶",
  ["{i:13478:inv_scroll_03:Recipe: Elixir of Superior Defense} is sold by {n:0:horde:Kor'geld} in Orgrimmar and {n:0:alliance:Soolie Berryfizz} in Ironforge."] = "{i:13478:inv_scroll_03:Recipe: Elixir of Superior Defense} 由奧格瑪的 {n:0:horde:Kor'geld} 和鐵爐堡的 {n:0:alliance:Soolie Berryfizz} 出售。",
  ["If you skipped the Stonescale Oil, make this:"] = "如果你跳過了石鱗油，就製作這個：",
  ["55x {s:17553:inv_potion_74:Superior Mana Potion} - 110 Sungrass, 110 Blindweed, 55 Crystal Vial."] = "55x {s:17553:inv_potion_74:Superior Mana Potion} - 110 太陽草、110 盲目草、55 水晶瓶。",
  ["{i:13477:inv_scroll_03:Recipe: Superior Mana Potion} is sold by {n:0:horde:Algernon} in Undercity and {n:0:alliance:Ulthir} in Darnassus."] = "{i:13477:inv_scroll_03:Recipe: Superior Mana Potion} 由幽暗城的 {n:0:horde:Algernon} 和達納蘇斯的 {n:0:alliance:Ulthir} 出售。",
  ["This WoW Forever Blacksmithing leveling guide will show you the fastest and cheapest way to level your Blacksmithing skill from 1 to 300. You will also find every trainer location and where to train Blacksmithing past 75, 150 and 225."] = "這份 WoW Forever 鍛造升級指南將告訴你如何以最快、最省錢的方式將鍛造技能從 1 升到 300。你也能找到每位訓練師的位置，以及在 75、150 和 225 之後要去哪裡繼續學習鍛造。",
  ["Below you will find the full shopping list, the Blacksmithing trainers by starting zone and capital city, and the cheapest recipes for every skill range from Apprentice to Artisan. Blacksmithing uses a lot of ore, so I recommend leveling it together with Mining, you will need a lot of gold if you want to buy everything from the Auction House."] = "下方有完整的購物清單、依新手區與主城分類的鍛造訓練師，以及從學徒到工匠每個技能區間最便宜的配方。鍛造會用到大量礦石，所以我建議搭配採礦一起練，如果全部從拍賣場購買，你會需要很多金幣。",
  ["The Thorium Bars include the 140 you need for the four quests."] = "瑟銀錠的數量包含四個任務所需的 140 個。",
  ["Blacksmithing Trainer Locations"] = "鍛造訓練師位置",
  ["Apprentice Blacksmithing has no level requirement in Forever, so you can learn it on a fresh character."] = "在 Forever 中學習學徒鍛造沒有等級需求，所以新角色也能學。",
  ["Every capital city has a trainer except Darnassus. You can also ask a guard, then it will be marked with a red flag on your map."] = "除了達納蘇斯，每座主城都有訓練師。你也可以詢問衛兵，地圖上就會用紅旗標出位置。",
  ["Orgrimmar: {n:0:horde:Ug'thok}"] = "奧格瑪：{n:0:horde:Ug'thok}",
  ["Undercity: {n:0:horde:Basil Frye}"] = "幽暗城：{n:0:horde:Basil Frye}",
  ["Thunder Bluff: {n:0:horde:Thrag Stonehoof}"] = "雷霆崖：{n:0:horde:Thrag Stonehoof}",
  ["{n:0:horde:Dwukk} at the forge in Razor Hill"] = "剃刀嶺鍛爐旁的 {n:0:horde:Dwukk}",
  ["There is no Blacksmithing trainer in Mulgore, go to {n:0:horde:Thrag Stonehoof} on the lower rise in Thunder Bluff"] = "莫高雷沒有鍛造訓練師，請去雷霆崖下層高台找 {n:0:horde:Thrag Stonehoof}",
  ["{n:0:horde:Angus Hammerhand} at Bandarion Keep. Nobody near him sells a {i:5956:inv_hammer_20:Blacksmith Hammer}, {b}buy one before you go{/b} from {n:0:horde:Walter Mason} in Deathknell or {n:0:horde:Abigail Shiel} in Brill."] = "班達利恩要塞的 {n:0:horde:Angus Hammerhand}。他附近沒有人出售 {i:5956:inv_hammer_20:Blacksmith Hammer}，{b}出發前先買一把{/b}，可在喪鐘鎮的 {n:0:horde:Walter Mason} 或布瑞爾的 {n:0:horde:Abigail Shiel} 購買。",
  ["{n:0::Daeann Steelwind} in Valanaar, {n:0::Aedi Thriceforged} in Shen'dar Village"] = "瓦拉納爾的 {n:0::Daeann Steelwind}，申達爾村的 {n:0::Aedi Thriceforged}",
  ["Stormwind City: {n:0:alliance:Dane Lindgren}"] = "暴風城：{n:0:alliance:Dane Lindgren}",
  ["Ironforge: {n:0:alliance:Groum Stonebeard}"] = "鐵爐堡：{n:0:alliance:Groum Stonebeard}",
  ["{n:0:alliance:Smith Argus} in Goldshire, across from the inn"] = "閃金鎮旅店對面的 {n:0:alliance:Smith Argus}",
  ["{n:0:alliance:Tognus Flintfire} in Kharanos, across from the Thunderbrew Distillery"] = "卡拉諾斯雷酒釀酒廠對面的 {n:0:alliance:Tognus Flintfire}",
  ["There is no Blacksmithing trainer in Teldrassil or Darnassus, the closest one is {n:0:alliance:Delfrum Flintbeard} in Auberdine, Darkshore"] = "泰達希爾和達納蘇斯沒有鍛造訓練師，最近的是黑海岸奧伯丁的 {n:0:alliance:Delfrum Flintbeard}",
  ["You can find every Blacksmithing trainer for Horde and Alliance on my WoW Forever Blacksmithing Trainers page."] = "你可以在我的 WoW Forever 鍛造訓練師頁面找到部落和聯盟的所有鍛造訓練師。",
  ["Apprentice Blacksmithing (1-75)"] = "學徒鍛造 (1-75)",
  ["Buy a {i:5956:inv_hammer_20:Blacksmith Hammer} when you learn Blacksmithing, most recipes need it, so you can craft gear for yourself while you level. It costs a few copper, open your faction below to see who sells it closest to your trainer."] = "學會鍛造時就買一把 {i:5956:inv_hammer_20:Blacksmith Hammer}，大多數配方都需要它，這樣你在升級時也能為自己打造裝備。它只要幾枚銅幣，展開下方你的陣營，看看離訓練師最近的賣家是誰。",
  ["Horde vendors"] = "部落商人",
  ["Vendor"] = "商人",
  ["Orgrimmar"] = "奧格瑪",
  ["{n:0:horde:Sumi}, right next to the trainer"] = "{n:0:horde:Sumi}，就在訓練師旁邊",
  ["Undercity"] = "幽暗城",
  ["{n:0:horde:Samuel Van Brunt}, right next to the trainer"] = "{n:0:horde:Samuel Van Brunt}，就在訓練師旁邊",
  ["Thunder Bluff"] = "雷霆崖",
  ["{n:0:horde:Taur Stonehoof}, right next to the trainer"] = "{n:0:horde:Taur Stonehoof}，就在訓練師旁邊",
  ["{n:0:horde:Flakk} in Razor Hill"] = "剃刀嶺的 {n:0:horde:Flakk}",
  ["{n:0:horde:Walter Mason} in Deathknell {n:0:horde:Abigail Shiel} in Brill"] = "喪鐘鎮的 {n:0:horde:Walter Mason} 布瑞爾的 {n:0:horde:Abigail Shiel}",
  ["{n:0::Halavuul Cragwind}, the Mining trainer in Valanaar {n:0::Aedi Thriceforged} in Shen'dar Village"] = "瓦拉納爾的採礦訓練師 {n:0::Halavuul Cragwind} 申達爾村的 {n:0::Aedi Thriceforged}",
  ["Alliance vendors"] = "聯盟商人",
  ["Stormwind City"] = "暴風城",
  ["{n:0:alliance:Kaita Deepforge}, right next to the trainer"] = "{n:0:alliance:Kaita Deepforge}，就在訓練師旁邊",
  ["Ironforge"] = "鐵爐堡",
  ["{n:0:alliance:Thurgrum Deepforge}, right next to the trainer"] = "{n:0:alliance:Thurgrum Deepforge}，就在訓練師旁邊",
  ["{n:0:alliance:Tharynn Bouden} in Goldshire"] = "閃金鎮的 {n:0:alliance:Tharynn Bouden}",
  ["{n:0:alliance:Thrawn Boltar}, right next to the trainer"] = "{n:0:alliance:Thrawn Boltar}，就在訓練師旁邊",
  ["Darkshore"] = "黑海岸",
  ["{n:0:alliance:Elisa Steelhand} in Auberdine, right next to the trainer"] = "奧伯丁的 {n:0:alliance:Elisa Steelhand}，就在訓練師旁邊",
  ["30x {s:2660:inv_stone_sharpeningstone_01:Rough Sharpening Stone} - 30 Rough Stone"] = "30x {s:2660:inv_stone_sharpeningstone_01:Rough Sharpening Stone} - 30 劣質的石頭",
  ["30x {s:3320:inv_stone_grindingstone_01:Rough Grinding Stone} - 60 Rough Stone"] = "30x {s:3320:inv_stone_grindingstone_01:Rough Grinding Stone} - 60 劣質的石頭",
  ["Keep 10 of them, you need them for the Silver Rods at 75."] = "保留其中 10 個，75 製作銀棒時會用到。",
  ["36x {s:3326:inv_stone_grindingstone_02:Coarse Grinding Stone} - 72 Coarse Stone"] = "36x {s:3326:inv_stone_grindingstone_02:Coarse Grinding Stone} - 72 粗糙的石頭",
  ["Make all 36, you will need them for the bracers at 95 and 112."] = "36 個全部做完，95 和 112 製作護腕時會用到。",
  ["If you are not at 75 after these, make a few more."] = "做完這些後如果還沒到 75，就再多做幾個。",
  ["Journeyman Blacksmithing (75-150)"] = "熟手鍛造 (75-150)",
  ["To train past 75, visit one of these trainers and learn Journeyman Blacksmithing. You need {b}Blacksmithing 50{/b} and {b}level 10{/b}:"] = "要學習 75 以上，請找以下任一位訓練師學習熟手鍛造。你需要{b}鍛造 50{/b}和{b}等級 10{/b}：",
  ["Orgrimmar: {n:0:horde:Snarl}"] = "奧格瑪：{n:0:horde:Snarl}",
  ["Undercity: {n:0:horde:James Van Brunt}"] = "幽暗城：{n:0:horde:James Van Brunt}",
  ["Thunder Bluff: {n:0:horde:Karn Stonehoof}"] = "雷霆崖：{n:0:horde:Karn Stonehoof}",
  ["Tirisfal Glades: {n:0:horde:Angus Hammerhand} at Bandarion Keep"] = "提里斯法林地：班達利恩要塞的 {n:0:horde:Angus Hammerhand}",
  ["Zephras Isle: {n:0::Daeann Steelwind} in Valanaar"] = "澤弗拉斯島：瓦拉納爾的 {n:0::Daeann Steelwind}",
  ["Stormwind City: {n:0:alliance:Therum Deepforge}"] = "暴風城：{n:0:alliance:Therum Deepforge}",
  ["Ironforge: {n:0:alliance:Rotgath Stonebeard}"] = "鐵爐堡：{n:0:alliance:Rotgath Stonebeard}",
  ["5x {s:7818:inv_staff_01:Silver Rod} - 5 Silver Bar, 10 Rough Grinding Stone"] = "5x {s:7818:inv_staff_01:Silver Rod} - 5 銀錠、10 劣質磨刀石",
  ["You need the {i:5956:inv_hammer_20:Blacksmith Hammer} from here on."] = "從這裡開始你需要 {i:5956:inv_hammer_20:Blacksmith Hammer}。",
  ["Make 5x {s:2666:inv_belt_03:Runed Copper Belt} instead (10 Copper Bar each) if one Silver Bar costs more than 10 Copper Bars."] = "如果 1 個銀錠比 10 個銅錠還貴，就改做 5x {s:2666:inv_belt_03:Runed Copper Belt}（每個 10 銅錠）。",
  ["18x {s:2666:inv_belt_03:Runed Copper Belt} - 180 Copper Bar"] = "18x {s:2666:inv_belt_03:Runed Copper Belt} - 180 銅錠",
  ["5x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 25 Bronze Bar, 10 Coarse Grinding Stone"] = "5x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 25 青銅錠、10 粗糙磨刀石",
  ["Use 10 of the Coarse Grinding Stones you made at 50 and keep the other 26 for 112."] = "使用你在 50 製作的 10 個粗糙磨刀石，其餘 26 個留到 112。",
  ["20x {s:3337:inv_stone_grindingstone_03:Heavy Grinding Stone} - 60 Heavy Stone"] = "20x {s:3337:inv_stone_grindingstone_03:Heavy Grinding Stone} - 60 沉重的石頭",
  ["Keep them, you need all 20 for the Golden Scale Bracers at 180."] = "保留它們，180 製作金鱗護腕時 20 個全部都會用到。",
  ["13x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 65 Bronze Bar, 26 Coarse Grinding Stone"] = "13x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 65 青銅錠、26 粗糙磨刀石",
  ["24x {s:2742:inv_sword_04:Bronze Shortsword} - 120 Bronze Bar, 96 Weak Flux, 48 Medium Leather"] = "24x {s:2742:inv_sword_04:Bronze Shortsword} - 120 青銅錠、96 弱效助熔劑、48 中皮",
  ["I recommend these over the Patterned Bronze Bracers because they sell for more than twice as much to a vendor, so they end up cheaper."] = "我推薦做這個而不是花紋青銅護腕，因為它賣給商人的價格是兩倍以上，算下來反而更便宜。",
  ["{i:2880:inv_misc_ammo_gunpowder_02:Weak Flux} and the {i:3466:inv_misc_ammo_gunpowder_01:Strong Flux} for the Bronze Warhammers (140-150) are sold by the Blacksmithing Supply vendor right next to the Blacksmithing trainer in every capital city."] = "{i:2880:inv_misc_ammo_gunpowder_02:Weak Flux} 以及青銅戰錘 (140-150) 所需的 {i:3466:inv_misc_ammo_gunpowder_01:Strong Flux}，在每座主城鍛造訓練師旁邊的鍛造供應商都有出售。",
  ["If you disenchant your greens:"] = "如果你會分解綠色裝備：",
  ["24x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 120 Bronze Bar, 48 Coarse Grinding Stone."] = "24x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 120 青銅錠、48 粗糙磨刀石。",
  ["10x {s:9985:inv_hammer_18:Bronze Warhammer} - 80 Bronze Bar, 10 Strong Flux, 10 Medium Leather"] = "10x {s:9985:inv_hammer_18:Bronze Warhammer} - 80 青銅錠、10 強效助熔劑、10 中皮",
  ["Expert Blacksmithing (150-215)"] = "專家鍛造 (150-215)",
  ["To train past 150, visit {n:0:horde:Saru Steelfury} in Orgrimmar (Horde) or {n:0:alliance:Bengus Deepforge} in Ironforge (Alliance) and learn Expert Blacksmithing. You need {b}Blacksmithing 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "要學習 150 以上，請找奧格瑪的 {n:0:horde:Saru Steelfury}（部落）或鐵爐堡的 {n:0:alliance:Bengus Deepforge}（聯盟）學習專家鍛造。你需要{b}鍛造 125{/b}和{b}等級 20{/b}，費用為 50 銀幣。",
  ["30x {s:3501:inv_bracer_06:Green Iron Bracers} - 180 Iron Bar, 30 Green Dye"] = "30x {s:3501:inv_bracer_06:Green Iron Bracers} - 180 鐵錠、30 綠色染料",
  ["Green Dye is sold by {n:0:horde:Tamar} in Orgrimmar and {n:0:alliance:Bombus Finespindle} in Ironforge."] = "綠色染料由奧格瑪的 {n:0:horde:Tamar} 和鐵爐堡的 {n:0:alliance:Bombus Finespindle} 出售。",
  ["8x {s:9920:inv_stone_grindingstone_04:Solid Grinding Stone} - 32 Solid Stone"] = "8x {s:9920:inv_stone_grindingstone_04:Solid Grinding Stone} - 32 堅固的石頭",
  ["Keep them, you need 6 for the Heavy Mithril Axes at 210."] = "保留它們，210 製作重型秘銀斧時需要 6 個。",
  ["20x {s:7223:inv_bracer_10:Golden Scale Bracers} - 100 Steel Bar, 40 Heavy Grinding Stone"] = "20x {s:7223:inv_bracer_10:Golden Scale Bracers} - 100 鋼錠、40 沉重磨刀石",
  ["Use the 20 Heavy Grinding Stones you made at 100 and make 20 more (60 {i:2838:inv_stone_12:Heavy Stone})."] = "使用你在 100 製作的 20 個沉重磨刀石，再多做 20 個（60 {i:2838:inv_stone_12:Heavy Stone}）。",
  ["If you have Mining 165, you can smelt the {i:3859:inv_ingot_steel:Steel Bars} yourself from {i:3575:inv_ingot_iron:Iron Bar} and {i:3857:inv_ore_tin_01:Coal}. Coal is sold by the Blacksmithing Supply vendor next to the Blacksmithing trainer in every capital city."] = "如果你的採礦達到 165，可以自己用 {i:3575:inv_ingot_iron:Iron Bar} 和 {i:3857:inv_ore_tin_01:Coal} 熔煉 {i:3859:inv_ingot_steel:Steel Bars}。煤在每座主城鍛造訓練師旁邊的鍛造供應商有出售。",
  ["Alliance players should keep 6 of these. You might need them if you choose Armorsmithing."] = "聯盟玩家應保留其中 6 個。如果你選擇護甲鍛造，可能會用到。",
  ["17x {s:9931:inv_pants_04:Mithril Plate Pants} - 204 Mithril Bar"] = "17x {s:9931:inv_pants_04:Mithril Plate Pants} - 204 秘銀錠",
  ["I recommend these over the Heavy Mithril Gauntlets because they sell for more than three times as much to a vendor, so they end up cheaper."] = "我推薦做這個而不是重型秘銀護手，因為它賣給商人的價格是三倍以上，算下來反而更便宜。",
  ["6x {s:9993:inv_axe_14:Heavy Mithril Axe} - 72 Mithril Bar, 12 Citrine, 6 Solid Grinding Stone, 24 Heavy Leather"] = "6x {s:9993:inv_axe_14:Heavy Mithril Axe} - 72 秘銀錠、12 黃水晶、6 堅固磨刀石、24 重皮",
  ["Keep 2 of these. You might need them if you choose Weaponsmithing."] = "保留其中 2 個。如果你選擇武器鍛造，可能會用到。",
  ["Blacksmithing Specializations"] = "鍛造專精",
  ["At {b}Blacksmithing 200{/b} and {b}level 40{/b}, you can specialize in Armorsmithing or Weaponsmithing to craft powerful armor or weapons. Choosing one is optional, you don't need it to level Blacksmithing, and you can choose later too."] = "在{b}鍛造 200{/b}和{b}等級 40{/b}時，你可以專精護甲鍛造或武器鍛造，打造強大的護甲或武器。專精是可選的，升級鍛造不需要它，你也可以之後再選。",
  ["For information on how to become an Armorsmith or a Weaponsmith, please see my separate guides:"] = "關於如何成為護甲鍛造師或武器鍛造師，請參閱我的獨立指南：",
  ["Artisan Blacksmithing (215-300)"] = "工匠鍛造 (215-300)",
  ["To train past 225, visit {n:0::Brikk Keencraft} in Booty Bay, Stranglethorn Vale and learn Artisan Blacksmithing. You need {b}Blacksmithing 200{/b} and {b}level 35{/b}, and both factions learn it there."] = "要學習 225 以上，請找荊棘谷藏寶海灣的 {n:0::Brikk Keencraft} 學習工匠鍛造。你需要{b}鍛造 200{/b}和{b}等級 35{/b}，兩個陣營都在那裡學習。",
  ["{i:7989:inv_scroll_06:Plans: Mithril Spurs} is a world drop. If you already have it, you can use the {b}Mithril Spurs{/b} tab instead."] = "{i:7989:inv_scroll_06:Plans: Mithril Spurs} 是世界掉落。如果你已經有了，可以改用{b}秘銀馬刺{/b}分頁。",
  ["Heavy Mithril"] = "重型秘銀",
  ["Mithril Spurs"] = "秘銀馬刺",
  ["10x {s:9959:inv_chest_plate10:Heavy Mithril Breastplate} - 160 Mithril Bar"] = "10x {s:9959:inv_chest_plate10:Heavy Mithril Breastplate} - 160 秘銀錠",
  ["Keep 2 of these. You might need them if you choose Armorsmithing."] = "保留其中 2 個。如果你選擇護甲鍛造，可能會用到。",
  ["5x {s:16641:inv_stone_sharpeningstone_05:Dense Sharpening Stone} - 5 Dense Stone"] = "5x {s:16641:inv_stone_sharpeningstone_05:Dense Sharpening Stone} - 5 緻密的石頭",
  ["16x {s:9968:inv_boots_plate_01:Heavy Mithril Boots} - 224 Mithril Bar, 64 Thick Leather"] = "16x {s:9968:inv_boots_plate_01:Heavy Mithril Boots} - 224 秘銀錠、64 厚皮",
  ["5x {s:16647:inv_belt_01:Imperial Plate Belt} - 110 Thorium Bar, 30 Rugged Leather, 5 Aquamarine"] = "5x {s:16647:inv_belt_01:Imperial Plate Belt} - 110 瑟銀錠、30 硬甲皮、5 海藍寶石",
  ["You can get the recipe from the {q:7653::Imperial Plate Belt} quest (Requires {b}level 50{/b}) in Tanaris from {n:14567::Derotain Mudsipper}. You will need 20 Thorium Bar to complete it. Do his {q:7652::A Blue Light Bargain} quest first, it unlocks the Imperial Plate quests."] = "你可以從塔納利斯的 {n:14567::Derotain Mudsipper} 接取 {q:7653::Imperial Plate Belt} 任務（需要{b}等級 50{/b}）來取得配方。你需要 20 個瑟銀錠來完成它。請先完成他的 {q:7652::A Blue Light Bargain} 任務，它會解鎖帝國板甲系列任務。",
  ["{b}The next three recipes are also from the same NPC{/b}, so make sure to bring at least 140 Thorium Bar with you to get all 4 recipes."] = "{b}接下來三個配方也來自同一位 NPC{/b}，所以請至少帶 140 個瑟銀錠，以取得全部 4 個配方。",
  ["If you have the plans for one of these world drops, you can make it from 240 instead:"] = "如果你有以下其中一種世界掉落的設計圖，可以從 240 開始改做它：",
  ["240-255: 27x {s:10005:inv_sword_30:Dazzling Mithril Rapier} - 378 Mithril Bar, 27 Aquamarine, 54 Lesser Moonstone, 54 Moss Agate, 27 Solid Grinding Stone, 54 Mageweave Cloth"] = "240-255: 27x {s:10005:inv_sword_30:Dazzling Mithril Rapier} - 378 秘銀錠、27 海藍寶石、54 次級月亮石、54 苔蘚瑪瑙、27 堅固磨刀石、54 魔紋布",
  ["240-255: 20x {s:10009:inv_hammer_17:Runed Mithril Hammer} - 360 Mithril Bar, 40 Core of Earth, 20 Solid Grinding Stone, 80 Thick Leather"] = "240-255: 20x {s:10009:inv_hammer_17:Runed Mithril Hammer} - 360 秘銀錠、40 大地之核、20 堅固磨刀石、80 厚皮",
  ["240-255: 17x {s:16644:inv_bracer_13:Thorium Bracers} - 204 Thorium Bar, 68 Blue Power Crystal"] = "240-255: 17x {s:16644:inv_bracer_13:Thorium Bracers} - 204 瑟銀錠、68 藍色能量水晶",
  ["10x {s:9964:ability_rogue_sprint:Mithril Spurs} - 40 Mithril Bar, 30 Solid Grinding Stone (120 Solid Stone)"] = "10x {s:9964:ability_rogue_sprint:Mithril Spurs} - 40 秘銀錠、30 堅固磨刀石（120 堅固的石頭）",
  ["33x {s:9964:ability_rogue_sprint:Mithril Spurs} - 132 Mithril Bar, 99 Solid Grinding Stone (396 Solid Stone)"] = "33x {s:9964:ability_rogue_sprint:Mithril Spurs} - 132 秘銀錠、99 堅固磨刀石（396 堅固的石頭）",
  ["{b}The next three recipes all come from one NPC in Tanaris{/b}, so make sure to bring at least 120 Thorium Bar with you to get all 3 recipes."] = "{b}接下來三個配方都來自塔納利斯的同一位 NPC{/b}，所以請至少帶 120 個瑟銀錠，以取得全部 3 個配方。",
  ["27x {s:16649:inv_bracer_19:Imperial Plate Bracers} - 540 Thorium Bar, 27 Star Ruby"] = "27x {s:16649:inv_bracer_19:Imperial Plate Bracers} - 540 瑟銀錠、27 星辰紅寶石",
  ["You get the recipe from the {q:7655::Imperial Plate Bracer} quest (Requires {b}level 50{/b}) in Tanaris from {n:14567::Derotain Mudsipper}. You will need 20 Thorium Bar to complete it."] = "你可以從塔納利斯的 {n:14567::Derotain Mudsipper} 接取 {q:7655::Imperial Plate Bracer} 任務（需要{b}等級 50{/b}）來取得配方。你需要 20 個瑟銀錠來完成它。",
  ["20x {s:16657:inv_boots_plate_01:Imperial Plate Boots} - 680 Thorium Bar, 20 Star Ruby, 20 Aquamarine"] = "20x {s:16657:inv_boots_plate_01:Imperial Plate Boots} - 680 瑟銀錠、20 星辰紅寶石、20 海藍寶石",
  ["You get the recipe from the {q:7654::Imperial Plate Boots} quest, it needs 40 Thorium Bar."] = "你可以從 {q:7654::Imperial Plate Boots} 任務取得配方，需要 40 個瑟銀錠。",
  ["{b}Note:{/b} It wasn't possible to level this far on the beta, so this part only relies on the data I found in the game files. There might be more recipes we haven't discovered yet, but if there is nothing else, these are the only recipes you can use to level until 300."] = "{b}注意：{/b}在測試版上無法升到這麼高，所以這部分只依據我在遊戲檔案中找到的資料。可能還有我們尚未發現的配方，但如果沒有其他配方，這些就是升到 300 唯一能用的配方。",
  ["10x {s:16730:inv_pants_04:Imperial Plate Leggings} - 440 Thorium Bar, 20 Star Ruby"] = "10x {s:16730:inv_pants_04:Imperial Plate Leggings} - 440 瑟銀錠、20 星辰紅寶石",
  ["You get the recipe from the {q:7658::Imperial Plate Leggings} quest, it needs 60 Thorium Bar."] = "你可以從 {q:7658::Imperial Plate Leggings} 任務取得配方，需要 60 個瑟銀錠。",
  ["This WoW Forever Enchanting leveling guide will show you the fastest and cheapest way to level your Enchanting skill from 1 to 300. You will also find every trainer location and where to train Enchanting past 75, 150 and 225."] = "這份 WoW Forever 附魔升級指南將告訴你如何以最快、最省錢的方式將附魔技能從 1 升到 300。你也能找到每位訓練師的位置，以及在 75、150 和 225 之後要去哪裡繼續學習附魔。",
  ["Enchanting goes well with Tailoring because you don't need a gathering profession for either of them, and you can disenchant the items you made with Tailoring. Below you will find the shopping list, the Enchanting trainers by starting zone and capital city, and the cheapest enchants for every skill range. Forever added a few new low level recipes, so the first 70 points are cheaper than in Classic."] = "附魔很適合搭配裁縫，因為兩者都不需要採集專業，而且你可以分解用裁縫做出來的物品。下方有購物清單、依新手區與主城分類的附魔訓練師，以及每個技能區間最便宜的附魔。Forever 新增了一些低等級配方，所以前 70 點比經典版更便宜。",
  ["An alternative replaces the whole row, so buy the one that is cheaper."] = "替代方案會取代整列，所以請買比較便宜的那個。",
  ["Enchanting Trainer Locations"] = "附魔訓練師位置",
  ["Apprentice Enchanting has no level requirement in Forever, so you can learn it on a fresh character."] = "在 Forever 中學習學徒附魔沒有等級需求，所以新角色也能學。",
  ["Orgrimmar: {n:0:horde:Jhag}"] = "奧格瑪：{n:0:horde:Jhag}",
  ["Undercity: {n:0:horde:Malcomb Wynn}"] = "幽暗城：{n:0:horde:Malcomb Wynn}",
  ["Thunder Bluff: {n:0:horde:Mot Dawnstrider}"] = "雷霆崖：{n:0:horde:Mot Dawnstrider}",
  ["{n:0:horde:Pa'zula} in Sen'jin Village"] = "森金村的 {n:0:horde:Pa'zula}",
  ["There is no Enchanting trainer in Mulgore, go to {n:0:horde:Mot Dawnstrider} on the middle rise in Thunder Bluff"] = "莫高雷沒有附魔訓練師，請去雷霆崖中間高台找 {n:0:horde:Mot Dawnstrider}",
  ["{n:0:horde:Vance Undergloom} upstairs in the inn in Brill"] = "布瑞爾旅店樓上的 {n:0:horde:Vance Undergloom}",
  ["{n:0::Eaysaa Brightgust} in Valanaar, {n:0::Nasalanna Windsinger} in Shen'dar Village"] = "瓦拉納爾的 {n:0::Eaysaa Brightgust}，申達爾村的 {n:0::Nasalanna Windsinger}",
  ["Stormwind City: {n:0:alliance:Betty Quin}"] = "暴風城：{n:0:alliance:Betty Quin}",
  ["Ironforge: {n:0:alliance:Thonys Pillarstone}"] = "鐵爐堡：{n:0:alliance:Thonys Pillarstone}",
  ["Darnassus: {n:0:alliance:Lalina Summermoon}"] = "達納蘇斯：{n:0:alliance:Lalina Summermoon}",
  ["There is no Enchanting trainer in Elwynn Forest, go to {n:0:alliance:Betty Quin} in the Mage Quarter in Stormwind City"] = "艾爾文森林沒有附魔訓練師，請去暴風城法師區找 {n:0:alliance:Betty Quin}",
  ["There is no Enchanting trainer in Dun Morogh, go to {n:0:alliance:Thonys Pillarstone} at the Great Forge in Ironforge"] = "丹莫洛沒有附魔訓練師，請去鐵爐堡大鍛爐找 {n:0:alliance:Thonys Pillarstone}",
  ["{n:0:alliance:Alanna Raveneye} at the Oracle Glade, in the north-west of Teldrassil"] = "泰達希爾西北部神諭林地的 {n:0:alliance:Alanna Raveneye}",
  ["You can find every Enchanting trainer for Horde and Alliance on my WoW Forever Enchanting Trainers page."] = "你可以在我的 WoW Forever 附魔訓練師頁面找到部落和聯盟的所有附魔訓練師。",
  ["Enchanting Macro for Faster Leveling"] = "加快升級的附魔巨集",
  ["I highly recommend using this macro to speed up the leveling process."] = "我強烈建議使用這個巨集來加快升級速度。",
  ["This macro presses the Create button for you and confirms the prompt that asks if you want to replace the enchant already on the item, without any extra clicks."] = "這個巨集會幫你按下製作按鈕，並確認詢問是否要取代物品上現有附魔的提示，不需要額外點擊。",
  ["Macro"] = "巨集",
  ["If you have never made a macro, type /m in the chat and press Enter, click New, give it a name and paste these two lines into it."] = "如果你從沒做過巨集，在聊天框輸入 /m 並按 Enter，點擊新增，取個名字，然後把這兩行貼進去。",
  ["How to Use"] = "使用方法",
  ["Place the macro on your action bar"] = "把巨集放到快捷列上",
  ["Open your Enchanting profession window"] = "打開附魔專業視窗",
  ["Select the enchant you want to craft (make sure it's the right one)"] = "選擇你要製作的附魔（確認選對了）",
  ["Put the item you want to enchant into the optional target slot"] = "把要附魔的物品放進可選的目標欄位",
  ["Press the macro repeatedly"] = "重複按下巨集",
  ["Disenchanting"] = "分解",
  ["You get {s:13262:inv_enchant_disenchant:Disenchant} together with Apprentice Enchanting. In WoW Forever {b}Disenchant is not in your spellbook{/b}, it's in the Enchanting box of the Professions window."] = "學會學徒附魔時你會一併獲得 {s:13262:inv_enchant_disenchant:Disenchant}。在 WoW Forever 中，{b}分解不在你的法術書裡{/b}，而是在專業視窗的附魔欄位中。",
  ["If you are looking for the disenchanting table, it's in my disenchanting guide, and if you can't find the Disenchant button, the guide shows it with pictures:"] = "如果你在找分解對照表，它在我的分解指南裡；如果你找不到分解按鈕，指南中有圖片說明：",
  ["Apprentice Enchanting (1-70)"] = "學徒附魔 (1-70)",
  ["1x {s:7421:inv_staff_goldfeathered_01:Runed Copper Rod} - 1 Copper Rod, 1 Mote of Magic"] = "1x {s:7421:inv_staff_goldfeathered_01:Runed Copper Rod} - 1 銅棒、1 魔法微粒",
  ["The {i:6217:inv_misc_flute_01:Copper Rod} and the {i:247786:inv_elemental_mote_mana:Mote of Magic} are sold by the Enchanting Supply vendor near your trainer, don't buy them from the Auction House."] = "{i:6217:inv_misc_flute_01:Copper Rod} 和 {i:247786:inv_elemental_mote_mana:Mote of Magic} 由訓練師附近的附魔供應商出售，不要在拍賣場購買。",
  ["{b}If you are leveling in a starting zone with a low level character{/b}, you can buy the Copper Rod from a trade vendor there, but the Mote of Magic is only sold by Enchanting vendors. In the starting zones only the trainers on {b}Zephras Isle{/b} and in {b}Tirisfal Glades{/b} (Brill) sell it, everyone else has to visit the trainer in the capital city, the vendor stands right next to them."] = "{b}如果你用低等級角色在新手區升級{/b}，可以在當地的商業商人購買銅棒，但魔法微粒只有附魔商人出售。新手區中只有{b}澤弗拉斯島{/b}和{b}提里斯法林地{/b}（布瑞爾）的訓練師有賣，其他人都得去主城的訓練師那裡，商人就站在旁邊。",
  ["18x {s:7418:spell_holy_greaterheal:Enchant Bracer - Inferior Stamina} - 18 Mote of Magic"] = "18x {s:7418:spell_holy_greaterheal:Enchant Bracer - Inferior Stamina} - 18 魔法微粒",
  ["Make one of these:"] = "製作以下其中一種：",
  ["50x {s:7420:spell_holy_greaterheal:Enchant Chest - Inferior Stamina} - 50 Strange Dust"] = "50x {s:7420:spell_holy_greaterheal:Enchant Chest - Inferior Stamina} - 50 奇異之塵",
  ["50x {s:7428:spell_holy_greaterheal:Enchant Bracer - Minor Deflect} - 50 Lesser Magic Essence"] = "50x {s:7428:spell_holy_greaterheal:Enchant Bracer - Minor Deflect} - 50 次級魔法精華",
  ["A {i:10939:inv_enchant_essencemagiclarge:Greater Magic Essence} turns into 3 Lesser Magic Essence when you right-click it in your bags, so you can buy those too."] = "在背包中右鍵點擊 {i:10939:inv_enchant_essencemagiclarge:Greater Magic Essence} 會變成 3 個次級魔法精華，所以你也可以買這個。",
  ["Journeyman Enchanting (70-150)"] = "熟手附魔 (70-150)",
  ["To train past 75, visit one of these trainers and learn Journeyman Enchanting. You need {b}Enchanting 50{/b} and {b}level 10{/b}:"] = "要學習 75 以上，請找以下任一位訓練師學習熟手附魔。你需要{b}附魔 50{/b}和{b}等級 10{/b}：",
  ["Orgrimmar: {n:0:horde:Godan}"] = "奧格瑪：{n:0:horde:Godan}",
  ["Undercity: {n:0:horde:Lavinia Crowe}"] = "幽暗城：{n:0:horde:Lavinia Crowe}",
  ["Thunder Bluff: {n:0:horde:Teg Dawnstrider}"] = "雷霆崖：{n:0:horde:Teg Dawnstrider}",
  ["Stormwind City: {n:0:alliance:Lucan Cordell}"] = "暴風城：{n:0:alliance:Lucan Cordell}",
  ["Ironforge: {n:0:alliance:Gimble Thistlefuzz}"] = "鐵爐堡：{n:0:alliance:Gimble Thistlefuzz}",
  ["Darnassus: {n:0:alliance:Taladan}"] = "達納蘇斯：{n:0:alliance:Taladan}",
  ["If you bought Strange Dust pick the {b}Strange Dust{/b} tab, if you bought Lesser Magic Essence pick the {b}Lesser Magic Essence{/b} tab."] = "如果你買的是奇異之塵，請選{b}奇異之塵{/b}分頁；如果你買的是次級魔法精華，請選{b}次級魔法精華{/b}分頁。",
  ["Strange Dust"] = "奇異之塵",
  ["Lesser Magic Essence"] = "次級魔法精華",
  ["49x {s:7426:spell_holy_greaterheal:Enchant Chest - Minor Absorption} - 49 Lesser Magic Essence"] = "49x {s:7426:spell_holy_greaterheal:Enchant Chest - Minor Absorption} - 49 次級魔法精華",
  ["1x {s:7795:inv_staff_01:Runed Silver Rod} - 1 Silver Rod, 3 Strange Dust, 4 Lesser Magic Essence, 1 Shadowgem"] = "1x {s:7795:inv_staff_01:Runed Silver Rod} - 1 銀棒、3 奇異之塵、4 次級魔法精華、1 暗影石",
  ["{i:6338:inv_staff_01:Silver Rod} and every other rod in this guide (Golden, Truesilver, Arcanite) is made by Blacksmiths, you can buy them from the Auction House."] = "{i:6338:inv_staff_01:Silver Rod} 以及本指南中的其他棒子（金棒、真銀棒、奧金棒）都是由鍛造師製作，你可以在拍賣場購買。",
  ["23x {s:14807:inv_staff_07:Greater Magic Wand} - 23 Simple Wood, 46 Lesser Magic Essence"] = "23x {s:14807:inv_staff_07:Greater Magic Wand} - 23 簡易木材、46 次級魔法精華",
  ["37x {s:7793:spell_holy_greaterheal:Enchant 2H Weapon - Lesser Intellect} - 148 Lesser Magic Essence"] = "37x {s:7793:spell_holy_greaterheal:Enchant 2H Weapon - Lesser Intellect} - 148 次級魔法精華",
  ["{i:6349:inv_misc_note_01:Formula: Enchant 2H Weapon - Lesser Intellect} is sold by these vendors:"] = "{i:6349:inv_misc_note_01:Formula: Enchant 2H Weapon - Lesser Intellect} 由以下商人出售：",
  ["{n:0:horde:Kithas} in Orgrimmar"] = "奧格瑪的 {n:0:horde:Kithas}",
  ["{n:0:horde:Nata Dawnstrider} in Thunder Bluff"] = "雷霆崖的 {n:0:horde:Nata Dawnstrider}",
  ["{n:0:horde:Leo Sarn} in Silverpine Forest"] = "銀松森林的 {n:0:horde:Leo Sarn}",
  ["{n:0:alliance:Tilli Thistlefuzz} in Ironforge"] = "鐵爐堡的 {n:0:alliance:Tilli Thistlefuzz}",
  ["Buy {i:20752:inv_misc_note_01:Formula: Minor Mana Oil} and {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil} from them too, you will need them at 150 and 200."] = "也順便向他們購買 {i:20752:inv_misc_note_01:Formula: Minor Mana Oil} 和 {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil}，150 和 200 時會用到。",
  ["If you don't want to get the formula, make this:"] = "如果你不想取得這個公式，就製作這個：",
  ["25x {s:7863:spell_holy_greaterheal:Enchant Boots - Minor Stamina} - 100 Strange Dust"] = "25x {s:7863:spell_holy_greaterheal:Enchant Boots - Minor Stamina} - 100 奇異之塵",
  ["23x {s:7420:spell_holy_greaterheal:Enchant Chest - Inferior Stamina} - 23 Strange Dust"] = "23x {s:7420:spell_holy_greaterheal:Enchant Chest - Inferior Stamina} - 23 奇異之塵",
  ["15x {s:7457:spell_holy_greaterheal:Enchant Bracer - Minor Stamina} - 30 Strange Dust"] = "15x {s:7457:spell_holy_greaterheal:Enchant Bracer - Minor Stamina} - 30 奇異之塵",
  ["9x {s:7771:spell_holy_greaterheal:Enchant Cloak - Minor Protection} - 18 Strange Dust"] = "9x {s:7771:spell_holy_greaterheal:Enchant Cloak - Minor Protection} - 18 奇異之塵",
  ["32x {s:7771:spell_holy_greaterheal:Enchant Cloak - Minor Protection} - 64 Strange Dust"] = "32x {s:7771:spell_holy_greaterheal:Enchant Cloak - Minor Protection} - 64 奇異之塵",
  ["20x {s:7863:spell_holy_greaterheal:Enchant Boots - Minor Stamina} - 80 Strange Dust"] = "20x {s:7863:spell_holy_greaterheal:Enchant Boots - Minor Stamina} - 80 奇異之塵",
  ["If 20 Soul Dust cost less than 80 Strange Dust, make this:"] = "如果 20 個靈魂之塵比 80 個奇異之塵便宜，就製作這個：",
  ["20x {s:13501:spell_holy_greaterheal:Enchant Bracer - Lesser Stamina} - 20 Soul Dust."] = "20x {s:13501:spell_holy_greaterheal:Enchant Bracer - Lesser Stamina} - 20 靈魂之塵。",
  ["Expert Enchanting (150-225)"] = "專家附魔 (150-225)",
  ["To train past 150, visit one of these trainers and learn Expert Enchanting. You need {b}Enchanting 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "要學習 150 以上，請找以下任一位訓練師學習專家附魔。你需要{b}附魔 125{/b}和{b}等級 20{/b}，費用為 50 銀幣。",
  ["There is only one Expert Enchanting trainer for each faction. {n:0:horde:Hgarth} in Stonetalon Mountains at Sun Rock Retreat is the Horde trainer, he is up on the hill above the village. {n:0:alliance:Kitta Firewind} in Elwynn Forest is the Alliance trainer, she is at the top of the Tower of Azora."] = "每個陣營只有一位專家附魔訓練師。部落訓練師是石爪山脈烈日石居的 {n:0:horde:Hgarth}，他在村莊上方的山丘上。聯盟訓練師是艾爾文森林的 {n:0:alliance:Kitta Firewind}，她在阿佐拉之塔的頂樓。",
  ["1x {s:13628:inv_staff_10:Runed Golden Rod} - 1 Golden Rod, 1 Iridescent Pearl, 1 Greater Astral Essence, 1 Soul Dust"] = "1x {s:13628:inv_staff_10:Runed Golden Rod} - 1 金棒、1 彩虹珍珠、1 強效星界精華、1 靈魂之塵",
  ["16x {s:25125:inv_potion_98:Minor Mana Oil} - 16 Soul Dust, 32 Maple Seed, 16 Leaded Vial"] = "16x {s:25125:inv_potion_98:Minor Mana Oil} - 16 靈魂之塵、32 楓樹種子、16 鉛瓶",
  ["{i:20752:inv_misc_note_01:Formula: Minor Mana Oil} is sold by these vendors:"] = "{i:20752:inv_misc_note_01:Formula: Minor Mana Oil} 由以下商人出售：",
  ["{n:0:horde:Thaddeus Webb} in Undercity"] = "幽暗城的 {n:0:horde:Thaddeus Webb}",
  ["{n:0:alliance:Vaean} in Darnassus"] = "達納蘇斯的 {n:0:alliance:Vaean}",
  ["{n:0:alliance:Jessara Cordell} in Stormwind City"] = "暴風城的 {n:0:alliance:Jessara Cordell}",
  ["Buy {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil} from them too, you will need it at 200."] = "也順便向他們購買 {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil}，200 時會用到。",
  ["{i:17034:inv_misc_food_02:Maple Seed} is sold by Reagent vendors and {i:3372:inv_potion_85:Leaded Vial} by Alchemy Supply vendors."] = "{i:17034:inv_misc_food_02:Maple Seed} 由施法材料商出售，{i:3372:inv_potion_85:Leaded Vial} 由鍊金術供應商出售。",
  ["47x {s:13637:spell_holy_greaterheal:Enchant Boots - Lesser Agility} - 47 Soul Dust"] = "47x {s:13637:spell_holy_greaterheal:Enchant Boots - Lesser Agility} - 47 靈魂之塵",
  ["If 2 Vision Dust cost less than 3 Soul Dust, stop the boots at 185 and make this until 200:"] = "如果 2 個幻象之塵比 3 個靈魂之塵便宜，就在 185 停止做靴子，改做這個直到 200：",
  ["15x {s:13661:spell_holy_greaterheal:Enchant Bracer - Strength} - 15 Vision Dust."] = "15x {s:13661:spell_holy_greaterheal:Enchant Bracer - Strength} - 15 幻象之塵。",
  ["1x {s:13702:inv_staff_11:Runed Truesilver Rod} - 1 Truesilver Rod, 1 Black Pearl, 1 Greater Mystic Essence, 1 Vision Dust"] = "1x {s:13702:inv_staff_11:Runed Truesilver Rod} - 1 真銀棒、1 黑珍珠、1 強效秘法精華、1 幻象之塵",
  ["25x {s:25126:inv_potion_103:Lesser Wizard Oil} - 25 Vision Dust, 50 Stranglethorn Seed, 25 Leaded Vial"] = "25x {s:25126:inv_potion_103:Lesser Wizard Oil} - 25 幻象之塵、50 荊棘谷種子、25 鉛瓶",
  ["If you didn't buy {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil} yet, the vendors are listed at the 151-165 step above."] = "如果你還沒買 {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil}，賣家列在上方 151-165 的步驟中。",
  ["{i:17035:inv_misc_food_02:Stranglethorn Seed} is sold by Reagent vendors and {i:3372:inv_potion_85:Leaded Vial} by Alchemy Supply vendors."] = "{i:17035:inv_misc_food_02:Stranglethorn Seed} 由施法材料商出售，{i:3372:inv_potion_85:Leaded Vial} 由鍊金術供應商出售。",
  ["5x {s:13746:spell_holy_greaterheal:Enchant Cloak - Greater Defense} - 5 Vision Dust"] = "5x {s:13746:spell_holy_greaterheal:Enchant Cloak - Greater Defense} - 5 幻象之塵",
  ["Artisan Enchanting (225-300)"] = "工匠附魔 (225-300)",
  ["The Expert Enchanting trainers only teach you up to 225. To train Enchanting past 225 you need {b}level 35{/b} and {b}Enchanting 200{/b}, then learn Artisan Enchanting from Annora in Uldaman (I explain below how to find her). {b}She is the only trainer who teaches Artisan Enchanting.{/b}"] = "專家附魔訓練師只能教你到 225。要學習 225 以上的附魔，你需要{b}等級 35{/b}和{b}附魔 200{/b}，然後在奧達曼向 Annora 學習工匠附魔（下方會說明如何找到她）。{b}她是唯一教授工匠附魔的訓練師。{/b}",
  ["There are a few recipes only Annora teaches, {b}so bring enough gold to learn every recipe and enough materials to reach Enchanting 250{/b}, otherwise you have to go back to Uldaman for the higher recipes. Around 50 {i:11137:inv_enchant_dustvision:Vision Dust} gets you to 250."] = "有些配方只有 Annora 會教，{b}所以請帶足夠的金幣學會所有配方，以及足夠升到附魔 250 的材料{/b}，否則你得為了更高的配方再回奧達曼一趟。大約 50 個 {i:11137:inv_enchant_dustvision:Vision Dust} 就能讓你升到 250。",
  ["How to enter Uldaman"] = "如何進入奧達曼",
  ["Uldaman is in the Badlands and it has two entrances, use the back entrance. You can't solo it at level 35, so go with a party or ask a level 60 to help."] = "奧達曼位於荒蕪之地，有兩個入口，請走後門入口。35 級無法單刷，所以請組隊或找一位 60 級玩家幫忙。",
  ["How to find Annora"] = "如何找到 Annora",
  ["Annora only spawns once you {b}kill every mob in the area she is in!{/b}"] = "{b}必須殺光她所在區域的所有怪物{/b}，Annora 才會出現！",
  ["{b}Don't forget to learn everything from Annora before you leave Uldaman!{/b} The recipes from 230 up are taught nowhere else."] = "{b}離開奧達曼前別忘了向 Annora 學會所有東西！{/b}230 以上的配方其他地方都學不到。",
  ["Recipe"] = "配方",
  ["Skill"] = "技能",
  ["Cost"] = "費用",
  ["{b}Artisan Enchanting{/b}"] = "{b}工匠附魔{/b}",
  ["37x {s:13815:spell_holy_greaterheal:Enchant Gloves - Agility} - 37 Vision Dust"] = "37x {s:13815:spell_holy_greaterheal:Enchant Gloves - Agility} - 37 幻象之塵",
  ["20x {s:25127:inv_potion_99:Lesser Mana Oil} - 20 Dream Dust, 20 Purple Lotus, 20 Crystal Vial"] = "20x {s:25127:inv_potion_99:Lesser Mana Oil} - 20 夢境之塵、20 紫蓮花、20 水晶瓶",
  ["{i:20754:inv_misc_note_01:Formula: Lesser Mana Oil} is sold by {n:0::Kania} in Silithus, she is upstairs in the inn. {i:8925:inv_potion_86:Crystal Vial} is sold by {n:0::Mishta} in Silithus or any Alchemy Supply vendor."] = "{i:20754:inv_misc_note_01:Formula: Lesser Mana Oil} 由希利蘇斯的 {n:0::Kania} 出售，她在旅店樓上。{i:8925:inv_potion_86:Crystal Vial} 由希利蘇斯的 {n:0::Mishta} 或任何鍊金術供應商出售。",
  ["If you don't have Purple Lotus, make {s:13939:spell_holy_greaterheal:Enchant Bracer - Greater Strength} instead (1 Dream Dust, 2 Lesser Nether Essence each), Annora teaches it."] = "如果你沒有紫蓮花，就改做 {s:13939:spell_holy_greaterheal:Enchant Bracer - Greater Strength}（每個 1 夢境之塵、2 次級虛空精華），Annora 會教這個。",
  ["40x {s:20017:spell_holy_greaterheal:Enchant Shield - Greater Stamina} - 240 Dream Dust"] = "40x {s:20017:spell_holy_greaterheal:Enchant Shield - Greater Stamina} - 240 夢境之塵",
  ["{i:16217:inv_misc_note_01:Formula: Enchant Shield - Greater Stamina} is sold by {n:0:horde:Daniel Bartlett} in Undercity and {n:0:alliance:Mythrin'dir} in Darnassus. It's bind on pickup, so don't buy it on an alt."] = "{i:16217:inv_misc_note_01:Formula: Enchant Shield - Greater Stamina} 由幽暗城的 {n:0:horde:Daniel Bartlett} 和達納蘇斯的 {n:0:alliance:Mythrin'dir} 出售。它是拾取綁定，所以不要用分身購買。",
  ["From 290 you can make the Runed Arcanite Rod, see the next step."] = "從 290 開始你可以製作符文奧金棒，請看下一步。",
  ["1x {s:20051:inv_wand_09:Runed Arcanite Rod} - 1 Arcanite Rod, 1 Golden Pearl, 10 Illusion Dust, 4 Greater Eternal Essence, 4 Small Brilliant Shard, 2 Large Brilliant Shard"] = "1x {s:20051:inv_wand_09:Runed Arcanite Rod} - 1 奧金棒、1 金珍珠、10 幻影之塵、4 強效不滅精華、4 小塊燦爛碎片、2 大塊燦爛碎片",
  ["{i:16243:inv_misc_note_01:Formula: Runed Arcanite Rod} is sold by {n:0::Lorelae Wintersong} in Moonglade at Nighthaven."] = "{i:16243:inv_misc_note_01:Formula: Runed Arcanite Rod} 由月光林地永夜港的 {n:0::Lorelae Wintersong} 出售。",
  ["{b}You need this rod for some recipes from 290 and for most recipes at 300{/b}, Crusader for example. You can make it from 290, but if you don't need it yet, you can make it later and make one more Shield for the last point instead."] = "{b}290 起的部分配方以及 300 的大多數配方都需要這根棒子{/b}，例如十字軍。你從 290 就能製作它，但如果暫時還用不到，可以之後再做，最後一點改為多做一個盾牌附魔即可。",
  ["This WoW Forever Engineering leveling guide will show you the fastest and cheapest way to level your Engineering skill from 1 to 300. You will also find every trainer location and where to train Engineering past 75, 150 and 225."] = "這份 WoW Forever 工程學升級指南將告訴你如何以最快、最省錢的方式將工程學技能從 1 升到 300。你也能找到每位訓練師的位置，以及在 75、150 和 225 之後要去哪裡繼續學習工程學。",
  ["Engineering is best combined with Mining, because almost everything you make needs stone and bars, and you can mine both. If you don't have Mining, you have to buy everything from the Auction House. Below you will find the shopping list, the Engineering trainers by starting zone and capital city, and the cheapest recipes for every skill range."] = "工程學最適合搭配採礦，因為你製作的幾乎所有東西都需要石頭和金屬錠，而這兩者你都能自己挖。如果你沒有採礦，就得全部從拍賣場購買。下方有購物清單、依新手區與主城分類的工程學訓練師，以及每個技能區間最便宜的配方。",
  ["Engineering Trainer Locations"] = "工程學訓練師位置",
  ["Apprentice Engineering has no level requirement in Forever, so you can learn it on a fresh character."] = "在 Forever 中學習學徒工程學沒有等級需求，所以新角色也能學。",
  ["There is no Engineering trainer in Thunder Bluff and Darnassus, the other four capitals have one. You can also ask a guard, then it will be marked with a red flag on your map."] = "雷霆崖和達納蘇斯沒有工程學訓練師，其他四座主城都有。你也可以詢問衛兵，地圖上就會用紅旗標出位置。",
  ["Orgrimmar: {n:0:horde:Thund}"] = "奧格瑪：{n:0:horde:Thund}",
  ["Undercity: {n:0:horde:Graham Van Talen}"] = "幽暗城：{n:0:horde:Graham Van Talen}",
  ["{n:0:horde:Mukdrak} in Razor Hill, near the forge next to the road to Orgrimmar"] = "剃刀嶺的 {n:0:horde:Mukdrak}，在通往奧格瑪道路旁的鍛爐附近",
  ["{n:0::Twizwick Sprocketgrind} on the plateau above the Venture Co. Mine, hard to reach at low level. There is no anvil near him and nobody there sells the Blacksmith Hammer, so it's probably best to go to {n:0:horde:Thund} in Orgrimmar instead."] = "風險投資公司礦坑上方高地的 {n:0::Twizwick Sprocketgrind}，低等級時很難到達。他附近沒有鐵砧，那裡也沒人賣鍛造錘，所以最好還是去奧格瑪找 {n:0:horde:Thund}。",
  ["There is no Engineering trainer in Tirisfal Glades, go to {n:0:horde:Graham Van Talen} in the Rogues' Quarter in Undercity"] = "提里斯法林地沒有工程學訓練師，請去幽暗城盜賊區找 {n:0:horde:Graham Van Talen}",
  ["{n:0::Strange Hermit} in Shadowgale Forest"] = "影風森林的 {n:0::Strange Hermit}",
  ["Stormwind City: {n:0:alliance:Sprite Jumpsprocket}"] = "暴風城：{n:0:alliance:Sprite Jumpsprocket}",
  ["Ironforge: {n:0:alliance:Jemma Quikswitch}"] = "鐵爐堡：{n:0:alliance:Jemma Quikswitch}",
  ["There is no Engineering trainer in Elwynn Forest, go to {n:0:alliance:Sprite Jumpsprocket} in the Dwarven District in Stormwind City"] = "艾爾文森林沒有工程學訓練師，請去暴風城矮人區找 {n:0:alliance:Sprite Jumpsprocket}",
  ["{n:0:alliance:Bronk Guzzlegear} at Steelgrill's Depot"] = "鋼架補給站的 {n:0:alliance:Bronk Guzzlegear}",
  ["There is no Engineering trainer in Teldrassil or Darnassus, the closest one is {n:0:alliance:Jenna Lemkenilli} in Auberdine in Darkshore"] = "泰達希爾和達納蘇斯沒有工程學訓練師，最近的是黑海岸奧伯丁的 {n:0:alliance:Jenna Lemkenilli}",
  ["You can find every Engineering trainer for Horde and Alliance on my WoW Forever Engineering Trainers page."] = "你可以在我的 WoW Forever 工程學訓練師頁面找到部落和聯盟的所有工程學訓練師。",
  ["Apprentice Engineering (1-50)"] = "學徒工程學 (1-50)",
  ["Buy a {i:5956:inv_hammer_20:Blacksmith Hammer}, most recipes need it. {b}Most trainers{/b} have a Blacksmithing or Engineering Supply vendor nearby that sells it, {b}except{/b} the trainers in Dun Morogh and on Zephras Isle. In Dun Morogh buy it in Kharanos from {n:0:alliance:Thrawn Boltar}, on Zephras Isle in Shen'dar Village from {n:0::Aedi Thriceforged}."] = "買一把 {i:5956:inv_hammer_20:Blacksmith Hammer}，大多數配方都需要它。{b}大多數訓練師{/b}附近都有出售它的鍛造或工程學供應商，{b}除了{/b}丹莫洛和澤弗拉斯島的訓練師。在丹莫洛請到卡拉諾斯向 {n:0:alliance:Thrawn Boltar} 購買，在澤弗拉斯島請到申達爾村向 {n:0::Aedi Thriceforged} 購買。",
  ["The {b}Gnome{/b} racial changed in Forever. Instead of +15 Engineering skill, Engineering Specialization now makes your devices fail or backfire 20% less often, so Gnomes level Engineering exactly like everyone else."] = "{b}地精{/b}的種族天賦在 Forever 中有所改變。工程學專精不再提供 +15 工程學技能，而是讓你的裝置失效或反噬的機率降低 20%，所以地精升級工程學的方式和其他人完全一樣。",
  ["66x {s:3918:inv_misc_dust_01:Rough Blasting Powder} - 66 Rough Stone"] = "66x {s:3918:inv_misc_dust_01:Rough Blasting Powder} - 66 劣質的石頭",
  ["Keep all of them, you need 66 for the bombs at 51."] = "全部保留，51 製作炸彈時需要 66 個。",
  ["33x {s:3922:inv_misc_gear_06:Handful of Copper Bolts} - 33 Copper Bar"] = "33x {s:3922:inv_misc_gear_06:Handful of Copper Bolts} - 33 銅錠",
  ["Keep these too, you will need all 33 for the bombs."] = "這些也要保留，製作炸彈時 33 個全部都會用到。",
  ["1x {s:7430:inv_misc_wrench_01:Arclight Spanner} - 6 Copper Bar"] = "1x {s:7430:inv_misc_wrench_01:Arclight Spanner} - 6 銅錠",
  ["You will use this to craft Engineering recipes, so keep it."] = "製作工程學配方時會用到它，所以請保留。",
  ["Journeyman Engineering (50-150)"] = "熟手工程學 (50-150)",
  ["To train past 75, visit one of these trainers and learn Journeyman Engineering. You need {b}Engineering 50{/b} and {b}level 10{/b}:"] = "要學習 75 以上，請找以下任一位訓練師學習熟手工程學。你需要{b}工程學 50{/b}和{b}等級 10{/b}：",
  ["Orgrimmar: {n:0:horde:Nogg}"] = "奧格瑪：{n:0:horde:Nogg}",
  ["Undercity: {n:0:horde:Franklin Lloyd}"] = "幽暗城：{n:0:horde:Franklin Lloyd}",
  ["Stormwind City: {n:0:alliance:Lilliam Sparkspindle}"] = "暴風城：{n:0:alliance:Lilliam Sparkspindle}",
  ["Ironforge: {n:0:alliance:Trixie Quikswitch}"] = "鐵爐堡：{n:0:alliance:Trixie Quikswitch}",
  ["Duskwood: {n:0:alliance:Finbus Geargrind}"] = "暮色森林：{n:0:alliance:Finbus Geargrind}",
  ["33x {s:3923:inv_misc_bomb_09:Rough Copper Bomb} - 33 Copper Bar, 33 Handful of Copper Bolts, 66 Rough Blasting Powder, 33 Linen Cloth"] = "33x {s:3923:inv_misc_bomb_09:Rough Copper Bomb} - 33 銅錠、33 一把銅螺栓、66 劣質火藥、33 亞麻布",
  ["{b}It's possible that you reach further than 75 with these{/b}, so it's best not to afk craft them unless you already learned Journeyman Engineering. Either make sure you learn it first, or just don't afk craft them. (Depends on luck, sometimes you don't even reach 75.)"] = "{b}做這些有可能會超過 75{/b}，所以除非你已經學會熟手工程學，否則最好不要掛機製作。要嘛先確定學會了，要嘛就別掛機做。（看運氣，有時甚至到不了 75。）",
  ["60x {s:3929:inv_misc_dust_02:Coarse Blasting Powder} - 60 Coarse Stone"] = "60x {s:3929:inv_misc_dust_02:Coarse Blasting Powder} - 60 粗糙的石頭",
  ["Keep them, you will need all 60 for the dynamite at 90."] = "保留它們，90 製作炸藥時 60 個全部都會用到。",
  ["20x {s:3931:inv_misc_bomb_06:Coarse Dynamite} - 60 Coarse Blasting Powder, 20 Linen Cloth"] = "20x {s:3931:inv_misc_bomb_06:Coarse Dynamite} - 60 粗製火藥、20 亞麻布",
  ["5x {s:3973:inv_ingot_04:Silver Contact} - 5 Silver Bar"] = "5x {s:3973:inv_ingot_04:Silver Contact} - 5 銀錠",
  ["If Silver Bar is expensive, make this instead:"] = "如果銀錠很貴，就改做這個：",
  ["5x {s:3934:inv_helmet_47:Flying Tiger Goggles} - 30 Light Leather, 10 Tigerseye."] = "5x {s:3934:inv_helmet_47:Flying Tiger Goggles} - 30 輕皮、10 虎眼石。",
  ["25x {s:3938:inv_gizmo_pipe_01:Bronze Tube} - 50 Bronze Bar, 25 Weak Flux"] = "25x {s:3938:inv_gizmo_pipe_01:Bronze Tube} - 50 青銅錠、25 弱效助熔劑",
  ["Keep 10 of them, you will need them at 125."] = "保留其中 10 個，125 時會用到。",
  ["{i:2880:inv_misc_ammo_gunpowder_02:Weak Flux} is sold by Engineering Supply vendors near your trainer."] = "{i:2880:inv_misc_ammo_gunpowder_02:Weak Flux} 由訓練師附近的工程學供應商出售。",
  ["If you end up a few points short of 125, don't make more tubes, just start the scopes."] = "如果你離 125 還差幾點，不用再做管子，直接開始做瞄準鏡。",
  ["10x {s:3978:inv_misc_spyglass_02:Standard Scope} - 10 Bronze Tube, 10 Moss Agate"] = "10x {s:3978:inv_misc_spyglass_02:Standard Scope} - 10 青銅管、10 苔蘚瑪瑙",
  ["Start making {s:3945:inv_misc_dust_06:Heavy Blasting Powder} instead if you don't have any Moss Agate, or it's really expensive."] = "如果你沒有苔蘚瑪瑙或它非常貴，就改為開始製作 {s:3945:inv_misc_dust_06:Heavy Blasting Powder}。",
  ["Make both of these:"] = "這兩種都要做：",
  ["30x {s:3945:inv_misc_dust_06:Heavy Blasting Powder} - 30 Heavy Stone"] = "30x {s:3945:inv_misc_dust_06:Heavy Blasting Powder} - 30 沉重的石頭",
  ["15x {s:3942:inv_gizmo_02:Whirring Bronze Gizmo} - 30 Bronze Bar, 15 Wool Cloth"] = "15x {s:3942:inv_gizmo_02:Whirring Bronze Gizmo} - 30 青銅錠、15 毛料",
  ["{b}Make sure to make them in the same order.{/b} You need both for the sheep at 160, so make them now and you should reach 150 with them."] = "{b}請務必按照相同順序製作。{/b}160 製作綿羊時這兩種都需要，所以現在就做，做完應該能升到 150。",
  ["Expert Engineering (150-200)"] = "專家工程學 (150-200)",
  ["To train past 150, visit {n:0:horde:Roxxik} in Orgrimmar (Horde) or {n:0:alliance:Springspindle Fizzlegear} in Ironforge (Alliance) and learn Expert Engineering. You need {b}Engineering 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "要學習 150 以上，請找奧格瑪的 {n:0:horde:Roxxik}（部落）或鐵爐堡的 {n:0:alliance:Springspindle Fizzlegear}（聯盟）學習專家工程學。你需要{b}工程學 125{/b}和{b}等級 20{/b}，費用為 50 銀幣。",
  ["15x {s:3953:inv_gizmo_bronzeframework_01:Bronze Framework} - 30 Bronze Bar, 15 Medium Leather, 15 Wool Cloth"] = "15x {s:3953:inv_gizmo_bronzeframework_01:Bronze Framework} - 30 青銅錠、15 中皮、15 毛料",
  ["Keep these too, you will need all 15 for the sheep."] = "這些也要保留，製作綿羊時 15 個全部都會用到。",
  ["The 15 will probably take you past 160, that's fine."] = "這 15 個大概會讓你超過 160，沒關係。",
  ["15x {s:3955:spell_nature_polymorph:Explosive Sheep} - 30 Heavy Blasting Powder, 15 Whirring Bronze Gizmo, 15 Bronze Framework, 30 Wool Cloth"] = "15x {s:3955:spell_nature_polymorph:Explosive Sheep} - 30 重火藥、15 嗡鳴的青銅零件、15 青銅框架、30 毛料",
  ["Keep 5 of them, you might need them if you choose Goblin Engineering at 200."] = "保留其中 5 個，如果你在 200 選擇哥布林工程學，可能會用到。",
  ["60x {s:12585:inv_misc_powder_black:Solid Blasting Powder} - 120 Solid Stone"] = "60x {s:12585:inv_misc_powder_black:Solid Blasting Powder} - 120 堅固的石頭",
  ["Save these, you will need them later."] = "留著這些，之後會用到。",
  ["1x {s:12590:inv_misc_screwdriver_02:Gyromatic Micro-Adjustor} - 4 Steel Bar"] = "1x {s:12590:inv_misc_screwdriver_02:Gyromatic Micro-Adjustor} - 4 鋼錠",
  ["Keep this, you will need it to craft some of the Engineering recipes."] = "保留它，製作部分工程學配方時會用到。",
  ["If you were unlucky with the skill points and didn't reach 195, craft a few {s:3962:inv_misc_bomb_08:Iron Grenade} or any other recipe that gives skill points."] = "如果你技能點運氣不好，沒有到 195，就做幾個 {s:3962:inv_misc_bomb_08:Iron Grenade} 或其他能給技能點的配方。",
  ["6x {s:12589:inv_musket_01:Mithril Tube} - 18 Mithril Bar"] = "6x {s:12589:inv_musket_01:Mithril Tube} - 18 秘銀錠",
  ["Keep all 6, you might need them if you choose Gnomish Engineering at 200."] = "6 個全部保留，如果你在 200 選擇地精工程學，可能會用到。",
  ["Engineering Specializations"] = "工程學專精",
  ["At {b}Engineering 200{/b} and {b}level 30{/b}, you can specialize in Gnomish or Goblin Engineering. Some items require a specific specialization to use, while other items are crafted by one specialization but are usable by any engineer. Fortunately, most recipes that are crafted by one specialization can be used by both."] = "在{b}工程學 200{/b}和{b}等級 30{/b}時，你可以專精地精工程學或哥布林工程學。有些物品需要特定專精才能使用，有些物品則由某一專精製作，但任何工程師都能使用。幸好大多數由某一專精製作的配方，兩種專精都能使用。",
  ["For information on how to choose a specialization, please see my separate guide:"] = "關於如何選擇專精，請參閱我的獨立指南：",
  ["Artisan Engineering (200-300)"] = "工匠工程學 (200-300)",
  ["To train Engineering past 225 you need {b}Engineering 200{/b} and {b}level 35{/b}, then learn Artisan Engineering from {n:0::Buzzek Bracketswing} in Tanaris at Gadgetzan, he is right outside the inn near the mailbox. He also teaches the recipes above 200, so go there as soon as you reach 200."] = "要學習 225 以上的工程學，你需要{b}工程學 200{/b}和{b}等級 35{/b}，然後向塔納利斯加基森的 {n:0::Buzzek Bracketswing} 學習工匠工程學，他就在旅店外的郵箱附近。他也教授 200 以上的配方，所以一到 200 就去找他。",
  ["20x {s:12591:inv_battery_01:Unstable Trigger} - 20 Mithril Bar, 20 Mageweave Cloth, 20 Solid Blasting Powder"] = "20x {s:12591:inv_battery_01:Unstable Trigger} - 20 秘銀錠、20 魔紋布、20 堅固火藥",
  ["Keep them, you will need all 20 for the bombs at 238."] = "保留它們，238 製作炸彈時 20 個全部都會用到。",
  ["40x {s:12599:inv_gizmo_mithrilcasing_01:Mithril Casing} - 120 Mithril Bar"] = "40x {s:12599:inv_gizmo_mithrilcasing_01:Mithril Casing} - 120 秘銀錠",
  ["Keep these too, you will need 40 for the bombs."] = "這些也要保留，製作炸彈時需要 40 個。",
  ["20x {s:12619:inv_misc_bomb_07:Hi-Explosive Bomb} - 40 Mithril Casing, 20 Unstable Trigger, 40 Solid Blasting Powder"] = "20x {s:12619:inv_misc_bomb_07:Hi-Explosive Bomb} - 40 秘銀外殼、20 不穩定的觸發器、40 堅固火藥",
  ["44x {s:19788:inv_misc_ammo_gunpowder_01:Dense Blasting Powder} - 88 Dense Stone"] = "44x {s:19788:inv_misc_ammo_gunpowder_01:Dense Blasting Powder} - 88 緻密的石頭",
  ["35x {s:19791:inv_gizmo_04:Thorium Widget} - 105 Thorium Bar, 35 Runecloth"] = "35x {s:19791:inv_gizmo_04:Thorium Widget} - 105 瑟銀錠、35 符文布",
  ["{i:16042:inv_scroll_03:Schematic: Thorium Widget} is sold by {n:0:horde:Sovik} in Orgrimmar and {n:0:alliance:Gearcutter Cogspinner} in Ironforge."] = "{i:16042:inv_scroll_03:Schematic: Thorium Widget} 由奧格瑪的 {n:0:horde:Sovik} 和鐵爐堡的 {n:0:alliance:Gearcutter Cogspinner} 出售。",
  ["20x {s:19795:inv_gizmo_pipe_04:Thorium Tube} - 120 Thorium Bar"] = "20x {s:19795:inv_gizmo_pipe_04:Thorium Tube} - 120 瑟銀錠",
  ["{i:16047:inv_scroll_03:Schematic: Thorium Tube} is sold by {n:0::Xizzer Fizzbolt} in Winterspring at Everlook, in the first building on the right after the gate. It's bind on pickup in Forever, so buy it with the character that levels Engineering."] = "{i:16047:inv_scroll_03:Schematic: Thorium Tube} 由冬泉谷永望鎮的 {n:0::Xizzer Fizzbolt} 出售，就在進大門後右手邊的第一棟建築裡。它在 Forever 中是拾取綁定，所以請用練工程學的角色購買。",
  ["This WoW Forever Leatherworking leveling guide will show you the fastest and cheapest way to level your Leatherworking skill from 1 to 300. You will also find every trainer location and where to train Leatherworking past 75, 150 and 225."] = "這份 WoW Forever 製皮升級指南將告訴你如何以最快、最省錢的方式將製皮技能從 1 升到 300。你也能找到每位訓練師的位置，以及在 75、150 和 225 之後要去哪裡繼續學習製皮。",
  ["Below you will find the full shopping list, the Leatherworking trainers by starting zone and capital city, and the cheapest recipes for every skill range from Apprentice to Artisan. Leatherworking is best combined with Skinning because leather is most of the cost, but you can also buy everything in the guide from the Auction House."] = "下方有完整的購物清單、依新手區與主城分類的製皮訓練師，以及從學徒到工匠每個技能區間最便宜的配方。製皮最適合搭配剝皮，因為皮革佔了大部分成本，不過你也可以從拍賣場購買指南中的所有材料。",
  ["When a recipe is yellow or green, a craft doesn't always give you a skill point, so nobody can tell exactly how many materials you will need. That's why the counts that depend a lot on luck are a range. {b}With the bigger number 9 out of 10 players have enough, with the smaller one it's 50/50.{/b} If you buy the smaller number, be ready to buy more later."] = "配方是黃色或綠色時，製作不一定會給技能點，所以沒人能準確知道你需要多少材料。因此那些很看運氣的數量會以範圍表示。{b}買較大的數量，10 位玩家中有 9 位會夠用；買較小的數量，則是一半一半。{/b}如果你買較小的數量，請準備之後再補買。",
  ["Material"] = "材料",
  ["Leatherworking Trainer Locations"] = "製皮訓練師位置",
  ["Apprentice Leatherworking has no level requirement in Forever, so you can learn it on a fresh character."] = "在 Forever 中學習學徒製皮沒有等級需求，所以新角色也能學。",
  ["Orgrimmar: {n:0:horde:Kamari}"] = "奧格瑪：{n:0:horde:Kamari}",
  ["Undercity: {n:0:horde:Dan Golthas}"] = "幽暗城：{n:0:horde:Dan Golthas}",
  ["Thunder Bluff: {n:0:horde:Mak}"] = "雷霆崖：{n:0:horde:Mak}",
  ["There is no Leatherworking trainer in Durotar, go to {n:0:horde:Kamari} in the Drag in Orgrimmar"] = "杜洛塔沒有製皮訓練師，請去奧格瑪暗巷區找 {n:0:horde:Kamari}",
  ["{n:0:horde:Chaw Stronghide} in Bloodhoof Village"] = "血蹄村的 {n:0:horde:Chaw Stronghide}",
  ["{n:0:horde:Shelene Rhobart} at the road junction southeast of Brill"] = "布瑞爾東南方岔路口的 {n:0:horde:Shelene Rhobart}",
  ["{n:0::Emerii Tallgust} in Valanaar, {n:0::Indari Sunseam} in Shen'dar Village"] = "瓦拉納爾的 {n:0::Emerii Tallgust}，申達爾村的 {n:0::Indari Sunseam}",
  ["Stormwind City: {n:0:alliance:Randal Worth}"] = "暴風城：{n:0:alliance:Randal Worth}",
  ["Ironforge: {n:0:alliance:Gretta Finespindle}"] = "鐵爐堡：{n:0:alliance:Gretta Finespindle}",
  ["Darnassus: {n:0:alliance:Darianna}"] = "達納蘇斯：{n:0:alliance:Darianna}",
  ["{n:0:alliance:Adele Fielder} in the small house by Crystal Lake, northeast of Goldshire"] = "閃金鎮東北方水晶湖畔小屋裡的 {n:0:alliance:Adele Fielder}",
  ["There is no Leatherworking trainer in Dun Morogh, go to {n:0:alliance:Gretta Finespindle} at the Great Forge in Ironforge"] = "丹莫洛沒有製皮訓練師，請去鐵爐堡大鍛爐找 {n:0:alliance:Gretta Finespindle}",
  ["{n:0:alliance:Nadyia Maneweaver} in the small house near the road to Darnassus"] = "通往達納蘇斯道路旁小屋裡的 {n:0:alliance:Nadyia Maneweaver}",
  ["You can find every Leatherworking trainer for Horde and Alliance on my WoW Forever Leatherworking Trainers page."] = "你可以在我的 WoW Forever 製皮訓練師頁面找到部落和聯盟的所有製皮訓練師。",
  ["Apprentice Leatherworking (1-55)"] = "學徒製皮 (1-55)",
  ["35x {s:2881:inv_misc_leatherscrap_03:Light Leather} - 105 Ruined Leather Scraps"] = "35x {s:2881:inv_misc_leatherscrap_03:Light Leather} - 105 破碎的皮革碎片",
  ["27x {s:3816:inv_misc_pelt_wolf_01:Cured Light Hide} - 27 Light Hide, 27 Salt"] = "27x {s:3816:inv_misc_pelt_wolf_01:Cured Light Hide} - 27 輕毛皮、27 鹽",
  ["{b}NOTE:{/b} {b}Most trainers{/b} have a Leatherworking Supply vendor nearby that sells the threads, dyes, and salt, {b}except{/b} the trainers in Elwynn Forest and Tirisfal Glades. For those, buy the Salt and Coarse Thread in Goldshire from {n:0:alliance:Tharynn Bouden} or in Brill from {n:0:horde:Abigail Shiel}."] = "{b}注意：{/b}{b}大多數訓練師{/b}附近都有出售線、染料和鹽的製皮供應商，{b}除了{/b}艾爾文森林和提里斯法林地的訓練師。在這兩處，請到閃金鎮向 {n:0:alliance:Tharynn Bouden} 或到布瑞爾向 {n:0:horde:Abigail Shiel} 購買鹽和粗線。",
  ["Keep 24 of the hides, you will need them for the Light Leather Pants at 100."] = "保留其中 24 張毛皮，100 製作輕皮長褲時會用到。",
  ["Alternative recipes"] = "替代配方",
  ["If you farm your own leather and don't have 27 Light Hides, make Light Armor Kits until 45, then Embossed Leather Gloves until 55:"] = "如果你自己剝皮且沒有 27 張輕毛皮，就先做輕型護甲片到 45，再做壓花皮手套到 55：",
  ["24x {s:2152:inv_misc_armorkit_17:Light Armor Kit} - 24 Light Leather"] = "24x {s:2152:inv_misc_armorkit_17:Light Armor Kit} - 24 輕皮",
  ["10x {s:3756:inv_gauntlets_05:Embossed Leather Gloves} - 30 Light Leather, 20 Coarse Thread"] = "10x {s:3756:inv_gauntlets_05:Embossed Leather Gloves} - 30 輕皮、20 粗線",
  ["You still need 24 Cured Light Hide for the Light Leather Pants at 100, so keep the Light Hides you skin until then."] = "你在 100 製作輕皮長褲時仍需要 24 張熟化輕毛皮，所以在那之前請保留剝到的輕毛皮。",
  ["Journeyman Leatherworking (55-130)"] = "熟手製皮 (55-130)",
  ["To train past 75, visit one of these trainers and learn Journeyman Leatherworking. You need {b}Leatherworking 50{/b} and {b}level 10{/b}:"] = "要學習 75 以上，請找以下任一位訓練師學習熟手製皮。你需要{b}製皮 50{/b}和{b}等級 10{/b}：",
  ["Orgrimmar: {n:0:horde:Karolek}"] = "奧格瑪：{n:0:horde:Karolek}",
  ["Undercity: {n:0:horde:Arthur Moore}"] = "幽暗城：{n:0:horde:Arthur Moore}",
  ["Thunder Bluff: {n:0:horde:Tarn}"] = "雷霆崖：{n:0:horde:Tarn}",
  ["Stormwind City: {n:0:alliance:Simon Tanner}"] = "暴風城：{n:0:alliance:Simon Tanner}",
  ["Ironforge: {n:0:alliance:Fimble Finespindle}"] = "鐵爐堡：{n:0:alliance:Fimble Finespindle}",
  ["Darnassus: {n:0:alliance:Faldron}"] = "達納蘇斯：{n:0:alliance:Faldron}",
  ["21x {s:3756:inv_gauntlets_05:Embossed Leather Gloves} - 63 Light Leather, 42 Coarse Thread"] = "21x {s:3756:inv_gauntlets_05:Embossed Leather Gloves} - 63 輕皮、42 粗線",
  ["8x {s:20648:inv_misc_leatherscrap_05:Medium Leather} - 32 Light Leather"] = "8x {s:20648:inv_misc_leatherscrap_05:Medium Leather} - 32 輕皮",
  ["10x {s:3817:inv_misc_pelt_bear_02:Cured Medium Hide} - 10 Medium Hide, 10 Salt"] = "10x {s:3817:inv_misc_pelt_bear_02:Cured Medium Hide} - 10 中毛皮、10 鹽",
  ["Keep the Cured Medium Hides, you will need them for the Dark Leather Belts at 115."] = "保留熟化中毛皮，115 製作黑皮腰帶時會用到。",
  ["19x {s:3763:inv_belt_04:Fine Leather Belt} - 114 Light Leather, 38 Coarse Thread"] = "19x {s:3763:inv_belt_04:Fine Leather Belt} - 114 輕皮、38 粗線",
  ["Keep 10 of the belts for the Dark Leather Belts at 115."] = "保留其中 10 條腰帶，用於 115 的黑皮腰帶。",
  ["24x {s:9068:inv_pants_02:Light Leather Pants} - 240 Light Leather, 24 Cured Light Hide, 24 Fine Thread"] = "24x {s:9068:inv_pants_02:Light Leather Pants} - 240 輕皮、24 熟化輕毛皮、24 細線",
  ["10x {s:3766:inv_belt_03:Dark Leather Belt} - 10 Fine Leather Belt, 10 Cured Medium Hide, 20 Fine Thread, 10 Gray Dye"] = "10x {s:3766:inv_belt_03:Dark Leather Belt} - 10 精製皮腰帶、10 熟化中毛皮、20 細線、10 灰色染料",
  ["7x {s:20649:inv_misc_leatherscrap_07:Heavy Leather} - 35 Medium Leather"] = "7x {s:20649:inv_misc_leatherscrap_07:Heavy Leather} - 35 中皮",
  ["Expert Leatherworking (130-205)"] = "專家製皮 (130-205)",
  ["To train past 150, visit {n:0:horde:Una} in Thunder Bluff (Horde) or {n:0:alliance:Telonis} in Darnassus (Alliance) and learn Expert Leatherworking. You need {b}Leatherworking 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "要學習 150 以上，請找雷霆崖的 {n:0:horde:Una}（部落）或達納蘇斯的 {n:0:alliance:Telonis}（聯盟）學習專家製皮。你需要{b}製皮 125{/b}和{b}等級 20{/b}，費用為 50 銀幣。",
  ["30x {s:3818:inv_misc_pelt_wolf_02:Cured Heavy Hide} - 30 Heavy Hide, 90 Salt"] = "30x {s:3818:inv_misc_pelt_wolf_02:Cured Heavy Hide} - 30 重毛皮、90 鹽",
  ["Keep the Cured Heavy Hides, you will need 10 for the Barbaric Shoulders at 155 and 20 for the Guardian Gloves at 165."] = "保留熟化重毛皮，155 製作野蠻護肩需要 10 張，165 製作守護者手套需要 20 張。",
  ["17x {s:3764:inv_gauntlets_05:Hillman's Leather Gloves} - 238 Medium Leather, 68 Fine Thread"] = "17x {s:3764:inv_gauntlets_05:Hillman's Leather Gloves} - 238 中皮、68 細線",
  ["10x {s:7151:inv_shoulder_08:Barbaric Shoulders} - 80 Heavy Leather, 10 Cured Heavy Hide, 20 Fine Thread"] = "10x {s:7151:inv_shoulder_08:Barbaric Shoulders} - 80 重皮、10 熟化重毛皮、20 細線",
  ["20x {s:7156:inv_gauntlets_05:Guardian Gloves} - 80 Heavy Leather, 20 Cured Heavy Hide, 20 Silken Thread"] = "20x {s:7156:inv_gauntlets_05:Guardian Gloves} - 80 重皮、20 熟化重毛皮、20 絲線",
  ["22x {s:10507:inv_belt_24:Nightscape Headband} - 110 Thick Leather, 44 Silken Thread"] = "22x {s:10507:inv_belt_24:Nightscape Headband} - 110 厚皮、44 絲線",
  ["Leatherworking Specializations"] = "製皮專精",
  ["Once you reach {b}Leatherworking 225{/b} and {b}level 40{/b}, you can choose one of the three Leatherworking specializations: Dragonscale, Elemental, or Tribal. Each specialization gives access to a specific set of patterns."] = "當你達到{b}製皮 225{/b}和{b}等級 40{/b}時，可以選擇三種製皮專精之一：龍鱗、元素或部族。每種專精都能學到特定的一組圖樣。",
  ["Dragonscale - Mail-type gear"] = "龍鱗 - 鎖甲類裝備",
  ["Elemental - elemental resistance and Leather-type agility gear"] = "元素 - 元素抗性與皮甲類敏捷裝備",
  ["Tribal - Leather-type intellect & agility gear and the Devilsaur Armor set"] = "部族 - 皮甲類智力與敏捷裝備，以及魔暴龍護甲套裝",
  ["For information on how to become a Dragonscale, Elemental, or Tribal Leatherworker, please see my separate guides:"] = "關於如何成為龍鱗、元素或部族製皮師，請參閱我的獨立指南：",
  ["Artisan Leatherworking (205-300)"] = "工匠製皮 (205-300)",
  ["To train past 225, visit {n:0:horde:Hahrana Ironhide} in Camp Mojache, Feralas (Horde) or {n:0:alliance:Drakk Stonehand} in Aerie Peak, The Hinterlands (Alliance) and learn Artisan Leatherworking. You need {b}Leatherworking 200{/b} and {b}level 35{/b}."] = "要學習 225 以上，請找菲拉斯莫沙徹營地的 {n:0:horde:Hahrana Ironhide}（部落）或辛特蘭鷹巢山的 {n:0:alliance:Drakk Stonehand}（聯盟）學習工匠製皮。你需要{b}製皮 200{/b}和{b}等級 35{/b}。",
  ["36x {s:10548:inv_pants_11:Nightscape Pants} - 504 Thick Leather, 144 Silken Thread"] = "36x {s:10548:inv_pants_11:Nightscape Pants} - 504 厚皮、144 絲線",
  ["{b}The Expert trainers in Thunder Bluff and Darnassus don't teach this recipe{/b}, you can only learn it from the two trainers above."] = "{b}雷霆崖和達納蘇斯的專家訓練師不教這個配方{/b}，只能向上面兩位訓練師學習。",
  ["I recommend these over the Nightscape Boots because they sell for more to a vendor, so they end up cheaper."] = "我推薦做這個而不是夜色長靴，因為它賣給商人的價格更高，算下來反而更便宜。",
  ["36x {s:19049:inv_gauntlets_31:Wicked Leather Gauntlets} - 288 Rugged Leather, 36 Black Dye, 36 Rune Thread"] = "36x {s:19049:inv_gauntlets_31:Wicked Leather Gauntlets} - 288 硬甲皮、36 黑色染料、36 符文線",
  ["The pattern is sold by {n:0:horde:Werg Thickblade} in Tirisfal Glades (Horde) and {n:0:alliance:Leonard Porter} in Western Plaguelands (Alliance)."] = "圖樣由提里斯法林地的 {n:0:horde:Werg Thickblade}（部落）和西瘟疫之地的 {n:0:alliance:Leonard Porter}（聯盟）出售。",
  ["Blue Suede Shoes use the same leather but sell for more to a vendor, so they save you about 13 gold on this step. If the pattern costs less than that on the Auction House, make these instead:"] = "藍色麂皮鞋使用相同的皮革，但賣給商人的價格更高，在這一步大約能幫你省下 13 金幣。如果拍賣場上的圖樣比這便宜，就改做這個：",
  ["36x {s:1255048:inv_boots_leather_12:Blue Suede Shoes} - 288 Rugged Leather, 36 Blue Dye, 36 Rune Thread."] = "36x {s:1255048:inv_boots_leather_12:Blue Suede Shoes} - 288 硬甲皮、36 藍色染料、36 符文線。",
  ["53x {s:19082:inv_misc_bandage_11:Runic Leather Headband} - 742 Rugged Leather, 530 Runecloth, 53 Rune Thread"] = "53x {s:19082:inv_misc_bandage_11:Runic Leather Headband} - 742 硬甲皮、530 符文布、53 符文線",
  ["The pattern is sold by {n:0::Jase Farlane} at Light's Hope Chapel in Eastern Plaguelands."] = "圖樣由東瘟疫之地聖光之願禮拜堂的 {n:0::Jase Farlane} 出售。",
  ["If you have the pattern, make these from 275 instead:"] = "如果你有圖樣，可以從 275 開始改做這個：",
  ["27x {s:1255019:inv_bracer_22a:Blue Suede Bracers} - 270 Rugged Leather, 27 Blue Dye, 27 Rune Thread."] = "27x {s:1255019:inv_bracer_22a:Blue Suede Bracers} - 270 硬甲皮、27 藍色染料、27 符文線。",
  ["Blue Suede Hat"] = "藍色麂皮帽",
  ["{b}Someone with Leatherworking 300 has to place the Sewing Machine for you.{/b} You can't place a Sewing Machine yourself before 300, even if you buy one. I'm not sure if this is an oversight by Blizzard, so they might change it."] = "{b}必須由製皮 300 的人幫你放置縫紉機。{/b}在 300 之前即使你買了縫紉機也無法自己放置。我不確定這是不是暴雪的疏忽，所以之後可能會更改。",
  ["If you can use one and have the pattern, you can make these from 280:"] = "如果你能使用縫紉機並且有圖樣，可以從 280 開始製作這個：",
  ["20x {s:1255017:inv_helm_armor_buckledhat_b_01_blue:Blue Suede Hat} - 320 Rugged Leather, 80 Blue Dye, 20 Rune Thread."] = "20x {s:1255017:inv_helm_armor_buckledhat_b_01_blue:Blue Suede Hat} - 320 硬甲皮、80 藍色染料、20 符文線。",
  ["This WoW Forever Tailoring leveling guide will show you the fastest and cheapest way to level your Tailoring skill from 1 to 300. You will also find every trainer location and where to train Tailoring past 75, 150 and 225."] = "這份 WoW Forever 裁縫升級指南將告訴你如何以最快、最省錢的方式將裁縫技能從 1 升到 300。你也能找到每位訓練師的位置，以及在 75、150 和 225 之後要去哪裡繼續學習裁縫。",
  ["Below you will find the full shopping list, the Tailoring trainers by starting zone and capital city, and the cheapest recipes for every skill range from Apprentice to Artisan. Tailoring uses cloth as its main material, but cloth drops from humanoids, so you don't need a gathering profession and you can combine Tailoring with anything. Enchanting is a popular choice because you can disenchant the things you make while leveling and use the dust to level Enchanting."] = "下方有完整的購物清單、依新手區與主城分類的裁縫訓練師，以及從學徒到工匠每個技能區間最便宜的配方。裁縫的主要材料是布料，而布料由人型生物掉落，所以你不需要採集專業，裁縫可以搭配任何專業。附魔是熱門選擇，因為你可以分解升級時做出的物品，並用這些塵來升級附魔。",
  ["{b}NOTE:{/b} {b}Most trainers{/b} have a Tailoring Supply vendor nearby that sells the threads and dyes, {b}except{/b} the trainer in Tirisfal Glades. For that one, buy the Coarse Thread in Brill from {n:0:horde:Abigail Shiel}."] = "{b}注意：{/b}{b}大多數訓練師{/b}附近都有出售線和染料的裁縫供應商，{b}除了{/b}提里斯法林地的訓練師。在那裡，請到布瑞爾向 {n:0:horde:Abigail Shiel} 購買粗線。",
  ["Alternative (if cheaper)"] = "替代方案（如果更便宜）",
  ["This list is not final yet, but the skill ranges come from the game data, so it should be pretty close. The 280-300 part is not included here yet."] = "這份清單尚未定案，但技能區間來自遊戲資料，所以應該相當接近。280-300 的部分還沒有包含在這裡。",
  ["Tailoring Trainer Locations"] = "裁縫訓練師位置",
  ["Apprentice Tailoring has no level requirement in Forever, so you can learn it on a fresh character."] = "在 Forever 中學習學徒裁縫沒有等級需求，所以新角色也能學。",
  ["Orgrimmar: {n:0:horde:Snang}"] = "奧格瑪：{n:0:horde:Snang}",
  ["Undercity: {n:0:horde:Victor Ward}"] = "幽暗城：{n:0:horde:Victor Ward}",
  ["Thunder Bluff: {n:0:horde:Vhan}"] = "雷霆崖：{n:0:horde:Vhan}",
  ["There is no Tailoring trainer in Durotar, go to {n:0:horde:Snang} in the Drag in Orgrimmar"] = "杜洛塔沒有裁縫訓練師，請去奧格瑪暗巷區找 {n:0:horde:Snang}",
  ["There is no Tailoring trainer in Mulgore, go to {n:0:horde:Vhan} on the middle rise in Thunder Bluff"] = "莫高雷沒有裁縫訓練師，請去雷霆崖中間高台找 {n:0:horde:Vhan}",
  ["{n:0:horde:Bowen Brisboise} in the small house at Cold Hearth Manor, southwest of Brill"] = "布瑞爾西南方冰冷爐床莊園小屋裡的 {n:0:horde:Bowen Brisboise}",
  ["{n:0::Othesia Evengale} in Valanaar, {n:0::Taleen Shimmerthread} in Shen'dar Village"] = "瓦拉納爾的 {n:0::Othesia Evengale}，申達爾村的 {n:0::Taleen Shimmerthread}",
  ["Stormwind City: {n:0:alliance:Lawrence Schneider}"] = "暴風城：{n:0:alliance:Lawrence Schneider}",
  ["Ironforge: {n:0:alliance:Uthrar Threx}"] = "鐵爐堡：{n:0:alliance:Uthrar Threx}",
  ["Darnassus: {n:0:alliance:Trianna}"] = "達納蘇斯：{n:0:alliance:Trianna}",
  ["{n:0:alliance:Eldrin} in a house at the Eastvale Logging Camp"] = "東谷伐木場一棟房子裡的 {n:0:alliance:Eldrin}",
  ["There is no Tailoring trainer in Dun Morogh, go to {n:0:alliance:Uthrar Threx} at the Great Forge in Ironforge"] = "丹莫洛沒有裁縫訓練師，請去鐵爐堡大鍛爐找 {n:0:alliance:Uthrar Threx}",
  ["There is no Tailoring trainer in Teldrassil, go to {n:0:alliance:Trianna} at the Craftsmen's Terrace in Darnassus"] = "泰達希爾沒有裁縫訓練師，請去達納蘇斯工匠區找 {n:0:alliance:Trianna}",
  ["You can find every Tailoring trainer for Horde and Alliance on my WoW Forever Tailoring Trainers page."] = "你可以在我的 WoW Forever 裁縫訓練師頁面找到部落和聯盟的所有裁縫訓練師。",
  ["Apprentice Tailoring (1-55)"] = "學徒裁縫 (1-55)",
  ["30x {s:2963:inv_fabric_linen_02:Bolt of Linen Cloth} - 60 Linen Cloth"] = "30x {s:2963:inv_fabric_linen_02:Bolt of Linen Cloth} - 60 亞麻布",
  ["Keep the bolts, you need all of them for the belts."] = "保留布卷，製作腰帶時全部都會用到。",
  ["28x {s:8776:inv_belt_05:Linen Belt} - 28 Bolt of Linen Cloth, 28 Coarse Thread"] = "28x {s:8776:inv_belt_05:Linen Belt} - 28 亞麻布卷、28 粗線",
  ["Journeyman Tailoring (55-140)"] = "熟手裁縫 (55-140)",
  ["To train past 75, visit one of these trainers and learn Journeyman Tailoring. You need {b}Tailoring 50{/b} and {b}level 10{/b}:"] = "要學習 75 以上，請找以下任一位訓練師學習熟手裁縫。你需要{b}裁縫 50{/b}和{b}等級 10{/b}：",
  ["Orgrimmar: {n:0:horde:Magar}"] = "奧格瑪：{n:0:horde:Magar}",
  ["Undercity: {n:0:horde:Rhiannon Davis}"] = "幽暗城：{n:0:horde:Rhiannon Davis}",
  ["Thunder Bluff: {n:0:horde:Tepa}"] = "雷霆崖：{n:0:horde:Tepa}",
  ["Stormwind City: {n:0:alliance:Sellandus}"] = "暴風城：{n:0:alliance:Sellandus}",
  ["Ironforge: {n:0:alliance:Jormund Stonebrow}"] = "鐵爐堡：{n:0:alliance:Jormund Stonebrow}",
  ["Darnassus: {n:0:alliance:Me'lynn}"] = "達納蘇斯：{n:0:alliance:Me'lynn}",
  ["{b}Learn Journeyman Tailoring before you make these.{/b} You can reach past 75 with them, but you won't get any skill points above 75 until you learn it, so don't go AFK while crafting before you have it."] = "{b}製作這些之前請先學會熟手裁縫。{/b}做這些可以超過 75，但在學會之前，75 以上不會獲得任何技能點，所以在學會之前製作時不要掛機。",
  ["45x {s:2964:inv_fabric_wool_03:Bolt of Woolen Cloth} - 135 Wool Cloth"] = "45x {s:2964:inv_fabric_wool_03:Bolt of Woolen Cloth} - 135 毛料",
  ["Keep the bolts, you will need them later. In total you will need 153 {i:2997:inv_fabric_wool_03:Bolt of Woolen Cloth} (459 {i:2592:inv_fabric_wool_01:Wool Cloth}) until 140, so you can also make all of them now."] = "保留布卷，之後會用到。到 140 為止你總共需要 153 個 {i:2997:inv_fabric_wool_03:Bolt of Woolen Cloth}（459 個 {i:2592:inv_fabric_wool_01:Wool Cloth}），所以你也可以現在全部做好。",
  ["22x {s:2402:inv_misc_cape_10:Woolen Cape} - 22 Bolt of Woolen Cloth, 22 Fine Thread"] = "22x {s:2402:inv_misc_cape_10:Woolen Cape} - 22 毛料卷、22 細線",
  ["If the bolts already took you past 80, just make capes until 95."] = "如果做布卷就已經超過 80，就直接做披風到 95。",
  ["5x {s:3848:inv_shoulder_06:Double-stitched Woolen Shoulders} - 15 Bolt of Woolen Cloth, 10 Fine Thread"] = "5x {s:3848:inv_shoulder_06:Double-stitched Woolen Shoulders} - 15 毛料卷、10 細線",
  ["54x {s:3839:inv_fabric_silk_03:Bolt of Silk Cloth} - 216 Silk Cloth"] = "54x {s:3839:inv_fabric_silk_03:Bolt of Silk Cloth} - 216 絲綢",
  ["Keep the bolts, you will need them later. In total you will need 184 {i:4305:inv_fabric_silk_03:Bolt of Silk Cloth} (736 {i:4306:inv_fabric_silk_01:Silk Cloth}) until 190, so you can also make all of them now."] = "保留布卷，之後會用到。到 190 為止你總共需要 184 個 {i:4305:inv_fabric_silk_03:Bolt of Silk Cloth}（736 個 {i:4306:inv_fabric_silk_01:Silk Cloth}），所以你也可以現在全部做好。",
  ["29x {s:3852:inv_gauntlets_05:Gloves of Meditation} - 116 Bolt of Woolen Cloth, 87 Fine Thread, 29 Elixir of Wisdom"] = "29x {s:3852:inv_gauntlets_05:Gloves of Meditation} - 116 毛料卷、87 細線、29 智慧藥劑",
  ["You can buy {i:3383:inv_potion_06:Elixir of Wisdom} from the Auction House or ask an Alchemist."] = "你可以在拍賣場購買 {i:3383:inv_potion_06:Elixir of Wisdom}，或請鍊金術師幫忙。",
  ["Expert Tailoring (140-200)"] = "專家裁縫 (140-200)",
  ["To train past 150, visit {n:0:horde:Josef Gregorian} in Undercity (Horde) or {n:0:alliance:Georgio Bolero} in Stormwind City (Alliance) and learn Expert Tailoring. You need {b}Tailoring 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "要學習 150 以上，請找幽暗城的 {n:0:horde:Josef Gregorian}（部落）或暴風城的 {n:0:alliance:Georgio Bolero}（聯盟）學習專家裁縫。你需要{b}裁縫 125{/b}和{b}等級 20{/b}，費用為 50 銀幣。",
  ["23x {s:3865:inv_fabric_mageweave_03:Bolt of Mageweave} - 115 Mageweave Cloth"] = "23x {s:3865:inv_fabric_mageweave_03:Bolt of Mageweave} - 115 魔紋布",
  ["Keep the bolts, you will need them later. In total you will need 157 {i:4339:inv_fabric_mageweave_03:Bolt of Mageweave} (785 {i:4338:inv_fabric_mageweave_01:Mageweave Cloth}) until 225, so you can also make all of them now."] = "保留布卷，之後會用到。到 225 為止你總共需要 157 個 {i:4339:inv_fabric_mageweave_03:Bolt of Mageweave}（785 個 {i:4338:inv_fabric_mageweave_01:Mageweave Cloth}），所以你也可以現在全部做好。",
  ["20x {s:8791:inv_shirt_04:Crimson Silk Vest} - 80 Bolt of Silk Cloth, 40 Red Dye, 40 Fine Thread"] = "20x {s:8791:inv_shirt_04:Crimson Silk Vest} - 80 絲綢卷、40 紅色染料、40 細線",
  ["26x {s:8799:inv_pants_06:Crimson Silk Pantaloons} - 104 Bolt of Silk Cloth, 52 Red Dye, 52 Silken Thread"] = "26x {s:8799:inv_pants_06:Crimson Silk Pantaloons} - 104 絲綢卷、52 紅色染料、52 絲線",
  ["19x {s:12049:inv_pants_09:Black Mageweave Leggings} - 38 Bolt of Mageweave, 57 Silken Thread"] = "19x {s:12049:inv_pants_09:Black Mageweave Leggings} - 38 魔紋布卷、57 絲線",
  ["Artisan Tailoring (200-300)"] = "工匠裁縫 (200-300)",
  ["To train past 225, visit {n:0:horde:Daryl Stack} in Tarren Mill, Hillsbrad Foothills (Horde) or {n:0:alliance:Timothy Worthington} in Theramore Isle, Dustwallow Marsh (Alliance) and learn Artisan Tailoring. You need {b}Tailoring 200{/b} and {b}level 35{/b}."] = "要學習 225 以上，請找希爾斯布萊德丘陵塔倫米爾的 {n:0:horde:Daryl Stack}（部落）或塵泥沼澤塞拉摩島的 {n:0:alliance:Timothy Worthington}（聯盟）學習工匠裁縫。你需要{b}裁縫 200{/b}和{b}等級 35{/b}。",
  ["5x {s:12074:inv_shoulder_25:Black Mageweave Shoulders} - 15 Bolt of Mageweave, 10 Heavy Silken Thread"] = "5x {s:12074:inv_shoulder_25:Black Mageweave Shoulders} - 15 魔紋布卷、10 粗絲線",
  ["{b}The Expert trainers in Undercity and Stormwind don't teach this recipe{/b}, you can only learn it from the two trainers above."] = "{b}幽暗城和暴風城的專家訓練師不教這個配方{/b}，只能向上面兩位訓練師學習。",
  ["23x {s:18401:inv_fabric_purplefire_02:Bolt of Runecloth} - 115 Runecloth"] = "23x {s:18401:inv_fabric_purplefire_02:Bolt of Runecloth} - 115 符文布",
  ["Keep the bolts, you will need them later. In total you will need 311 {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth} (1555 {i:14047:inv_fabric_purplefire_01:Runecloth}) until 280, so you can also make all of them now."] = "保留布卷，之後會用到。到 280 為止你總共需要 311 個 {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}（1555 個 {i:14047:inv_fabric_purplefire_01:Runecloth}），所以你也可以現在全部做好。",
  ["26x {s:12065:inv_misc_bag_10_black:Mageweave Bag} - 104 Bolt of Mageweave, 52 Silken Thread"] = "26x {s:12065:inv_misc_bag_10_black:Mageweave Bag} - 104 魔紋布卷、52 絲線",
  ["I recommend the bags right now simply because they are more useful. You can use them yourself, sell some, give them to friends or use them in your bank."] = "我現在推薦做背包，單純因為它們比較實用。你可以自己用、賣掉一些、送給朋友，或放在銀行裡使用。",
  ["If you don't need the bags and don't want to sell them, make these instead."] = "如果你不需要背包也不想賣，就改做這個。",
  ["10x {s:18402:inv_belt_15:Runecloth Belt} - 30 Bolt of Runecloth, 10 Rune Thread."] = "10x {s:18402:inv_belt_15:Runecloth Belt} - 30 符文布卷、10 符文線。",
  ["24x {s:18402:inv_belt_15:Runecloth Belt} - 72 Bolt of Runecloth, 24 Rune Thread"] = "24x {s:18402:inv_belt_15:Runecloth Belt} - 72 符文布卷、24 符文線",
  ["11x {s:18417:inv_gauntlets_25:Runecloth Gloves} - 44 Bolt of Runecloth, 44 Rugged Leather, 11 Rune Thread"] = "11x {s:18417:inv_gauntlets_25:Runecloth Gloves} - 44 符文布卷、44 硬甲皮、11 符文線",
  ["The pattern is sold by {n:0::Qia} in Winterspring."] = "圖樣由冬泉谷的 {n:0::Qia} 出售。",
  ["39x {s:1257487:inv_bracer_13:Runecloth Cuffs} - 195 Bolt of Runecloth, 39 Ironweb Spider Silk, 39 Rune Thread"] = "39x {s:1257487:inv_bracer_13:Runecloth Cuffs} - 195 符文布卷、39 鐵網蜘蛛絲、39 符文線",
  ["The pattern is sold by {n:0::Pexmit} in Mount Hyjal. It's bind on pickup, so buy it with the character that levels Tailoring."] = "圖樣由海加爾山的 {n:0::Pexmit} 出售。它是拾取綁定，所以請用練裁縫的角色購買。",
  ["Horde players can also get it as the reward for {q:95769::Threading a Solution}, a quest from {n:265788::Kal'tinzan} in Elderwild, Mount Hyjal. It needs level 54 and 6 Bolt of Runecloth. It's probably a Tailoring quest, but I don't know yet what skill it needs."] = "部落玩家也可以透過 {q:95769::Threading a Solution} 任務的獎勵取得，這個任務由海加爾山長青荒野的 {n:265788::Kal'tinzan} 提供。需要等級 54 和 6 個符文布卷。這可能是裁縫任務，但我還不知道需要多少技能。",
  ["Make the {s:18449:inv_shoulder_21:Runecloth Shoulders} if you can get the pattern. These are all the recipes I found so far that still give points after 280. I left out the ones that aren't worth it for leveling, and there might be new ones that nobody has found yet."] = "如果你能取得圖樣，就製作 {s:18449:inv_shoulder_21:Runecloth Shoulders}。這些是我目前找到在 280 之後仍會給點數的所有配方。我略過了那些不值得用來升級的配方，而且可能還有沒人發現的新配方。",
  ["Range"] = "區間",
  ["Materials"] = "材料",
  ["Pattern"] = "圖樣",
  ["World drop, on the Auction House"] = "世界掉落，可在拍賣場購買",
  ["Rare, grab it if you see it on the Auction House"] = "稀有，在拍賣場看到就買下來",
  ["You can get a few more points with these, but they stop giving skill points before 300, so you can't reach 300 with them:"] = "做這些還能多拿幾點，但它們在 300 之前就不再給技能點，所以無法靠它們升到 300：",
  ["{n:0::Pexmit} in Mount Hyjal"] = "海加爾山的 {n:0::Pexmit}",
  ["Recipes that need a Loom"] = "需要織布機的配方",
  ["{b}These recipes need a Loom, and you can only make a Loom at Tailoring 300.{/b} They could be used for leveling, but for now you would need a camp where another tailor already placed a Loom. I'm not sure if this is an oversight by Blizzard, so they might change it."] = "{b}這些配方需要織布機，而織布機要到裁縫 300 才能製作。{/b}它們可以用來升級，但目前你需要找一個已經有其他裁縫放置了織布機的營地。我不確定這是不是暴雪的疏忽，所以之後可能會更改。",
  ["These are the Cenarion Circle patterns from {n:0::Mishta} in Silithus:"] = "這些是希利蘇斯 {n:0::Mishta} 出售的塞納里奧議會圖樣：",
  ["Requires"] = "需求",
  ["5x {s:1297123:inv_gauntlets_17:Swarmtender's Gloves} or {s:1297120:inv_gauntlets_18:Venomspew Gloves}"] = "5x {s:1297123:inv_gauntlets_17:Swarmtender's Gloves} 或 {s:1297120:inv_gauntlets_18:Venomspew Gloves}",
  ["20x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}, 5x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}, 15x {i:7080:spell_nature_acid_01:Essence of Water} or {i:7082:spell_nature_earthbind:Essence of Air}"] = "20x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}、5x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}、15x {i:7080:spell_nature_acid_01:Essence of Water} 或 {i:7082:spell_nature_earthbind:Essence of Air}",
  ["Cenarion Circle Friendly"] = "塞納里奧議會友好",
  ["5x {s:1297124:inv_belt_03:Swarmtender's Cord} or {s:1297121:inv_belt_25:Venomspew Cord}"] = "5x {s:1297124:inv_belt_03:Swarmtender's Cord} 或 {s:1297121:inv_belt_25:Venomspew Cord}",
  ["30x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}, 5x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}, 15x {i:7080:spell_nature_acid_01:Essence of Water} or {i:7082:spell_nature_earthbind:Essence of Air}"] = "30x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}、5x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}、15x {i:7080:spell_nature_acid_01:Essence of Water} 或 {i:7082:spell_nature_earthbind:Essence of Air}",
  ["Cenarion Circle Honored"] = "塞納里奧議會尊敬",
  ["18x {s:1297125:inv_boots_cloth_01:Swarmtender's Footpads} or {s:1297122:inv_boots_cloth_04:Venomspew Footpads}"] = "18x {s:1297125:inv_boots_cloth_01:Swarmtender's Footpads} 或 {s:1297122:inv_boots_cloth_04:Venomspew Footpads}",
  ["90x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}, 18x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}, 54x {i:7080:spell_nature_acid_01:Essence of Water} or {i:7082:spell_nature_earthbind:Essence of Air}"] = "90x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}、18x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}、54x {i:7080:spell_nature_acid_01:Essence of Water} 或 {i:7082:spell_nature_earthbind:Essence of Air}",
  ["This WoW Forever Mining leveling guide will show you the fastest way to level Mining from 1 to 300. You will also find every trainer location and where to train Mining past 75, 150 and 225."] = "這份 WoW Forever 採礦升級指南將告訴你如何以最快的方式將採礦從 1 升到 300。你也能找到每位訓練師的位置，以及在 75、150 和 225 之後要去哪裡繼續學習採礦。",
  ["Below you will find the Mining trainers by starting zone and capital city, and the best zones to mine in for every skill range. Mining serves two professions, Blacksmithing and Engineering, so it's really good combined with these two. Check out my Forever Blacksmithing leveling guide or my Forever Engineering leveling guide if you want to level one of them."] = "下方有依新手區與主城分類的採礦訓練師，以及每個技能區間最適合挖礦的區域。採礦供應鍛造和工程學兩種專業，所以非常適合搭配這兩者。如果你想練其中一種，請看我的 Forever 鍛造升級指南或 Forever 工程學升級指南。",
  ["WoW Forever added a couple of new ores, bars and recipes. You can check them out here:"] = "WoW Forever 新增了一些新的礦石、金屬錠和配方。你可以在這裡查看：",
  ["Mining Trainer Locations"] = "採礦訓練師位置",
  ["Every capital city except Darnassus has a Mining trainer. You can also ask a guard, then it will be marked with a red flag on your map."] = "除了達納蘇斯，每座主城都有採礦訓練師。你也可以詢問衛兵，地圖上就會用紅旗標出位置。",
  ["{b}Capital cities:{/b}"] = "{b}主城：{/b}",
  ["Orgrimmar: {n:0:horde:Makaru}"] = "奧格瑪：{n:0:horde:Makaru}",
  ["Undercity: {n:0:horde:Brom Killian}"] = "幽暗城：{n:0:horde:Brom Killian}",
  ["Thunder Bluff: {n:0:horde:Brek Stonehoof}"] = "雷霆崖：{n:0:horde:Brek Stonehoof}",
  ["{b}Starting zones:{/b}"] = "{b}新手區：{/b}",
  ["{n:0:horde:Norzsh} in the Valley of Trials (only up to 75) {n:0:horde:Krunn} in Razor Hill"] = "試煉谷的 {n:0:horde:Norzsh}（最多只到 75） 剃刀嶺的 {n:0:horde:Krunn}",
  ["{n:0:horde:Vartha Rockmane} in Camp Narache (only up to 75) {n:0:horde:Brek Stonehoof} in Thunder Bluff"] = "納拉其營地的 {n:0:horde:Vartha Rockmane}（最多只到 75） 雷霆崖的 {n:0:horde:Brek Stonehoof}",
  ["{n:0:horde:Walter Mason} in Deathknell (only up to 75) {n:0:horde:Brom Killian} in Undercity"] = "喪鐘鎮的 {n:0:horde:Walter Mason}（最多只到 75） 幽暗城的 {n:0:horde:Brom Killian}",
  ["There is no trainer in Thendal Village, where you start, but you don't need one. {q:93552::Harvesting Windstones} is one of the first quests you get in Thendal Village. Pick {i:247840:inv_10_specialization_professionbook_mining_orig:Mining for Dummies} as your reward, it teaches you Mining. The trainers on the island are {n:0::Halavuul Cragwind} in Valanaar and {n:0::Messana Crestwind} in Shen'dar Village."] = "你出生的坦達爾村沒有訓練師，但你也不需要。{q:93552::Harvesting Windstones} 是你在坦達爾村最早接到的任務之一。選擇 {i:247840:inv_10_specialization_professionbook_mining_orig:Mining for Dummies} 作為獎勵，它會教你採礦。島上的訓練師是瓦拉納爾的 {n:0::Halavuul Cragwind} 和申達爾村的 {n:0::Messana Crestwind}。",
  ["Stormwind City: {n:0:alliance:Gelman Stonehand}"] = "暴風城：{n:0:alliance:Gelman Stonehand}",
  ["Ironforge: {n:0:alliance:Geofram Bouldertoe}"] = "鐵爐堡：{n:0:alliance:Geofram Bouldertoe}",
  ["Darnassus: no trainer, the closest one is {n:0:alliance:Kurdram Stonehammer} in Auberdine, Darkshore"] = "達納蘇斯：沒有訓練師，最近的是黑海岸奧伯丁的 {n:0:alliance:Kurdram Stonehammer}",
  ["{n:0:alliance:Kelsey Fargo} (only up to 75) {n:0:alliance:Gelman Stonehand} in Stormwind City"] = "{n:0:alliance:Kelsey Fargo}（最多只到 75） 暴風城的 {n:0:alliance:Gelman Stonehand}",
  ["{n:0:alliance:Sally Swiftwrench} (only up to 75) {n:0:alliance:Yarr Hammerstone} at Steelgrill's Depot {n:0:alliance:Dank Drizzlecut} at Gol'Bolar Quarry"] = "{n:0:alliance:Sally Swiftwrench}（最多只到 75） 鋼架補給站的 {n:0:alliance:Yarr Hammerstone} 古博拉採掘場的 {n:0:alliance:Dank Drizzlecut}",
  ["{n:0:alliance:Fanorran Stilloak} at Aldrassil in Shadowglen (only up to 75) {n:0:alliance:Kurdram Stonehammer} in Auberdine, Darkshore"] = "影谷奧達希爾的 {n:0:alliance:Fanorran Stilloak}（最多只到 75） 黑海岸奧伯丁的 {n:0:alliance:Kurdram Stonehammer}",
  ["You can find every Mining trainer for Horde and Alliance on my WoW Forever Mining Trainers page."] = "你可以在我的 WoW Forever 採礦訓練師頁面找到部落和聯盟的所有採礦訓練師。",
  ["Track Ore on Your Minimap"] = "在小地圖上追蹤礦石",
  ["You can only track one thing at a time, so {b}you can't track minerals and herbs together{/b}."] = "你一次只能追蹤一種東西，所以{b}無法同時追蹤礦物和草藥{/b}。",
  ["You learn {s:2580:spell_nature_earthquake:Find Minerals} together with Mining, but it's not turned on by default:"] = "學會採礦時你會一併獲得 {s:2580:spell_nature_earthquake:Find Minerals}，但它預設沒有開啟：",
  ["Open the Professions window with the hammer and pick button, the 2nd button in the menu at the bottom of your screen."] = "用錘子與十字鎬圖示的按鈕打開專業視窗，就是畫面底部選單中的第 2 個按鈕。",
  ["Click Find Minerals in the Mining box. {b}I recommend dragging it to your action bar, close to the buffs you use after you die.{/b} This way you make a habit out of it and you are less likely to forget it."] = "點擊採礦欄位中的尋找礦物。{b}我建議把它拖到快捷列上，放在你死亡後會使用的增益技能附近。{/b}這樣你會養成習慣，比較不容易忘記。",
  ["The Find Minerals buff shows up next to your minimap. {b}Your tracking turns off every time you die, so don't forget to turn it back on!{/b}"] = "尋找礦物的增益效果會顯示在小地圖旁邊。{b}每次死亡時追蹤都會關閉，別忘了重新開啟！{/b}",
  ["The Find Minerals button in the WoW Forever Professions window"] = "WoW Forever 專業視窗中的尋找礦物按鈕",
  ["Mining Skill Bonuses"] = "採礦技能加成",
  ["You don't need these, but they help when you are stuck between two ores. With +5 you can mine Iron Deposits from 120 instead of 125, so you can skip the last few slow points of Tin."] = "這些不是必需的，但當你卡在兩種礦石之間時很有幫助。有 +5 的話，你在 120 就能採鐵礦床，不必等到 125，這樣就能跳過錫礦最後幾點慢慢升的部分。",
  ["Item"] = "物品",
  ["Mining"] = "採礦",
  ["How to get it"] = "取得方式",
  ["An enchanter"] = "找附魔師",
  ["Made by Engineers, you need Engineering 205 to wear it"] = "由工程師製作，需要工程學 205 才能裝備",
  ["Reward of A Miner Problem, an Alliance quest in the Riverglades"] = "A Miner Problem 的獎勵，這是河谷地的聯盟任務",
  ["Drops from Miner Johnson in The Deadmines"] = "由死亡礦坑的礦工約翰森掉落",
  ["Smelting to 105"] = "熔煉到 105",
  ["You can skip the first 105 skill points by buying ores on the Auction House and smelting them. If you prefer leveling Mining the normal way, scroll down to the mining routes. But I would recommend smelting if you have the gold, as it saves a lot of time. Sometimes the bars even sell for more than the ores or they are very close in price, so it's not like you are losing much by doing this."] = "你可以在拍賣場購買礦石並熔煉，跳過前 105 個技能點。如果你偏好用一般方式練採礦，請往下捲到挖礦路線。但如果你有金幣，我建議熔煉，因為能省下很多時間。有時金屬錠甚至比礦石賣得更貴，或價格非常接近，所以這樣做其實不會損失太多。",
  ["Buy around 140 {i:2770:inv_ore_copper_01:Copper Ore} and 70 {i:2771:inv_ore_tin_01:Tin Ore}. Smelting is mostly yellow and green, so you might need a few more if you are unlucky."] = "購買大約 140 個 {i:2770:inv_ore_copper_01:Copper Ore} 和 70 個 {i:2771:inv_ore_tin_01:Tin Ore}。熔煉大多是黃色和綠色，如果運氣不好，可能需要多一些。",
  ["Notes"] = "備註",
  ["120-140x {s:2657:inv_ingot_02:Smelt Copper} until you reach 65. Keep 70 Copper Bars, you will need them for Bronze."] = "120-140x {s:2657:inv_ingot_02:Smelt Copper} 直到 65。保留 70 個銅錠，製作青銅時會用到。",
  ["Learn Journeyman Mining, Smelt Tin and Smelt Bronze from your trainer. Make 70x {s:3304:inv_ingot_05:Smelt Tin}. It turns grey at 75, but you need all 70 Tin Bars for Bronze anyway."] = "向訓練師學習熟手採礦、熔煉錫和熔煉青銅。製作 70x {s:3304:inv_ingot_05:Smelt Tin}。它在 75 會變灰，但反正你需要全部 70 個錫錠來做青銅。",
  ["Make 70x {s:2659:inv_ingot_bronze:Smelt Bronze} from the Copper Bars and Tin Bars you made. You will end up somewhere between 100 and 110, so you might need a few more."] = "用你做好的銅錠和錫錠製作 70x {s:2659:inv_ingot_bronze:Smelt Bronze}。你最後會落在 100 到 110 之間，所以可能需要再多做幾個。",
  ["Learn Smelt Silver from your trainer. Check the price of Silver Ore and Silver Bar first, because this part can get expensive. If you don't mind the cost, make 35-45x {s:2658:inv_ingot_01:Smelt Silver} until you reach 120. The last 5 points to 125 could take around 50 more Silver Ore, so I recommend mining from 120. (or keep smelting if you have the gold) Iron Deposits need Mining 125, but with +5 from the Mining Skill Bonuses above you can mine them from 120, so you can skip Tin and go straight to Iron."] = "向訓練師學習熔煉銀。先查看銀礦石和銀錠的價格，因為這部分可能會很貴。如果你不在意花費，就做 35-45x {s:2658:inv_ingot_01:Smelt Silver} 直到 120。最後 5 點到 125 可能還要再花大約 50 個銀礦石，所以我建議從 120 開始改去挖礦。（如果你有金幣也可以繼續熔煉）鐵礦床需要採礦 125，但有了上方採礦技能加成的 +5，你在 120 就能採，所以可以跳過錫礦直接挖鐵礦。",
  ["{b}Don't forget to buy{/b} a {i:2901:inv_pick_02:Mining Pick} from the Mining Supplier near your trainer or from the trainer!"] = "{b}別忘了購買{/b}一把 {i:2901:inv_pick_02:Mining Pick}，可以向訓練師附近的採礦供應商或訓練師本人購買！",
  ["You can buy one from these vendors:"] = "你可以向以下商人購買：",
  ["{n:0:horde:Norzsh} in the Valley of Trials, {n:0:horde:Flakk} in Razor Hill"] = "試煉谷的 {n:0:horde:Norzsh}，剃刀嶺的 {n:0:horde:Flakk}",
  ["{n:0:horde:Vartha Rockmane} in Camp Narache, {n:0:horde:Wunna Darkmane} in Bloodhoof Village"] = "納拉其營地的 {n:0:horde:Vartha Rockmane}，血蹄村的 {n:0:horde:Wunna Darkmane}",
  ["{n:0:horde:Walter Mason} in Deathknell, {n:0:horde:Abigail Shiel} in Brill"] = "喪鐘鎮的 {n:0:horde:Walter Mason}，布瑞爾的 {n:0:horde:Abigail Shiel}",
  ["{n:0::Uualia Suncrest} in Thendal Village, {n:0::Belandiel Farflight} in Shen'dar Village"] = "坦達爾村的 {n:0::Uualia Suncrest}，申達爾村的 {n:0::Belandiel Farflight}",
  ["{n:0:horde:Gorina} in the Valley of Honor"] = "榮譽谷的 {n:0:horde:Gorina}",
  ["{n:0:horde:Elizabeth Van Talen} in the Rogues' Quarter"] = "盜賊區的 {n:0:horde:Elizabeth Van Talen}",
  ["{n:0:alliance:Brother Danil} in Northshire Valley, {n:0:alliance:Tharynn Bouden} in Goldshire"] = "北郡山谷的 {n:0:alliance:Brother Danil}，閃金鎮的 {n:0:alliance:Tharynn Bouden}",
  ["{n:0:alliance:Thrawn Boltar} in Kharanos"] = "卡拉諾斯的 {n:0:alliance:Thrawn Boltar}",
  ["{n:0:alliance:Fanorran Stilloak} at Aldrassil in Shadowglen, {n:0:alliance:Narret Shadowgrove} in Dolanaar"] = "影谷奧達希爾的 {n:0:alliance:Fanorran Stilloak}，多蘭納爾的 {n:0:alliance:Narret Shadowgrove}",
  ["{n:0:alliance:Brooke Stonebraid} in the Dwarven District"] = "矮人區的 {n:0:alliance:Brooke Stonebraid}",
  ["{n:0:alliance:Thurgrum Deepforge} in The Great Forge"] = "大鍛爐的 {n:0:alliance:Thurgrum Deepforge}",
  ["Darnassus"] = "達納蘇斯",
  ["Like I said above, for most high level players I think it's best to skip this part and smelt your way up to at least 105. But if you prefer mining and you can choose your zone, I think {b}Durotar{/b} is the best for Horde and {b}Elwynn Forest{/b} for Alliance."] = "如我上面所說，對大多數高等級玩家來說，我認為最好跳過這部分，靠熔煉至少升到 105。但如果你偏好挖礦且能自選區域，我認為部落最適合{b}杜洛塔{/b}，聯盟最適合{b}艾爾文森林{/b}。",
  ["One or two laps around the zone will get you enough Copper Ore to reach 65 with smelting."] = "在區域裡繞一兩圈就能挖到足夠的銅礦石，靠熔煉升到 65。",
  ["After you do one lap, {b}stop at Razor Hill and smelt your Copper Ore{/b} into Copper Bars."] = "繞完一圈後，{b}在剃刀嶺停下來把銅礦石熔煉{/b}成銅錠。",
  ["Mining route in Durotar"] = "杜洛塔的採礦路線",
  ["The cave marked with the red circle has 5 Copper Veins inside, {b}the respawn rate is so fast that you can basically stay inside the cave and level there{/b}. The cave layout is also very good because there is a drop down at the end, so you can quickly return to the start and continue mining. If the respawn rate is not enough for you or there is competition, just run outside, mine a couple of Copper Veins and go back to the cave."] = "紅圈標示的洞穴裡有 5 個銅礦脈，{b}重生速度快到你基本上可以待在洞裡升級{/b}。洞穴的構造也很好，盡頭有個可以跳下去的地方，讓你能快速回到起點繼續挖。如果重生速度不夠快或有人搶，就跑到外面挖幾個銅礦脈再回洞裡。",
  ["You can also just do a full lap in Mulgore, the route is very easy to follow, it's basically a loop around the edge of the zone. But I found the cave to be better without a mount."] = "你也可以在莫高雷繞一整圈，路線非常好跟，基本上就是沿著區域邊緣繞一圈。不過沒有坐騎的話，我覺得洞穴更好。",
  ["{b}You can smelt your ore at the Bael'dun Digsite{/b}, the dwarf camp just north of the cave has a forge and an anvil. (marked on the map) The dwarves there are hostile."] = "{b}你可以在貝爾丹挖掘場熔煉礦石{/b}，洞穴正北方的矮人營地有鍛爐和鐵砧。（已在地圖上標示）那裡的矮人是敵對的。",
  ["Mining route in Mulgore with the forge and anvil at the Bael'dun Digsite"] = "莫高雷的採礦路線，包含貝爾丹挖掘場的鍛爐和鐵砧",
  ["Both routes are good. The route on the east side of the zone will probably have fewer people, because there are fewer quest hubs there."] = "兩條路線都不錯。區域東側的路線人可能比較少，因為那裡的任務點較少。",
  ["{b}Stop at Brill after one lap{/b} to smelt your Copper Ore."] = "繞完一圈後{b}在布瑞爾停下來{/b}熔煉銅礦石。",
  ["Mining route in Tirisfal Glades"] = "提里斯法林地的採礦路線",
  ["{q:93552::Harvesting Windstones} is one of the first quests you get in Thendal Village. Pick {i:247840:inv_10_specialization_professionbook_mining_orig:Mining for Dummies} as your reward, it teaches you Mining."] = "{q:93552::Harvesting Windstones} 是你在坦達爾村最早接到的任務之一。選擇 {i:247840:inv_10_specialization_professionbook_mining_orig:Mining for Dummies} 作為獎勵，它會教你採礦。",
  ["The respawn rate is very fast around this area, sometimes the veins spawned right on top of me. You can do a larger route, but without a mount and with the fast respawn rate I found it wasn't needed."] = "這一帶的重生速度非常快，有時礦脈就直接在我身上重生。你可以走更大的路線，但沒有坐騎又重生這麼快的情況下，我覺得沒必要。",
  ["{b}Stop at Shen'dar Village after one lap{/b} to smelt your Copper Ore."] = "繞完一圈後{b}在申達爾村停下來{/b}熔煉銅礦石。",
  ["Mining route on Zephras Isle"] = "澤弗拉斯島的採礦路線",
  ["Just move back and forth along the marked route, and clear the cave if you are high enough level. The respawn rate is quite fast inside the cave, so you might not even have to leave it, it depends on your level. You can also just skip the cave, the respawn rate seems to be fast enough on the route, but then do the small detour to the north too."] = "沿著標示的路線來回走，如果等級夠高就把洞穴清一清。洞裡的重生速度相當快，視你的等級而定，可能根本不用出洞。你也可以直接跳過洞穴，路線上的重生速度似乎也夠快，但這樣的話請順便繞一下北邊的小岔路。",
  ["{b}Stop at Goldshire after one lap{/b} to smelt your Copper Ore."] = "繞完一圈後{b}在閃金鎮停下來{/b}熔煉銅礦石。",
  ["Mining route in Elwynn Forest"] = "艾爾文森林的採礦路線",
  ["Not much to say about this one, just do loops around this area. You don't have to go inside the cave, it's optional and the respawn rate outside is quite fast."] = "這條沒什麼好說的，就是在這一帶繞圈。洞穴可以不進去，那是選擇性的，外面的重生速度也相當快。",
  ["{b}Stop at Kharanos after one lap{/b} to smelt your Copper Ore."] = "繞完一圈後{b}在卡拉諾斯停下來{/b}熔煉銅礦石。",
  ["Mining route in Dun Morogh"] = "丹莫洛的採礦路線",
  ["These two caves have an insanely fast respawn rate. I don't know if it stays like this, but right now you can just stay inside the caves and level there."] = "這兩個洞穴的重生速度快得誇張。我不知道會不會一直這樣，但目前你可以直接待在洞裡升級。",
  ["There is no forge in Teldrassil, {b}the closest one is at the Warrior's Terrace in Darnassus{/b}."] = "泰達希爾沒有鍛爐，{b}最近的在達納蘇斯的戰士區{/b}。",
  ["Mining route in Teldrassil"] = "泰達希爾的採礦路線",
  ["Visit your trainer and learn Journeyman Mining, it requires Mining 50. The new Junior Mining Trainers in the starting areas won't teach you Journeyman Mining."] = "找訓練師學習熟手採礦，需要採礦 50。新手區新增的初級採礦訓練師不會教熟手採礦。",
  ["If you have any Copper Ore or Tin Ore at this point, smelt them and make Bronze Bars before you head out, because Bronze stops giving skill points around 105."] = "如果你這時手上還有銅礦石或錫礦石，出發前先熔煉並做成青銅錠，因為青銅大約在 105 就不再給技能點。",
  ["For Alliance, the {b}Wetlands{/b} is the best one by far if you can manage the cave. For Horde it's the {b}Silverpine Forest{/b} cave or {b}Hillsbrad Foothills{/b}. The rest are pretty even, hard to judge."] = "聯盟方面，如果你能應付那個洞穴，{b}濕地{/b}是目前最好的選擇。部落則是{b}銀松森林{/b}的洞穴或{b}希爾斯布萊德丘陵{/b}。其他的都差不多，很難比較。",
  ["Ores in these zones: {i:2771:inv_ore_tin_01:Tin Ore}, {i:2770:inv_ore_copper_01:Copper Ore}, {i:2775:inv_stone_16:Silver Ore}"] = "這些區域的礦石：{i:2771:inv_ore_tin_01:Tin Ore}、{i:2770:inv_ore_copper_01:Copper Ore}、{i:2775:inv_stone_16:Silver Ore}",
  ["Tin Veins need Mining 65 and Silver Veins 75."] = "錫礦脈需要採礦 65，銀礦脈需要 75。",
  ["Wetlands"] = "濕地",
  ["Silverpine Forest"] = "銀松森林",
  ["Westfall"] = "西部荒野",
  ["Hillsbrad Foothills"] = "希爾斯布萊德丘陵",
  ["The Barrens"] = "貧瘠之地",
  ["Ashenvale"] = "梣谷",
  ["Stonetalon Mountains"] = "石爪山脈",
  ["This cave in the Wetlands is the best place for Alliance players to level Mining. The cave is full of Tin Veins and Incendicite Mineral Veins with a very fast respawn time."] = "濕地的這個洞穴是聯盟玩家練採礦的最佳地點。洞裡滿是錫礦脈和火岩礦脈，重生時間非常短。",
  ["The mobs are around level 20 and {b}in Forever they respawn much faster, so you need to outlevel them by quite a few levels{/b}, or they will keep respawning right on top of you."] = "怪物大約 20 級，{b}而在 Forever 中牠們重生得快很多，所以你的等級要比牠們高出不少{/b}，否則牠們會不斷在你身上重生。",
  ["Mining route in the Wetlands"] = "濕地的採礦路線",
  ["This cave has 3 vein spawn points with a very fast respawn time, just mine the veins and wait for the respawn. (around 2 minutes)"] = "這個洞穴有 3 個礦脈重生點，重生時間非常短，挖完礦脈等它重生就好。（大約 2 分鐘）",
  ["The mobs are around level 21-22 and {b}in Forever they respawn much faster, so you need to outlevel them by quite a few levels{/b}, or they will keep respawning right on top of you."] = "怪物大約 21-22 級，{b}而在 Forever 中牠們重生得快很多，所以你的等級要比牠們高出不少{/b}，否則牠們會不斷在你身上重生。",
  ["Mining route in Silverpine Forest"] = "銀松森林的採礦路線",
  ["This cave has several Tin Veins that respawn very fast. There are also veins outside, so if you clear it too fast you can just run outside and mine a few there too."] = "這個洞穴有好幾個重生很快的錫礦脈。外面也有礦脈，所以如果你清得太快，可以跑出去挖幾個。",
  ["The mobs are around level 13-15 and {b}in Forever they respawn much faster, so you need to outlevel them by quite a few levels{/b}, or they will keep respawning right on top of you."] = "怪物大約 13-15 級，{b}而在 Forever 中牠們重生得快很多，所以你的等級要比牠們高出不少{/b}，否則牠們會不斷在你身上重生。",
  ["Mining route in Westfall"] = "西部荒野的採礦路線",
  ["This is the best if you prefer mining the normal way, but you might have more competition from other players because this is a popular area. The route goes around a Horde town, so I'm not sure how it works for Alliance. I think you can probably avoid the guards, but I only tested this one with a Horde character."] = "如果你偏好一般的挖礦方式，這裡是最好的，但這是熱門區域，可能會有較多玩家跟你搶。路線會繞過一座部落城鎮，所以我不確定聯盟走起來如何。我想你大概能避開衛兵，但我只用部落角色測試過。",
  ["Mining route in Hillsbrad Foothills"] = "希爾斯布萊德丘陵的採礦路線",
  ["The mobs are around level 22-26 here, so it's best to farm here if you are above those levels. But the respawn rate is fast."] = "這裡的怪物大約 22-26 級，所以最好在你高於這個等級時來這裡刷。不過重生速度很快。",
  ["Mining route in The Barrens"] = "貧瘠之地的採礦路線",
  ["A very straightforward route that is easy to follow. This is the best if you prefer mining the normal way, but you might have more competition from other players because this is a popular area."] = "非常簡單好跟的路線。如果你偏好一般的挖礦方式，這裡是最好的，但這是熱門區域，可能會有較多玩家跟你搶。",
  ["Mining route in Ashenvale"] = "梣谷的採礦路線",
  ["This route might not work if more than one player is leveling Mining there, because when I tested it there were very few people around. But this place usually has fewer people, so I think it's a good alternative if you don't want to level in caves. The only downside is that sometimes an Iron Deposit spawns instead of a Tin Vein, and you can't mine it yet."] = "如果有不只一位玩家在這裡練採礦，這條路線可能行不通，因為我測試時周圍人很少。不過這裡通常人比較少，所以如果你不想在洞穴裡升級，我認為這是不錯的替代方案。唯一的缺點是有時重生的是鐵礦床而不是錫礦脈，而你還不能採。",
  ["Mining route in Stonetalon Mountains"] = "石爪山脈的採礦路線",
  ["From this point the guide follows the standard Classic Mining routes. The beta cap was 30, so I couldn't properly test Arathi and Desolace. I'll revise this section once I level my character higher on live, but the main change is the ore respawn rate, so most routes should work and you can probably take shorter routes in most zones."] = "從這裡開始，指南採用經典版的標準採礦路線。測試版的等級上限是 30，所以我無法好好測試阿拉希和淒涼之地。等我在正式伺服器把角色練高後會修訂這一部分，但主要的變化是礦石重生速度，所以大多數路線應該都可行，而且在大多數區域你大概可以走更短的路線。",
  ["{b}Visit your trainer and learn Expert Mining{/b}, it requires Mining 125."] = "{b}找訓練師學習專家採礦{/b}，需要採礦 125。",
  ["Smelting Iron and Gold (optional)"] = "熔煉鐵和金（選擇性）",
  ["If you want to save some time and have the gold, buy around 20 {i:2772:inv_ore_iron_01:Iron Ore} and make {s:3307:inv_ingot_iron:Smelt Iron} until 135 before you head out mining. After 135 it rarely gives a point, so don't count on reaching 140."] = "如果你想省點時間又有金幣，出發挖礦前先買大約 20 個 {i:2772:inv_ore_iron_01:Iron Ore}，用 {s:3307:inv_ingot_iron:Smelt Iron} 升到 135。135 之後很少給點，所以別指望升到 140。",
  ["At 155 you can learn {s:3308:inv_ingot_03:Smelt Gold} from your trainer. It gives a point every time until 170, so around 22 Gold Ore takes you from 155 to 175 and you can start on Mithril right away. I recommend checking the price of Gold Ore and Gold Bar first."] = "在 155 你可以向訓練師學習 {s:3308:inv_ingot_03:Smelt Gold}。到 170 之前每次都會給一點，所以大約 22 個金礦石就能讓你從 155 升到 175，然後馬上開始挖秘銀。我建議先查看金礦石和金錠的價格。",
  ["If you have a {b}lower level character{/b} around level 30, stick to the {b}Thousand Needles{/b} route, that's the safest. If you have a {b}higher level character or a mount{/b} already, I recommend {b}Arathi Highlands{/b}."] = "如果你是 30 級左右的{b}低等級角色{/b}，就走{b}千針石林{/b}的路線，那是最安全的。如果你已經是{b}高等級角色或有坐騎{/b}，我推薦{b}阿拉希高地{/b}。",
  ["Ores in these zones: {i:2772:inv_ore_iron_01:Iron Ore}, {i:2771:inv_ore_tin_01:Tin Ore}, {i:2776:inv_ore_gold_01:Gold Ore}"] = "這些區域的礦石：{i:2772:inv_ore_iron_01:Iron Ore}、{i:2771:inv_ore_tin_01:Tin Ore}、{i:2776:inv_ore_gold_01:Gold Ore}",
  ["Iron Deposits need Mining 125 and Gold Veins 155."] = "鐵礦床需要採礦 125，金礦脈需要 155。",
  ["Arathi Highlands"] = "阿拉希高地",
  ["Thousand Needles"] = "千針石林",
  ["Desolace"] = "淒涼之地",
  ["There are 4 caves marked with red circles on the map. Make sure to go all the way to the end of each cave because you won't see all the mining veins from the entrance."] = "地圖上用紅圈標示了 4 個洞穴。請務必走到每個洞穴的最深處，因為從入口看不到所有礦脈。",
  ["Low level players should skip all 4 caves, and low level Alliance players should take a detour and go south of Hammerfall!"] = "低等級玩家應該跳過全部 4 個洞穴，低等級聯盟玩家則應該繞路，從落錘鎮南邊走！",
  ["Mining route in Arathi Highlands"] = "阿拉希高地的採礦路線",
  ["Mining route in Thousand Needles"] = "千針石林的採礦路線",
  ["Mining route in Desolace"] = "淒涼之地的採礦路線",
  ["To train past 225, visit your trainer and learn Artisan Mining, it requires Mining 200."] = "要學習 225 以上，請找訓練師學習工匠採礦，需要採礦 200。",
  ["Ores in these zones: {i:3858:inv_ore_mithril_02:Mithril Ore}, {i:7911:inv_ore_truesilver_01:Truesilver Ore}"] = "這些區域的礦石：{i:3858:inv_ore_mithril_02:Mithril Ore}、{i:7911:inv_ore_truesilver_01:Truesilver Ore}",
  ["Mithril Deposits need Mining 175 and Truesilver Deposits 230."] = "秘銀礦床需要採礦 175，真銀礦床需要 230。",
  ["The Hinterlands"] = "辛特蘭",
  ["Tanaris"] = "塔納利斯",
  ["The red route should be skipped by lower level players because the area is filled with level 62 elites. Lower level players might also want to consider skipping the cave marked with a red circle on the map. (depends on your gear/class)"] = "較低等級的玩家應該跳過紅色路線，因為那一帶都是 62 級精英怪。較低等級的玩家也可以考慮跳過地圖上紅圈標示的洞穴。（視你的裝備/職業而定）",
  ["Mining route in The Hinterlands"] = "辛特蘭的採礦路線",
  ["Players below level 60 should skip the 4 caves marked with red circles."] = "60 級以下的玩家應該跳過紅圈標示的 4 個洞穴。",
  ["Mining route in Tanaris"] = "塔納利斯的採礦路線",
  ["Ores in these zones: {i:3858:inv_ore_mithril_02:Mithril Ore}, {i:7911:inv_ore_truesilver_01:Truesilver Ore}, {i:10620:inv_ore_thorium_02:Thorium Ore}"] = "這些區域的礦石：{i:3858:inv_ore_mithril_02:Mithril Ore}、{i:7911:inv_ore_truesilver_01:Truesilver Ore}、{i:10620:inv_ore_thorium_02:Thorium Ore}",
  ["Small Thorium Veins need Mining 245."] = "瑟銀礦脈需要採礦 245。",
  ["Un'Goro Crater"] = "安戈洛環形山",
  ["Blasted Lands"] = "詛咒之地",
  ["Felwood"] = "費伍德森林",
  ["You will find 2-3 veins in the two caves marked with red circles on the map."] = "在地圖上紅圈標示的兩個洞穴裡，你會找到 2-3 個礦脈。",
  ["Lower level players should probably skip the cave to the south. It really depends on your level, gear and class."] = "較低等級的玩家可能應該跳過南邊的洞穴。這真的要看你的等級、裝備和職業。",
  ["Mining route in Un'Goro Crater"] = "安戈洛環形山的採礦路線",
  ["Both caves marked with red circles have a lot of mobs inside, so I only recommend this zone to level 60 players with good gear, or to Druids and Rogues with stealth."] = "紅圈標示的兩個洞穴裡都有很多怪物，所以我只推薦裝備好的 60 級玩家，或有潛行的德魯伊和盜賊來這個區域。",
  ["It's really hard to navigate inside the Garrison Armory mine, so I included a small map. {b}Alliance{/b} players can't mine inside the Garrison Armory!"] = "要塞軍械庫礦坑裡很難找路，所以我附了一張小地圖。{b}聯盟{/b}玩家無法在要塞軍械庫裡挖礦！",
  ["Mining route in the Blasted Lands"] = "詛咒之地的採礦路線",
  ["There are usually 2 veins inside the cave marked with a red circle. It's worth going in because the cave is small and there aren't many mobs inside, and if you are high level, you can pass some of them without aggro."] = "紅圈標示的洞穴裡通常有 2 個礦脈。值得進去，因為洞穴很小、怪物不多，如果你等級夠高，有些怪可以直接走過去不會被仇恨。",
  ["I recommend skipping the other two caves at Jaedenar, especially Shadow Hold. (if you have stealth, they might be worth going into)"] = "我建議跳過加德納爾的另外兩個洞穴，尤其是暗影堡。（如果你有潛行，也許值得進去）",
  ["Mining route in Felwood"] = "費伍德森林的採礦路線",
  ["Ores in these zones: {i:10620:inv_ore_thorium_02:Thorium Ore}, {i:3858:inv_ore_mithril_02:Mithril Ore}"] = "這些區域的礦石：{i:10620:inv_ore_thorium_02:Thorium Ore}、{i:3858:inv_ore_mithril_02:Mithril Ore}",
  ["At 275 you can mine Rich Thorium Veins too."] = "到 275 你也能採富瑟銀礦脈。",
  ["Eastern Plaguelands"] = "東瘟疫之地",
  ["Winterspring"] = "冬泉谷",
  ["Burning Steppes"] = "燃燒平原",
  ["Almost the same as the previous Un'Goro route, but now it includes Rich Thorium Veins."] = "和前面安戈洛的路線幾乎一樣，但現在包含了富瑟銀礦脈。",
  ["Mining route with Rich Thorium Veins in Un'Goro Crater"] = "安戈洛環形山包含富瑟銀礦脈的採礦路線",
  ["The red line is full of level 57-58 elites, so if your gear is bad, you should probably skip that part unless you have stealth. With some practice you can usually get through and only pull a few of them."] = "紅線上滿是 57-58 級的精英怪，所以如果你裝備不好，除非有潛行，否則最好跳過那部分。多練習幾次，通常只會拉到少數幾隻就能通過。",
  ["Mining route in the Eastern Plaguelands"] = "東瘟疫之地的採礦路線",
  ["The mobs in this cave are not that hard, so most classes can clear it. (depends on your gear)"] = "這個洞穴裡的怪物沒那麼難，所以大多數職業都能清掉。（視你的裝備而定）",
  ["Most classes can get into at least the first part of the cave without pulling aggro. You can try going deeper depending on your gear."] = "大多數職業至少能進到洞穴的第一段而不被仇恨。視你的裝備，可以試著再往深處走。",
  ["A lot of elites patrol this gorge, but you can usually pass most of them without pulling aggro. Sometimes you have to kill 1 or 2."] = "這個峽谷有很多精英怪巡邏，但通常大部分都能避開不被仇恨。有時得殺掉 1 到 2 隻。",
  ["I don't recommend this area for most players because it's hard to farm here without dying. It really depends on your class and how good you are at avoiding mobs."] = "我不推薦大多數玩家來這一帶，因為在這裡刷很難不死。這真的要看你的職業，以及你閃避怪物的功力。",
  ["Mining route in Winterspring"] = "冬泉谷的採礦路線",
  ["The two caves marked with red circles are full of level 50 mobs, so lower level players might want to skip them. (depends on your gear and level)"] = "紅圈標示的兩個洞穴裡都是 50 級的怪物，所以較低等級的玩家可能要跳過。（視你的裝備和等級而定）",
  ["Mining route in the Burning Steppes"] = "燃燒平原的採礦路線",
  ["This WoW Forever Herbalism leveling guide will show you the fastest way to level Herbalism from 1 to 300. You will also find a route map for every zone, every trainer location and where to train Herbalism past 75, 150 and 225."] = "這份 WoW Forever 草藥學升級指南將告訴你如何以最快的方式將草藥學從 1 升到 300。你也能找到每個區域的路線圖、每位訓練師的位置，以及在 75、150 和 225 之後要去哪裡繼續學習草藥學。",
  ["Below you will find the Herbalism trainers by starting zone and capital city, and the best zones to pick herbs in for every skill range. Herbalism goes well with Alchemy because you can use the herbs you pick to make potions and elixirs, so check out my Forever Alchemy leveling guide if you want to level Alchemy. But keep in mind, this guide is made to level Herbalism as fast as possible, so sometimes the herbs you pick are not the best ones for Alchemy."] = "下方有依新手區與主城分類的草藥學訓練師，以及每個技能區間最適合採草藥的區域。草藥學很適合搭配鍊金術，因為你可以用採到的草藥製作藥水和藥劑，所以如果你想練鍊金術，請看我的 Forever 鍊金術升級指南。但請記住，本指南是為了盡快練草藥學而寫的，所以有時你採的草藥並不是鍊金術最需要的。",
  ["WoW Forever added a couple of new herbs, seeds and recipes. You can check them out here:"] = "WoW Forever 新增了一些新的草藥、種子和配方。你可以在這裡查看：",
  ["Herbalism Trainer Locations"] = "草藥學訓練師位置",
  ["Every capital city has a Herbalism trainer. You can also ask a guard where the herbalist is, then it will be marked with a red flag on your map."] = "每座主城都有草藥學訓練師。你也可以詢問衛兵草藥師在哪裡，地圖上就會用紅旗標出位置。",
  ["Orgrimmar: {n:0:horde:Jandi}"] = "奧格瑪：{n:0:horde:Jandi}",
  ["Undercity: {n:0:horde:Martha Alliestar}"] = "幽暗城：{n:0:horde:Martha Alliestar}",
  ["Thunder Bluff: {n:0:horde:Komin Winterhoof}"] = "雷霆崖：{n:0:horde:Komin Winterhoof}",
  ["{n:0:horde:Zor'la} in the Valley of Trials (only up to 75) {n:0:horde:Mishiki} in Sen'jin Village"] = "試煉谷的 {n:0:horde:Zor'la}（最多只到 75） 森金村的 {n:0:horde:Mishiki}",
  ["{n:0:horde:Garan Sunstrider} in Camp Narache (only up to 75) {n:0:horde:Komin Winterhoof} in Thunder Bluff"] = "納拉其營地的 {n:0:horde:Garan Sunstrider}（最多只到 75） 雷霆崖的 {n:0:horde:Komin Winterhoof}",
  ["{n:0:horde:Florence Nightshade} in Deathknell (only up to 75) {n:0:horde:Faruza} in Brill"] = "喪鐘鎮的 {n:0:horde:Florence Nightshade}（最多只到 75） 布瑞爾的 {n:0:horde:Faruza}",
  ["There is no trainer in Thendal Village, where you start, but you don't need one. {q:93552::Harvesting Windstones} is one of the first quests you get in Thendal Village. Pick {i:247841:inv_10_specialization_professionbook_herbalism_color1:Wild Harvest} as your reward, it teaches you Herbalism. The trainers on the island are {n:0::Syriel Nightrain} in Valanaar and {n:0::Halassa Fernbreeze} in Shen'dar Village."] = "你出生的坦達爾村沒有訓練師，但你也不需要。{q:93552::Harvesting Windstones} 是你在坦達爾村最早接到的任務之一。選擇 {i:247841:inv_10_specialization_professionbook_herbalism_color1:Wild Harvest} 作為獎勵，它會教你草藥學。島上的訓練師是瓦拉納爾的 {n:0::Syriel Nightrain} 和申達爾村的 {n:0::Halassa Fernbreeze}。",
  ["Stormwind City: {n:0:alliance:Tannysa}"] = "暴風城：{n:0:alliance:Tannysa}",
  ["Ironforge: {n:0:alliance:Reyna Stonebranch}"] = "鐵爐堡：{n:0:alliance:Reyna Stonebranch}",
  ["Darnassus: {n:0:alliance:Firodren Mooncaller}"] = "達納蘇斯：{n:0:alliance:Firodren Mooncaller}",
  ["{n:0:alliance:Nancy Songflower} (only up to 75) {n:0:alliance:Herbalist Pomeroy}"] = "{n:0:alliance:Nancy Songflower}（最多只到 75） {n:0:alliance:Herbalist Pomeroy}",
  ["{n:0:alliance:Emrys Flintbeard} (only up to 75) {n:0:alliance:Reyna Stonebranch} in Ironforge"] = "{n:0:alliance:Emrys Flintbeard}（最多只到 75） 鐵爐堡的 {n:0:alliance:Reyna Stonebranch}",
  ["{n:0:alliance:Eleyna Duskbreeze} at Aldrassil in Shadowglen (only up to 75) {n:0:alliance:Malorne Bladeleaf} in Dolanaar"] = "影谷奧達希爾的 {n:0:alliance:Eleyna Duskbreeze}（最多只到 75） 多蘭納爾的 {n:0:alliance:Malorne Bladeleaf}",
  ["You can find every Herbalism trainer for Horde and Alliance on my WoW Forever Herbalism Trainers page."] = "你可以在我的 WoW Forever 草藥學訓練師頁面找到部落和聯盟的所有草藥學訓練師。",
  ["Track Herbs on Your Minimap"] = "在小地圖上追蹤草藥",
  ["You can only track one thing at a time, so {b}you can't track herbs and minerals together{/b}."] = "你一次只能追蹤一種東西，所以{b}無法同時追蹤草藥和礦物{/b}。",
  ["You learn {s:2383:inv_misc_flower_02:Find Herbs} together with Herbalism, but it's not turned on by default:"] = "學會草藥學時你會一併獲得 {s:2383:inv_misc_flower_02:Find Herbs}，但它預設沒有開啟：",
  ["Click Find Herbs in the Herbalism box. {b}I recommend dragging it to your action bar, close to the buffs you use after you die.{/b} This way you make a habit out of it and you are less likely to forget it."] = "點擊草藥學欄位中的尋找草藥。{b}我建議把它拖到快捷列上，放在你死亡後會使用的增益技能附近。{/b}這樣你會養成習慣，比較不容易忘記。",
  ["The Find Herbs buff shows up next to your minimap. {b}Your tracking turns off every time you die, so don't forget to turn it back on!{/b}"] = "尋找草藥的增益效果會顯示在小地圖旁邊。{b}每次死亡時追蹤都會關閉，別忘了重新開啟！{/b}",
  ["Herbalism Skill Bonuses"] = "草藥學技能加成",
  ["You don't need these, but they help when you are stuck between two herbs. With +5 you can pick Kingsblood from 120 instead of 125, so you can move on earlier."] = "這些不是必需的，但當你卡在兩種草藥之間時很有幫助。有 +5 的話，你在 120 就能採皇血草，不必等到 125，可以更早往下一步走。",
  ["Herbalism"] = "草藥學",
  ["A world drop, check the Auction House"] = "世界掉落，請查看拍賣場",
  ["Henry Stern in Razorfen Downs teaches the recipe, it {b}requires Cooking 175{/b}. Take the left path at the start of the instance and go all the way to the end, to the stables, knock down the walls and talk to him."] = "剃刀高地的 Henry Stern 會教這個配方，{b}需要烹飪 175{/b}。進副本後走左邊的路一直走到底的獸欄，打破牆壁後和他對話。",
  ["can be very handy when you find a herb you can't pick yet and you are only a few points short. It will probably be pretty expensive early on because of the Goldthorn prices, but it's worth keeping a few with you while you level Herbalism."] = "當你發現一株還不能採的草藥、只差幾點時非常好用。由於金棘草的價格，初期可能會很貴，但在練草藥學時身上帶幾個是值得的。",
  ["Every starting zone is full of herbs, so it doesn't really matter which one you choose. The respawn rate is so fast that without a mount you often can't even finish a full lap, you just run around in circles and pick the herbs as you see them."] = "每個新手區都滿是草藥，所以選哪一個其實沒差。重生速度快到沒有坐騎時常常連一整圈都跑不完，你只是在原地繞圈，看到草藥就採。",
  ["Herbs in these zones: {i:2447:inv_misc_flower_02:Peacebloom}, {i:765:inv_misc_herb_10:Silverleaf}, {i:2449:inv_misc_herb_07:Earthroot}"] = "這些區域的草藥：{i:2447:inv_misc_flower_02:Peacebloom}、{i:765:inv_misc_herb_10:Silverleaf}、{i:2449:inv_misc_herb_07:Earthroot}",
  ["Earthroot requires Herbalism 15."] = "地根草需要草藥學 15。",
  ["Herbalism route in Durotar"] = "杜洛塔的草藥學路線",
  ["Herbalism route in Mulgore"] = "莫高雷的草藥學路線",
  ["Herbalism route in Tirisfal Glades"] = "提里斯法林地的草藥學路線",
  ["{q:93552::Harvesting Windstones} is one of the first quests you get in Thendal Village. Pick {i:247841:inv_10_specialization_professionbook_herbalism_color1:Wild Harvest} as your reward, it teaches you Herbalism."] = "{q:93552::Harvesting Windstones} 是你在坦達爾村最早接到的任務之一。選擇 {i:247841:inv_10_specialization_professionbook_herbalism_color1:Wild Harvest} 作為獎勵，它會教你草藥學。",
  ["Herbalism route on Zephras Isle"] = "澤弗拉斯島的草藥學路線",
  ["Herbalism route in Elwynn Forest"] = "艾爾文森林的草藥學路線",
  ["Herbalism route in Dun Morogh"] = "丹莫洛的草藥學路線",
  ["Herbalism route in Teldrassil"] = "泰達希爾的草藥學路線",
  ["Visit your trainer and learn Journeyman Herbalism, it requires Herbalism 50. The new Junior Herbalism Trainers in the starting areas won't teach you Journeyman Herbalism."] = "找訓練師學習熟手草藥學，需要草藥學 50。新手區新增的初級草藥學訓練師不會教熟手草藥學。",
  ["Herbs in these zones: {i:785:inv_jewelry_talisman_03:Mageroyal}, {i:2450:inv_misc_root_01:Briarthorn}, {i:3820:inv_misc_herb_11:Stranglekelp}"] = "這些區域的草藥：{i:785:inv_jewelry_talisman_03:Mageroyal}、{i:2450:inv_misc_root_01:Briarthorn}、{i:3820:inv_misc_herb_11:Stranglekelp}",
  ["Stranglekelp requires Herbalism 85, so you can't pick it right away."] = "荊棘藻需要草藥學 85，所以你無法馬上採。",
  ["Loch Modan"] = "洛克莫丹",
  ["The respawn rate in the lower part of Silverpine Forest is fast enough that you can basically run in small circles in the marked area. I tested this without a mount, so with a mount it might be different, but then running up and down the main road to the loop should work fine as well."] = "銀松森林南部的重生速度夠快，你基本上可以在標示區域內繞小圈。我是在沒有坐騎的情況下測試的，有坐騎可能會不一樣，但那樣的話沿著主要道路上下跑到環線應該也可以。",
  ["Herbalism route in Silverpine Forest"] = "銀松森林的草藥學路線",
  ["A very easy route to follow, but there might be a bit fewer herbs than in Darkshore."] = "非常好跟的路線，但草藥可能比黑海岸少一點。",
  ["Herbalism route in Loch Modan"] = "洛克莫丹的草藥學路線",
  ["Darkshore has herbs everywhere. I used this loop, but you can also expand it to the upper part of the map. The respawn rate is fast, so you can do smaller circles in different areas. I just found this route pretty easy and chill to follow."] = "黑海岸到處都是草藥。我走的是這個環線，但你也可以擴展到地圖的上半部。重生速度很快，所以你可以在不同區域繞小圈。我只是覺得這條路線很好跟又輕鬆。",
  ["Herbalism route in Darkshore"] = "黑海岸的草藥學路線",
  ["To train past 150, visit your trainer and learn Expert Herbalism, it requires Herbalism 125."] = "要學習 150 以上，請找訓練師學習專家草藥學，需要草藥學 125。",
  ["Herbs in these zones: {i:2453:inv_misc_herb_01:Bruiseweed}, {i:3355:inv_misc_flower_01:Wild Steelbloom}, {i:3820:inv_misc_herb_11:Stranglekelp}, {i:3356:inv_misc_herb_03:Kingsblood}, {i:3357:inv_misc_root_02:Liferoot}"] = "這些區域的草藥：{i:2453:inv_misc_herb_01:Bruiseweed}、{i:3355:inv_misc_flower_01:Wild Steelbloom}、{i:3820:inv_misc_herb_11:Stranglekelp}、{i:3356:inv_misc_herb_03:Kingsblood}、{i:3357:inv_misc_root_02:Liferoot}",
  ["Kingsblood requires Herbalism 125 and Liferoot 150, so you can't pick them right away."] = "皇血草需要草藥學 125，活根草需要 150，所以你無法馬上採。",
  ["Running this loop in Hillsbrad Foothills gives the herbs enough time to respawn, but I tested it without a mount, so with a mount it might be different."] = "在希爾斯布萊德丘陵跑這個環線能讓草藥有足夠的時間重生，但我是在沒有坐騎的情況下測試的，有坐騎可能會不一樣。",
  ["Herbalism route in Hillsbrad Foothills"] = "希爾斯布萊德丘陵的草藥學路線",
  ["All three areas are good here:"] = "這裡三個區域都不錯：",
  ["The mobs here are only around level 14-15, so this is the lowest level area where you can safely farm these herbs."] = "這裡的怪物只有 14-15 級左右，所以這是能安全採這些草藥的最低等級區域。",
  ["A good alternative if someone is already farming the first area. The mobs are higher level here, around 25."] = "如果第一個區域已經有人在採，這是不錯的替代方案。這裡的怪物等級較高，大約 25 級。",
  ["This area is usually pretty crowded and full of mobs. {b}I only recommend it if you are over 125 already{/b}, because there is more Kingsblood here."] = "這一帶通常很擁擠，怪物也很多。{b}我只推薦已經超過 125 的人來{/b}，因為這裡的皇血草比較多。",
  ["Herbalism route in Stonetalon Mountains"] = "石爪山脈的草藥學路線",
  ["From this point the guide follows the standard Classic Herbalism routes. The beta cap was 30, so I couldn't test the higher level routes. I'll revise this section once I level my character higher on live, but the main change is the herb respawn rate, so most routes should work."] = "從這裡開始，指南採用經典版的標準草藥學路線。測試版的等級上限是 30，所以我無法測試較高等級的路線。等我在正式伺服器把角色練高後會修訂這一部分，但主要的變化是草藥重生速度，所以大多數路線應該都可行。",
  ["Herbs in these zones: {i:3356:inv_misc_herb_03:Kingsblood}, {i:3357:inv_misc_root_02:Liferoot}, {i:3818:inv_misc_herb_12:Fadeleaf}, {i:3821:inv_misc_herb_15:Goldthorn}, {i:3358:inv_misc_herb_08:Khadgar's Whisker}"] = "這些區域的草藥：{i:3356:inv_misc_herb_03:Kingsblood}、{i:3357:inv_misc_root_02:Liferoot}、{i:3818:inv_misc_herb_12:Fadeleaf}、{i:3821:inv_misc_herb_15:Goldthorn}、{i:3358:inv_misc_herb_08:Khadgar's Whisker}",
  ["Khadgar's Whisker requires Herbalism 185, so you can't pick it right away."] = "卡德加的鬍鬚需要草藥學 185，所以你無法馬上採。",
  ["Stranglethorn Vale"] = "荊棘谷",
  ["Herbalism route in Stranglethorn Vale"] = "荊棘谷的草藥學路線",
  ["Herbalism route in Arathi Highlands"] = "阿拉希高地的草藥學路線",
  ["{b}Learn Artisan Herbalism before you leave for these zones{/b}, it requires Herbalism 200. There is no trainer in Tanaris or Searing Gorge, so if you skip it, you have to fly back at 225."] = "{b}出發前往這些區域之前先學會工匠草藥學{/b}，需要草藥學 200。塔納利斯和灼熱峽谷都沒有訓練師，所以如果你跳過了，到 225 時就得飛回去。",
  ["Herbs in these zones: {i:8831:inv_misc_herb_17:Purple Lotus}, {i:4625:inv_misc_herb_19:Firebloom}"] = "這些區域的草藥：{i:8831:inv_misc_herb_17:Purple Lotus}、{i:4625:inv_misc_herb_19:Firebloom}",
  ["Searing Gorge"] = "灼熱峽谷",
  ["Herbalism route in Tanaris"] = "塔納利斯的草藥學路線",
  ["Herbalism route in Searing Gorge"] = "灼熱峽谷的草藥學路線",
  ["Herbs in The Hinterlands: {i:8838:inv_misc_herb_18:Sungrass}, {i:8831:inv_misc_herb_17:Purple Lotus}, {i:8845:inv_mushroom_08:Ghost Mushroom}, {i:13464:inv_misc_herb_sansamroot:Golden Sansam}"] = "辛特蘭的草藥：{i:8838:inv_misc_herb_18:Sungrass}、{i:8831:inv_misc_herb_17:Purple Lotus}、{i:8845:inv_mushroom_08:Ghost Mushroom}、{i:13464:inv_misc_herb_sansamroot:Golden Sansam}",
  ["I marked a cave with a red X, there are a lot of Ghost Mushrooms in the cave, but you can only pick them with Herbalism 245."] = "我用紅色 X 標了一個洞穴，洞裡有很多鬼魂菇，但要草藥學 245 才能採。",
  ["Herbalism route in The Hinterlands"] = "辛特蘭的草藥學路線",
  ["Herbs in Felwood: {i:8838:inv_misc_herb_18:Sungrass}, {i:8846:inv_misc_herb_16:Gromsblood}, {i:13464:inv_misc_herb_sansamroot:Golden Sansam}, {i:13463:inv_misc_herb_dreamfoil:Dreamfoil}, {i:13465:inv_misc_herb_mountainsilversage:Mountain Silversage}, {i:13466:inv_misc_herb_plaguebloom:Plaguebloom}"] = "費伍德森林的草藥：{i:8838:inv_misc_herb_18:Sungrass}、{i:8846:inv_misc_herb_16:Gromsblood}、{i:13464:inv_misc_herb_sansamroot:Golden Sansam}、{i:13463:inv_misc_herb_dreamfoil:Dreamfoil}、{i:13465:inv_misc_herb_mountainsilversage:Mountain Silversage}、{i:13466:inv_misc_herb_plaguebloom:Plaguebloom}",
  ["Herbalism route in Felwood"] = "費伍德森林的草藥學路線",
  ["This WoW Forever Skinning leveling guide will show you the fastest way to level Skinning from 1 to 300. You will also find every trainer location and the best places to skin for each skill range."] = "這份 WoW Forever 剝皮升級指南將告訴你如何以最快的方式將剝皮從 1 升到 300。你也能找到每位訓練師的位置，以及每個技能區間最適合剝皮的地點。",
  ["This guide is aimed at higher level players who want to switch their profession, but it's good for lower level players too. Leveling Skinning is easy but really boring, you will have to run around and skin hundreds of mobs. Skinning goes well with Leatherworking because you can use the leather you skin, so check out my Forever Leatherworking leveling guide if you want to level Leatherworking."] = "本指南主要針對想轉換專業的高等級玩家，但對低等級玩家也很適用。練剝皮很簡單但真的很無聊，你得到處跑、剝上數百隻怪物。剝皮很適合搭配製皮，因為你可以使用自己剝下來的皮革，所以如果你想練製皮，請看我的 Forever 製皮升級指南。",
  ["Skinning Trainer Locations"] = "剝皮訓練師位置",
  ["Every capital city has a Skinning trainer. You can also ask a guard, then it will be marked with a red flag on your map."] = "每座主城都有剝皮訓練師。你也可以詢問衛兵，地圖上就會用紅旗標出位置。",
  ["Orgrimmar: {n:0:horde:Thuwd}"] = "奧格瑪：{n:0:horde:Thuwd}",
  ["Undercity: {n:0:horde:Killian Hagey}"] = "幽暗城：{n:0:horde:Killian Hagey}",
  ["Thunder Bluff: {n:0:horde:Mooranta}"] = "雷霆崖：{n:0:horde:Mooranta}",
  ["{n:0:horde:Kagil} in the Valley of Trials (only up to 75) {n:0:horde:Thuwd} in Orgrimmar"] = "試煉谷的 {n:0:horde:Kagil}（最多只到 75） 奧格瑪的 {n:0:horde:Thuwd}",
  ["{n:0:horde:Nawka Wildsong} in Camp Narache (only up to 75) {n:0:horde:Yonn Deepcut} in Bloodhoof Village"] = "納拉其營地的 {n:0:horde:Nawka Wildsong}（最多只到 75） 血蹄村的 {n:0:horde:Yonn Deepcut}",
  ["{n:0:horde:Margaret Weaver} in Deathknell (only up to 75) {n:0:horde:Rand Rhobart} in Tirisfal Glades"] = "喪鐘鎮的 {n:0:horde:Margaret Weaver}（最多只到 75） 提里斯法林地的 {n:0:horde:Rand Rhobart}",
  ["There is no trainer in Thendal Village, where you start, but you don't need one. {q:93552::Harvesting Windstones} is one of the first quests you get in Thendal Village. Pick {i:247846:inv_10_specialization_professionbook_skinning_color1:Pelt Collecting for Beginners} as your reward, it teaches you Skinning. The trainers on the island are {n:0::Ishlee Breezewhisper} in Valanaar and {n:0::Mendalass Tattermend} in Shen'dar Village."] = "你出生的坦達爾村沒有訓練師，但你也不需要。{q:93552::Harvesting Windstones} 是你在坦達爾村最早接到的任務之一。選擇 {i:247846:inv_10_specialization_professionbook_skinning_color1:Pelt Collecting for Beginners} 作為獎勵，它會教你剝皮。島上的訓練師是瓦拉納爾的 {n:0::Ishlee Breezewhisper} 和申達爾村的 {n:0::Mendalass Tattermend}。",
  ["Stormwind City: {n:0:alliance:Maris Granger}"] = "暴風城：{n:0:alliance:Maris Granger}",
  ["Ironforge: {n:0:alliance:Balthus Stoneflayer}"] = "鐵爐堡：{n:0:alliance:Balthus Stoneflayer}",
  ["Darnassus: {n:0:alliance:Eladriel}"] = "達納蘇斯：{n:0:alliance:Eladriel}",
  ["{n:0:alliance:Riley Peltskinner} in Northshire Valley (only up to 75) {n:0:alliance:Helene Peltskinner} in Goldshire"] = "北郡山谷的 {n:0:alliance:Riley Peltskinner}（最多只到 75） 閃金鎮的 {n:0:alliance:Helene Peltskinner}",
  ["{n:0:alliance:Brighid Stormflayer} (only up to 75) {n:0:alliance:Balthus Stoneflayer} in Ironforge"] = "{n:0:alliance:Brighid Stormflayer}（最多只到 75） 鐵爐堡的 {n:0:alliance:Balthus Stoneflayer}",
  ["{n:0:alliance:Terunne Bearshaper} at Aldrassil in Shadowglen (only up to 75) {n:0:alliance:Radnaal Maneweaver} in Teldrassil"] = "影谷奧達希爾的 {n:0:alliance:Terunne Bearshaper}（最多只到 75） 泰達希爾的 {n:0:alliance:Radnaal Maneweaver}",
  ["You can find every Skinning trainer for Horde and Alliance on my WoW Forever Skinning Trainers page."] = "你可以在我的 WoW Forever 剝皮訓練師頁面找到部落和聯盟的所有剝皮訓練師。",
  ["Skinning Skill Requirements"] = "剝皮技能需求",
  ["You need 5 times the mob's level in Skinning to skin it, so a level 30 mob needs Skinning 150. Below level 20 it's less, if you follow the guide you don't have to worry about this."] = "剝皮技能需要達到怪物等級的 5 倍才能剝牠，所以 30 級的怪物需要剝皮 150。20 級以下的需求較低，如果你照著指南走就不用擔心這個。",
  ["Mob level"] = "怪物等級",
  ["Skinning needed"] = "所需剝皮技能",
  ["10 for a level 11 mob, 10 more for every level (level 15 needs 50, level 19 needs 90)"] = "11 級怪物需要 10，每多一級再加 10（15 級需要 50，19 級需要 90）",
  ["20 and up"] = "20 級以上",
  ["5 times the level"] = "等級的 5 倍",
  ["If you enchant your gloves with {s:13698:spell_holy_greaterheal:Enchant Gloves - Skinning}, you can skin mobs 1 level higher than normal."] = "如果你的手套附魔了 {s:13698:spell_holy_greaterheal:Enchant Gloves - Skinning}，就能剝比平常高 1 級的怪物。",
  ["Horde players can also pick the {i:269716:inv_weapon_shortblade_05:Keen Skinning Knife} (+3 Skinning) as a reward from Unwelcome Guests in The Barrens."] = "部落玩家也可以在貧瘠之地的 Unwelcome Guests 任務中選擇 {i:269716:inv_weapon_shortblade_05:Keen Skinning Knife}（+3 剝皮）作為獎勵。",
  ["In WoW Forever you can skin the mobs in the starting areas, and they give skill points all the way up to 75."] = "在 WoW Forever 中你可以剝新手區的怪物，而且牠們一直到 75 都會給技能點。",
  ["{b}Any starting zone is good{/b} for this. If you are leveling a new character, you can skin any mob in your starting zone, so you don't need a recommendation until around level 10, when you leave the zone. The two places below are for players who already have a higher level character and want to catch up on Skinning. A lot of players will be leveling new characters there, so there is always something to skin."] = "{b}任何新手區都可以{/b}。如果你在練新角色，可以剝新手區裡的任何怪物，所以在大約 10 級離開新手區之前都不需要推薦地點。下面兩個地點是給已經有高等級角色、想把剝皮補上來的玩家。很多玩家會在那裡練新角色，所以總是有東西可以剝。",
  ["{b}Don't forget to buy a {i:7005:inv_weapon_shortblade_01:Skinning Knife}!{/b} The Leatherworking Supply vendors near your trainer and most General Goods vendors sell it. You don't have to equip it, but you can't skin without one in your bags."] = "{b}別忘了買一把 {i:7005:inv_weapon_shortblade_01:Skinning Knife}！{/b}訓練師附近的製皮供應商和大多數雜貨商都有賣。你不需要裝備它，但背包裡沒有剝皮小刀就無法剝皮。",
  ["Skin the {n:3098::Mottled Boars} in the Valley of Trials in Durotar."] = "剝杜洛塔試煉谷的 {n:3098::Mottled Boars}。",
  ["{b}Mob level:{/b} 1-2"] = "{b}怪物等級：{/b}1-2",
  ["The Mottled Boars in the Valley of Trials in Durotar"] = "杜洛塔試煉谷的斑紋野豬",
  ["Skin the {n:299::Young Wolves} and {n:69::Timber Wolves} in Northshire Valley in Elwynn Forest."] = "剝艾爾文森林北郡山谷的 {n:299::Young Wolves} 和 {n:69::Timber Wolves}。",
  ["The wolves in Northshire Valley in Elwynn Forest"] = "艾爾文森林北郡山谷的狼",
  ["Visit your trainer and learn Journeyman Skinning if you haven't yet, it requires Skinning 50. The new Junior Skinning Trainers in the starting areas won't teach you Journeyman Skinning."] = "如果還沒學，請找訓練師學習熟手剝皮，需要剝皮 50。新手區新增的初級剝皮訓練師不會教熟手剝皮。",
  ["To train past 150, visit your trainer again and learn Expert Skinning when you reach 125."] = "要學習 150 以上，請在達到 125 時再去找訓練師學習專家剝皮。",
  ["Kill and skin {n:3256::Sunscale Scytheclaw}, {n:3426::Zhevra Charger}, {n:3245::Ornery Plainstrider}."] = "擊殺並剝皮 {n:3256::Sunscale Scytheclaw}、{n:3426::Zhevra Charger}、{n:3245::Ornery Plainstrider}。",
  ["Go to the small raptor camp just west of Northwatch Hold. Skin the level 16-17 ones until 80, from 80 you can skin the level 18 ones too. Stay here until 150, the last 10 points are green but the respawn is fast."] = "前往北方城堡西邊的小迅猛龍營地。先剝 16-17 級的直到 80，從 80 開始也能剝 18 級的。待在這裡直到 150，最後 10 點是綠色的，但重生很快。",
  ["{b}Mob level:{/b} 16-18"] = "{b}怪物等級：{/b}16-18",
  ["The Sunscale Scytheclaws west of Northwatch Hold in the Barrens"] = "貧瘠之地北方城堡西邊的陽鱗鐮爪龍",
  ["75-125 Loch Modan"] = "75-125 洛克莫丹",
  ["Kill and skin {n:1192::Elder Mountain Boar}, {n:1189::Black Bear Patriarch}."] = "擊殺並剝皮 {n:1192::Elder Mountain Boar}、{n:1189::Black Bear Patriarch}。",
  ["{n:1693::Loch Crocolisk} are also skinnable, make sure to pull them when you get to the shore."] = "{n:1693::Loch Crocolisk} 也可以剝，到湖岸時記得順便拉牠們。",
  ["Stay here until around 125, then head north to the Wetlands, it is on the way to Hillsbrad."] = "在這裡待到大約 125，然後往北前往濕地，就在去希爾斯布萊德的路上。",
  ["{b}Mob level:{/b} 16-17"] = "{b}怪物等級：{/b}16-17",
  ["Skinning spot in Loch Modan"] = "洛克莫丹的剝皮地點",
  ["125-150 Wetlands"] = "125-150 濕地",
  ["Kill and skin {n:1022::Mottled Scytheclaw}, {n:1023::Mottled Razormaw}."] = "擊殺並剝皮 {n:1022::Mottled Scytheclaw}、{n:1023::Mottled Razormaw}。",
  ["There are always a few of them at Whelgar's Excavation Site, so you never run out of mobs to kill."] = "維爾加挖掘場總是有幾隻，所以怪物永遠殺不完。",
  ["{b}Mob level:{/b} 25-27"] = "{b}怪物等級：{/b}25-27",
  ["Whelgar's Excavation Site in the Wetlands"] = "濕地的維爾加挖掘場",
  ["From 150, go to the Foothill Caverns in Hillsbrad Foothills, the yeti cave on the border of Alterac Mountains, or to the Rotting Orchard in Duskwood."] = "從 150 開始，前往希爾斯布萊德丘陵與奧特蘭克山脈交界處的雪人洞穴「丘陵洞穴」，或暮色森林的腐爛果園。",
  ["Duskwood"] = "暮色森林",
  ["Both factions can get there, Horde from Tarren Mill and Alliance from Southshore."] = "兩個陣營都能到達，部落從塔倫米爾，聯盟從南海鎮。",
  ["Kill and skin {n:2248::Cave Yeti}, {n:2249::Ferocious Yeti}."] = "擊殺並剝皮 {n:2248::Cave Yeti}、{n:2249::Ferocious Yeti}。",
  ["The yetis respawn so fast that you can stay inside the cave the whole time."] = "雪人重生快到你可以整段時間都待在洞裡。",
  ["{b}Mob level:{/b} 30-32"] = "{b}怪物等級：{/b}30-32",
  ["The Foothill Caverns in Hillsbrad Foothills"] = "希爾斯布萊德丘陵的丘陵洞穴",
  ["Duskwood is an Alliance zone, but Grom'gol is close, so Horde players can get there too."] = "暮色森林是聯盟區域，但格羅姆高營地很近，所以部落玩家也能到達。",
  ["Kill and skin {n:898::Nightbane Worgen}, {n:533::Nightbane Shadow Weaver}, {n:205::Nightbane Dark Runner}."] = "擊殺並剝皮 {n:898::Nightbane Worgen}、{n:533::Nightbane Shadow Weaver}、{n:205::Nightbane Dark Runner}。",
  ["Start at the area marked with 1, clear the mobs outside and inside Roland's Doom cave, then go to the Rotting Orchard until the mobs respawn."] = "從標示 1 的區域開始，清掉羅蘭之墓洞穴外面和裡面的怪物，然後去腐爛果園等怪物重生。",
  ["{b}Mob level:{/b} 26-29"] = "{b}怪物等級：{/b}26-29",
  ["Roland's Doom and the Rotting Orchard in Duskwood"] = "暮色森林的羅蘭之墓和腐爛果園",
  ["Visit your trainer and learn Artisan Skinning, it requires Skinning 200."] = "找訓練師學習工匠剝皮，需要剝皮 200。",
  ["Mount up and go to the yeti cave at Feral Scar Vale in the south of Feralas. Both factions can get there, Horde from Camp Mojache and Alliance from Feathermoon Stronghold."] = "騎上坐騎前往菲拉斯南部野疤谷的雪人洞穴。兩個陣營都能到達，部落從莫沙徹營地，聯盟從羽月要塞。",
  ["Kill and skin {n:5292::Feral Scar Yeti}, {n:5295::Enraged Feral Scar}, {n:5293::Hulking Feral Scar}."] = "擊殺並剝皮 {n:5292::Feral Scar Yeti}、{n:5295::Enraged Feral Scar}、{n:5293::Hulking Feral Scar}。",
  ["{b}Mob level:{/b} 43-46"] = "{b}怪物等級：{/b}43-46",
  ["The yeti cave at Feral Scar Vale in Feralas"] = "菲拉斯野疤谷的雪人洞穴",
  ["From 280, fly to Marshal's Refuge and skin the dinosaurs in the western part of Un'Goro Crater."] = "從 280 開始，飛到馬紹爾營地，剝安戈洛環形山西部的恐龍。",
  ["Kill and skin {n:9163::Diemetradon}, {n:9166::Pterrordax}, {n:9164::Elder Diemetradon}, {n:9167::Frenzied Pterrordax}."] = "擊殺並剝皮 {n:9163::Diemetradon}、{n:9166::Pterrordax}、{n:9164::Elder Diemetradon}、{n:9167::Frenzied Pterrordax}。",
  ["{b}Mob level:{/b} 50-55"] = "{b}怪物等級：{/b}50-55",
  ["The dinosaur area in the west of Un'Goro Crater"] = "安戈洛環形山西部的恐龍區域",
  ["This WoW Forever Fishing and Cooking leveling guide will show you the fastest way to level Fishing and Cooking together from 1 to 300."] = "這份 WoW Forever 釣魚與烹飪升級指南將告訴你如何以最快的方式同時將釣魚和烹飪從 1 升到 300。",
  ["Leveling Fishing takes a long time, so it's best to level these two together, because every fish you catch is also a Cooking recipe and your Cooking goes up for free while you fish. You will still need a lot of patience because you have to catch a lot of fish to get from start to finish. If you only want one of them, use my Fishing guide or my Cooking guide instead."] = "練釣魚需要很長時間，所以最好兩者一起練，因為你釣到的每條魚也是一道烹飪配方，釣魚時烹飪就免費跟著升了。你仍然需要很多耐心，因為從頭到尾要釣非常多的魚。如果你只想練其中一種，請改用我的釣魚指南或烹飪指南。",
  ["Level Fishing to 75"] = "釣魚練到 75",
  ["If you can choose, {b}level Fishing in Mulgore{/b}, because everything is close together there. {n:0::Harn Longcast} in Bloodhoof Village sells both recipes and the pole, and the Fishing trainer stands at Stonebull Lake. Thunder Bluff, where you fish after 75, is right next to it."] = "如果可以選擇，{b}在莫高雷練釣魚{/b}，因為那裡所有東西都很近。血蹄村的 {n:0::Harn Longcast} 兩種配方和魚竿都有賣，釣魚訓練師就站在石牛湖邊。75 之後要去釣魚的雷霆崖就在旁邊。",
  ["If you haven't learned Fishing yet, learn it from {n:0::Lau'Tiki} on the coast south of Sen'jin Village."] = "如果你還沒學釣魚，請向森金村南邊海岸的 {n:0::Lau'Tiki} 學習。",
  ["Buy {i:6326:inv_scroll_03:Recipe: Slitherskin Mackerel} from {n:0::Zansoa} in Sen'jin Village. Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} there too. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "向森金村的 {n:0::Zansoa} 購買 {i:6326:inv_scroll_03:Recipe: Slitherskin Mackerel}。順便在那裡買一根 {i:6256:inv_fishingpole_02:Fishing Pole} 和一個 {i:6529:inv_misc_orb_03:Shiny Bauble}。（看到 {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} 就買下來留著之後用。）",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish on the coast next to {n:0::Lau'Tiki}, south of Sen'jin Village, until your Fishing skill reaches 75. Almost everything you catch there is {i:6303:inv_misc_fish_24:Raw Slitherskin Mackerel}, about 70 of them."] = "裝備魚竿，裝上 {i:6529:inv_misc_orb_03:Shiny Bauble}，在森金村南邊 {n:0::Lau'Tiki} 旁的海岸釣魚，直到釣魚技能達到 75。你在那裡釣到的幾乎都是 {i:6303:inv_misc_fish_24:Raw Slitherskin Mackerel}，大約 70 條。",
  ["Learn Journeyman Fishing from {n:0::Lau'Tiki}, it requires level 10."] = "向 {n:0::Lau'Tiki} 學習熟手釣魚，需要等級 10。",
  ["The coast south of Sen'jin Village in Durotar, where to fish from 1 to 75"] = "杜洛塔森金村南邊的海岸，1 到 75 的釣魚地點",
  ["If you haven't learned Fishing yet, learn it from {n:0::Uthan Stillwater} at Stonebull Lake."] = "如果你還沒學釣魚，請向石牛湖的 {n:0::Uthan Stillwater} 學習。",
  ["Buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} from {n:0::Harn Longcast} in Bloodhoof Village. Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} there too. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "向血蹄村的 {n:0::Harn Longcast} 購買 {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} 和 {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper}。順便在那裡買一根 {i:6256:inv_fishingpole_02:Fishing Pole} 和一個 {i:6529:inv_misc_orb_03:Shiny Bauble}。（看到 {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} 就買下來留著之後用。）",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in Stonebull Lake until your Fishing skill reaches 75. You will catch about 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}."] = "裝備魚竿，裝上 {i:6529:inv_misc_orb_03:Shiny Bauble}，在石牛湖釣魚，直到釣魚技能達到 75。你會釣到大約 45 條 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} 和 30 條 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}。",
  ["Learn Journeyman Fishing from {n:0::Uthan Stillwater}, it requires level 10."] = "向 {n:0::Uthan Stillwater} 學習熟手釣魚，需要等級 10。",
  ["Stonebull Lake around Bloodhoof Village in Mulgore, where to fish from 1 to 75"] = "莫高雷血蹄村周圍的石牛湖，1 到 75 的釣魚地點",
  ["If you haven't learned Fishing yet, learn it from {n:0::Clyde Kellen} at Brightwater Lake."] = "如果你還沒學釣魚，請向清水湖的 {n:0::Clyde Kellen} 學習。",
  ["Buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} from {n:0::Martine Tramblay} at the Death's Watch Waystation, south-east of Brill. Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} there too. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "向布瑞爾東南方亡者哨站的 {n:0::Martine Tramblay} 購買 {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish}。順便在那裡買一根 {i:6256:inv_fishingpole_02:Fishing Pole} 和一個 {i:6529:inv_misc_orb_03:Shiny Bauble}。（看到 {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} 就買下來留著之後用。）",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in Brightwater Lake until your Fishing skill reaches 75. You will catch about 30 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 20 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}, plus some {i:6299:inv_misc_fish_28:Sickly Looking Fish} and junk."] = "裝備魚竿，裝上 {i:6529:inv_misc_orb_03:Shiny Bauble}，在清水湖釣魚，直到釣魚技能達到 75。你會釣到大約 30 條 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} 和 20 條 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}，還有一些 {i:6299:inv_misc_fish_28:Sickly Looking Fish} 和垃圾。",
  ["Learn Journeyman Fishing from {n:0::Clyde Kellen}, it requires level 10."] = "向 {n:0::Clyde Kellen} 學習熟手釣魚，需要等級 10。",
  ["Brightwater Lake east of Brill in Tirisfal Glades, where to fish from 1 to 75"] = "提里斯法林地布瑞爾東邊的清水湖，1 到 75 的釣魚地點",
  ["If you haven't learned Fishing yet, learn it from {n:0::Fenn Fairweather} in Shen'dar Village or {n:0::Baelann Swiftcurrent} in Valanaar."] = "如果你還沒學釣魚，請向申達爾村的 {n:0::Fenn Fairweather} 或瓦拉納爾的 {n:0::Baelann Swiftcurrent} 學習。",
  ["Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} from {n:0::Belandiel Farflight} in Shen'dar Village or {n:0::Baelann Swiftcurrent} in Valanaar. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "向申達爾村的 {n:0::Belandiel Farflight} 或瓦拉納爾的 {n:0::Baelann Swiftcurrent} 購買一根 {i:6256:inv_fishingpole_02:Fishing Pole} 和一個 {i:6529:inv_misc_orb_03:Shiny Bauble}。（看到 {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} 就買下來留著之後用。）",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in any lake or river on Zephras Isle until your Fishing skill reaches 75, for example next to the Fishing trainers in Shen'dar Village and Valanaar. You will catch about 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}. Keep all the fish you catch."] = "裝備魚竿，裝上 {i:6529:inv_misc_orb_03:Shiny Bauble}，在澤弗拉斯島的任何湖泊或河流釣魚，直到釣魚技能達到 75，例如申達爾村和瓦拉納爾的釣魚訓練師旁邊。你會釣到大約 45 條 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} 和 30 條 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}。釣到的魚全部保留。",
  ["Learn Journeyman Fishing from {n:0::Fenn Fairweather} or {n:0::Baelann Swiftcurrent}, it requires level 10."] = "向 {n:0::Fenn Fairweather} 或 {n:0::Baelann Swiftcurrent} 學習熟手釣魚，需要等級 10。",
  ["When you get to Thunder Bluff, buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} from {n:0::Sewa Mistrunner} and {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} from {n:0::Naal Mistrunner}. They stand next to each other."] = "到了雷霆崖後，向 {n:0::Sewa Mistrunner} 購買 {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish}，向 {n:0::Naal Mistrunner} 購買 {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper}。他們站在彼此旁邊。",
  ["The water at Shen'dar Village and Valanaar on Zephras Isle, where to fish from 1 to 75"] = "澤弗拉斯島申達爾村和瓦拉納爾的水域，1 到 75 的釣魚地點",
  ["If you can choose, {b}level Fishing in Elwynn Forest{/b}, because everything is close together there. {n:0::Tharynn Bouden} in Goldshire sells both recipes and the pole, and the Fishing trainer stands at Crystal Lake. Stormwind City, where you fish after 75, is right next to it."] = "如果可以選擇，{b}在艾爾文森林練釣魚{/b}，因為那裡所有東西都很近。閃金鎮的 {n:0::Tharynn Bouden} 兩種配方和魚竿都有賣，釣魚訓練師就站在水晶湖邊。75 之後要去釣魚的暴風城就在旁邊。",
  ["If you haven't learned Fishing yet, learn it from {n:0::Lee Brown} at Crystal Lake."] = "如果你還沒學釣魚，請向水晶湖的 {n:0::Lee Brown} 學習。",
  ["Buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} from {n:0::Tharynn Bouden} in Goldshire. Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} there too. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "向閃金鎮的 {n:0::Tharynn Bouden} 購買 {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} 和 {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper}。順便在那裡買一根 {i:6256:inv_fishingpole_02:Fishing Pole} 和一個 {i:6529:inv_misc_orb_03:Shiny Bauble}。（看到 {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} 就買下來留著之後用。）",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in Crystal Lake, east of Goldshire, until your Fishing skill reaches 75. You will catch about 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}."] = "裝備魚竿，裝上 {i:6529:inv_misc_orb_03:Shiny Bauble}，在閃金鎮東邊的水晶湖釣魚，直到釣魚技能達到 75。你會釣到大約 45 條 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} 和 30 條 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}。",
  ["Learn Journeyman Fishing from {n:0::Lee Brown}, it requires level 10."] = "向 {n:0::Lee Brown} 學習熟手釣魚，需要等級 10。",
  ["Crystal Lake east of Goldshire in Elwynn Forest, where to fish from 1 to 75"] = "艾爾文森林閃金鎮東邊的水晶湖，1 到 75 的釣魚地點",
  ["If you haven't learned Fishing yet, learn it from {n:0::Paxton Ganter} at Iceflow Lake."] = "如果你還沒學釣魚，請向冰流湖的 {n:0::Paxton Ganter} 學習。",
  ["Buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} from {n:0::Gretta Ganter} at Iceflow Lake. Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} there too. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "向冰流湖的 {n:0::Gretta Ganter} 購買 {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish}。順便在那裡買一根 {i:6256:inv_fishingpole_02:Fishing Pole} 和一個 {i:6529:inv_misc_orb_03:Shiny Bauble}。（看到 {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} 就買下來留著之後用。）",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in Iceflow Lake until your Fishing skill reaches 75. You will catch about 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}."] = "裝備魚竿，裝上 {i:6529:inv_misc_orb_03:Shiny Bauble}，在冰流湖釣魚，直到釣魚技能達到 75。你會釣到大約 45 條 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} 和 30 條 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}。",
  ["Learn Journeyman Fishing from {n:0::Paxton Ganter}, it requires level 10."] = "向 {n:0::Paxton Ganter} 學習熟手釣魚，需要等級 10。",
  ["Iceflow Lake in Dun Morogh, where to fish from 1 to 75"] = "丹莫洛的冰流湖，1 到 75 的釣魚地點",
  ["Learn Fishing from {n:0::Astaia} in Darnassus. There is no Fishing trainer in Dolanaar."] = "向達納蘇斯的 {n:0::Astaia} 學習釣魚。多蘭納爾沒有釣魚訓練師。",
  ["Buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} from {n:0::Nyoma} in Dolanaar."] = "向多蘭納爾的 {n:0::Nyoma} 購買 {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} 和 {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper}。",
  ["Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} from {n:0::Narret Shadowgrove} in Dolanaar. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "向多蘭納爾的 {n:0::Narret Shadowgrove} 購買一根 {i:6256:inv_fishingpole_02:Fishing Pole} 和一個 {i:6529:inv_misc_orb_03:Shiny Bauble}。（看到 {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} 就買下來留著之後用。）",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in Lake Al'Ameth, south of Dolanaar, until your Fishing skill reaches 75. You will catch about 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}."] = "裝備魚竿，裝上 {i:6529:inv_misc_orb_03:Shiny Bauble}，在多蘭納爾南邊的阿拉梅斯湖釣魚，直到釣魚技能達到 75。你會釣到大約 45 條 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} 和 30 條 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}。",
  ["Learn Journeyman Fishing from {n:0::Astaia} in Darnassus, it requires level 10."] = "向達納蘇斯的 {n:0::Astaia} 學習熟手釣魚，需要等級 10。",
  ["Lake Al'Ameth south of Dolanaar in Teldrassil, where to fish from 1 to 75"] = "泰達希爾多蘭納爾南邊的阿拉梅斯湖，1 到 75 的釣魚地點",
  ["When you get to Stormwind City, buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} from {n:0::Tharynn Bouden} in Goldshire, right outside the city."] = "到了暴風城後，向城外不遠處閃金鎮的 {n:0::Tharynn Bouden} 購買 {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} 和 {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper}。",
  ["Fishing (75-130) and Cooking (1-100)"] = "釣魚 (75-130) 與烹飪 (1-100)",
  ["Fishing"] = "釣魚",
  ["Fish in the capital city closest to you until your Fishing skill reaches 130. From 75 no fish gets away in any of them. You should catch about 20 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish}, 60 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} and 30 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}."] = "在離你最近的主城釣魚，直到釣魚技能達到 130。從 75 開始，在任何一座主城都不會脫鉤。你應該會釣到大約 20 條 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish}、60 條 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} 和 30 條 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}。",
  ["{b}Thunder Bluff:{/b} the pond near the Auction House."] = "{b}雷霆崖：{/b}拍賣場附近的池塘。",
  ["{b}Undercity:{/b} the canals. About a third of what you catch here is junk, so you get fewer fish."] = "{b}幽暗城：{/b}運河。你在這裡釣到的東西大約三分之一是垃圾，所以魚會比較少。",
  ["{b}Orgrimmar:{/b} the pond in the Valley of Honor, where the Fishing trainer stands."] = "{b}奧格瑪：{/b}榮譽谷的池塘，釣魚訓練師就站在那裡。",
  ["Recipes to buy"] = "要購買的配方",
  ["Buy {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish} from {n:0::Naal Mistrunner} in Thunder Bluff or {n:0::Ronald Burch} in Undercity, you need it in the next part."] = "向雷霆崖的 {n:0::Naal Mistrunner} 或幽暗城的 {n:0::Ronald Burch} 購買 {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish}，下一部分會用到。",
  ["If you don't have {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} yet, buy it from {n:0::Naal Mistrunner} in Thunder Bluff or {n:0::Lizbeth Cromwell} in Undercity."] = "如果你還沒有 {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper}，請向雷霆崖的 {n:0::Naal Mistrunner} 或幽暗城的 {n:0::Lizbeth Cromwell} 購買。",
  ["Nobody sells them in Orgrimmar, so buy them on the Auction House or in Thunder Bluff."] = "奧格瑪沒有人賣，所以請在拍賣場或雷霆崖購買。",
  ["Cooking"] = "烹飪",
  ["If you haven't learned Cooking yet, learn it from {n:0::Aska Mistrunner} in Thunder Bluff, {n:0::Eunice Burch} in Undercity or {n:0::Zamja} in Orgrimmar. Then learn {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and cook all your {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} into {s:7751:inv_misc_fish_07:Brilliant Smallfish}. If you caught {i:6303:inv_misc_fish_24:Raw Slitherskin Mackerel} in your starting zone, learn {i:6326:inv_scroll_03:Recipe: Slitherskin Mackerel} and cook them into {s:7752:inv_misc_fish_24:Slitherskin Mackerel} instead. This should take your Cooking skill to 50."] = "如果你還沒學烹飪，請向雷霆崖的 {n:0::Aska Mistrunner}、幽暗城的 {n:0::Eunice Burch} 或奧格瑪的 {n:0::Zamja} 學習。然後學會 {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish}，把所有 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} 烹飪成 {s:7751:inv_misc_fish_07:Brilliant Smallfish}。如果你在新手區釣到的是 {i:6303:inv_misc_fish_24:Raw Slitherskin Mackerel}，就改學 {i:6326:inv_scroll_03:Recipe: Slitherskin Mackerel}，把牠們烹飪成 {s:7752:inv_misc_fish_24:Slitherskin Mackerel}。這應該能讓你的烹飪技能達到 50。",
  ["If you are a few points short of 50, catch and cook a few more."] = "如果離 50 還差幾點，就再釣幾條來烹飪。",
  ["Learn Journeyman Cooking from the same trainer. Then learn {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} and cook all your {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} into {s:7753:inv_misc_fish_32:Longjaw Mud Snapper}. Your Cooking skill should go above 100."] = "向同一位訓練師學習熟手烹飪。然後學會 {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper}，把所有 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} 烹飪成 {s:7753:inv_misc_fish_32:Longjaw Mud Snapper}。你的烹飪技能應該會超過 100。",
  ["Don't worry if you don't reach 100 Cooking with Longjaw Mud Snapper, you will catch more Raw Longjaw Mud Snapper later."] = "如果用長顎泥鯛沒有升到烹飪 100 也別擔心，之後你還會釣到更多生長顎泥鯛。",
  ["Fish in the canals of Stormwind City until your skill reaches 130. You should catch about 20 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish}, 60 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}, and 30 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}."] = "在暴風城的運河釣魚，直到技能達到 130。你應該會釣到大約 20 條 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish}、60 條 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} 和 30 條 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}。",
  ["Find {n:0::Catherine Leland} in Stormwind City and buy {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish}. If you don't have {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} yet, buy it from {n:0::Tharynn Bouden} in Goldshire."] = "在暴風城找到 {n:0::Catherine Leland}，購買 {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish}。如果你還沒有 {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper}，請向閃金鎮的 {n:0::Tharynn Bouden} 購買。",
  ["You should also find {n:0::Ben Trias} and buy 20 {i:8932:inv_misc_food_37:Alterac Swiss} from him. You will need these later for the Artisan Cooking quest."] = "你也應該找到 {n:0::Ben Trias}，向他購買 20 個 {i:8932:inv_misc_food_37:Alterac Swiss}。之後的工匠烹飪任務會用到。",
  ["Learn Cooking from {n:0::Stephen Ryback} if you haven't yet. Then learn {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and cook all your {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} into {s:7751:inv_misc_fish_07:Brilliant Smallfish}. This should take your Cooking skill to 50."] = "如果還沒學烹飪，請向 {n:0::Stephen Ryback} 學習。然後學會 {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish}，把所有 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} 烹飪成 {s:7751:inv_misc_fish_07:Brilliant Smallfish}。這應該能讓你的烹飪技能達到 50。",
  ["Learn Journeyman Cooking from {n:0::Stephen Ryback} in Stormwind City. Then learn {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} and cook all your {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} into {s:7753:inv_misc_fish_32:Longjaw Mud Snapper}. Your Cooking skill should go above 100."] = "向暴風城的 {n:0::Stephen Ryback} 學習熟手烹飪。然後學會 {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper}，把所有 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} 烹飪成 {s:7753:inv_misc_fish_32:Longjaw Mud Snapper}。你的烹飪技能應該會超過 100。",
  ["Fishing (130-205) and Cooking (100-175)"] = "釣魚 (130-205) 與烹飪 (100-175)",
  ["Expert Fishing needs {b}level 20{/b} and {b}Fishing 125{/b}, Expert Cooking needs {b}Cooking 125{/b}."] = "專家釣魚需要{b}等級 20{/b}和{b}釣魚 125{/b}，專家烹飪需要{b}烹飪 125{/b}。",
  ["Booty Bay"] = "藏寶海灣",
  ["Go to Ratchet in The Barrens and take the boat to Booty Bay in Stranglethorn Vale."] = "前往貧瘠之地的棘齒城，搭船到荊棘谷的藏寶海灣。",
  ["Find {n:0::Old Man Heming} in Booty Bay, buy {i:16083:inv_misc_book_08:Expert Fishing - The Bass and You} from him and read it."] = "在藏寶海灣找到 {n:0::Old Man Heming}，向他購買 {i:16083:inv_misc_book_08:Expert Fishing - The Bass and You} 並閱讀。",
  ["Find {n:0::Kelsey Yance} and buy these two recipes: {i:17062:inv_scroll_03:Recipe: Mithril Head Trout}, {i:13941:inv_scroll_03:Recipe: Filet of Redgill}."] = "找到 {n:0::Kelsey Yance}，購買這兩個配方：{i:17062:inv_scroll_03:Recipe: Mithril Head Trout}、{i:13941:inv_scroll_03:Recipe: Filet of Redgill}。",
  ["Go back to The Barrens, then fly from Ratchet to Sun Rock Retreat in Stonetalon Mountains and buy 7 {i:6530:inv_misc_monstertail_03:Nightcrawlers} from {n:0::Kulwia}. You need 2 until 150, keep the other 5 for later."] = "回到貧瘠之地，從棘齒城飛到石爪山脈的烈日石居，向 {n:0::Kulwia} 購買 7 個 {i:6530:inv_misc_monstertail_03:Nightcrawlers}。到 150 需要 2 個，其餘 5 個留著之後用。",
  ["Attach a {i:6530:inv_misc_monstertail_03:Nightcrawler} and fish in the open water until your Fishing skill reaches 205. You will catch about 95 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} and 145 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}."] = "裝上 {i:6530:inv_misc_monstertail_03:Nightcrawler}，在開闊水域釣魚，直到釣魚技能達到 205。你會釣到大約 95 條 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} 和 145 條 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}。",
  ["Fly to Shadowprey Village in Desolace."] = "飛到淒涼之地的葬影村。",
  ["Find {n:0::Wulan} and buy the {i:16072:inv_misc_book_08:Expert Cookbook}. He is on the top floor of the eastern-most building in the village."] = "找到 {n:0::Wulan}，購買 {i:16072:inv_misc_book_08:Expert Cookbook}。他在村子最東邊那棟建築的頂樓。",
  ["Buy 20 {i:8932:inv_misc_food_37:Alterac Swiss} from {n:0::Innkeeper Sikewa}. You will need them for the Artisan Cooking quest."] = "向 {n:0::Innkeeper Sikewa} 購買 20 個 {i:8932:inv_misc_food_37:Alterac Swiss}。工匠烹飪任務會用到。",
  ["Leveling Cooking to 175"] = "烹飪練到 175",
  ["Cook your {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} into {s:7753:inv_misc_fish_32:Longjaw Mud Snapper} if your Cooking skill is still below 100."] = "如果你的烹飪技能還低於 100，就把 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} 烹飪成 {s:7753:inv_misc_fish_32:Longjaw Mud Snapper}。",
  ["{b}Read the {i:16072:inv_misc_book_08:Expert Cookbook} as soon as you reach 125{/b}, especially if you go AFK while cooking. Without it you stop getting skill points at 150 and keep cooking for nothing."] = "{b}一到 125 就閱讀 {i:16072:inv_misc_book_08:Expert Cookbook}{/b}，尤其是你掛機烹飪的時候。沒有它的話，到 150 就不會再獲得技能點，只是白白烹飪。",
  ["Learn {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish} and cook all your {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} into {s:7755:inv_misc_fish_30:Bristle Whisker Catfish}. Your Cooking skill will hopefully get close to 175."] = "學會 {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish}，把所有 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} 烹飪成 {s:7755:inv_misc_fish_30:Bristle Whisker Catfish}。你的烹飪技能應該會接近 175。",
  ["Don't worry if you don't reach 175 Cooking with Bristle Whisker Catfish, you will catch more Raw Bristle Whisker Catfish later."] = "如果用刺鬚鯰魚沒有升到烹飪 175 也別擔心，之後你還會釣到更多生刺鬚鯰魚。",
  ["Go to Booty Bay in Stranglethorn Vale."] = "前往荊棘谷的藏寶海灣。",
  ["Go to The Barrens, then fly from Ratchet to Astranaar in Ashenvale. Ride south-east to Mystral Lake and buy the {i:16072:inv_misc_book_08:Expert Cookbook} and 7 {i:6530:inv_misc_monstertail_03:Nightcrawlers} from {n:0::Shandrina}. You need 2 until 150, keep the other 5 for later."] = "前往貧瘠之地，從棘齒城飛到梣谷的阿斯特蘭納。往東南騎到密斯特拉湖，向 {n:0::Shandrina} 購買 {i:16072:inv_misc_book_08:Expert Cookbook} 和 7 個 {i:6530:inv_misc_monstertail_03:Nightcrawlers}。到 150 需要 2 個，其餘 5 個留著之後用。",
  ["Attach a {i:6530:inv_misc_monstertail_03:Nightcrawler} and fish in the open water of Mystral Lake until your Fishing skill reaches 205. You will catch about 95 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} and 145 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}."] = "裝上 {i:6530:inv_misc_monstertail_03:Nightcrawler}，在密斯特拉湖的開闊水域釣魚，直到釣魚技能達到 205。你會釣到大約 95 條 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} 和 145 條 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}。",
  ["Artisan Fishing Quest"] = "工匠釣魚任務",
  ["If you have no {i:6530:inv_misc_monstertail_03:Nightcrawlers} left, buy 5 from {n:0::Kilxx} in The Barrens or {n:0:alliance:Helenia Olden} in Dustwallow Marsh."] = "如果你的 {i:6530:inv_misc_monstertail_03:Nightcrawlers} 用完了，請向貧瘠之地的 {n:0::Kilxx} 或塵泥沼澤的 {n:0:alliance:Helenia Olden} 購買 5 個。",
  ["Go to Dustwallow Marsh and {b}fish anywhere in the swamp until your skill reaches 225{/b}. {b}Don't fish in the ocean.{/b} Keep a {i:6530:inv_misc_monstertail_03:Nightcrawler} on your pole until 225, otherwise a few fish get away."] = "前往塵泥沼澤，{b}在沼澤裡任何地方釣魚直到技能達到 225{/b}。{b}不要在海裡釣。{/b}到 225 之前魚竿上要一直裝著 {i:6530:inv_misc_monstertail_03:Nightcrawler}，否則會有幾條魚脫鉤。",
  ["Find {n:0::Nat Pagle} and accept the quest {q:6607::Nat Pagle, Angler Extreme}. It requires {b}level 35{/b} and {b}Fishing 225{/b}, and you need it to learn Artisan Fishing."] = "找到 {n:0::Nat Pagle}，接受任務 {q:6607::Nat Pagle, Angler Extreme}。它需要{b}等級 35{/b}和{b}釣魚 225{/b}，學習工匠釣魚需要完成它。",
  ["Tidefury Cove, Dustwallow Marsh"] = "塵泥沼澤，怒潮灣",
  ["To complete the quest you have to catch 4 quest fish in four different zones:"] = "要完成任務，你必須在四個不同區域釣到 4 條任務魚：",
  ["{i:16967:inv_misc_monsterhead_02:Feralas Ahi} - Feralas (attach the {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you kept, or {i:6532:inv_misc_gem_variety_02:Bright Baubles} from {n:0::Sheendra Tallgrass} / {n:0::Vivianna} in Feralas, otherwise most of them get away)"] = "{i:16967:inv_misc_monsterhead_02:Feralas Ahi} - 菲拉斯（裝上你保留的 {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor}，或菲拉斯的 {n:0::Sheendra Tallgrass} / {n:0::Vivianna} 出售的 {i:6532:inv_misc_gem_variety_02:Bright Baubles}，否則大部分都會脫鉤）",
  ["{i:16970:inv_misc_fish_21:Misty Reed Mahi Mahi} - Swamp of Sorrows"] = "{i:16970:inv_misc_fish_21:Misty Reed Mahi Mahi} - 悲傷沼澤",
  ["{i:16968:inv_misc_fish_32:Sar'theris Striker} - Desolace"] = "{i:16968:inv_misc_fish_32:Sar'theris Striker} - 淒涼之地",
  ["{i:16969:inv_misc_fish_08:Savage Coast Blue Sailfin} - Stranglethorn Vale"] = "{i:16969:inv_misc_fish_08:Savage Coast Blue Sailfin} - 荊棘谷",
  ["Nat Pagle, Angler Extreme Quest Fishes"] = "納特·帕格：釣魚大師 任務魚",
  ["Where to catch the four Nat Pagle quest fish"] = "四條納特·帕格任務魚的釣魚地點",
  ["Leveling Fishing to 255 and Cooking to 225"] = "釣魚練到 255，烹飪練到 225",
  ["After you completed the quest, {b}keep fishing in the swamp in Dustwallow Marsh until your Fishing skill reaches 255.{/b} {b}Don't fish in the ocean{/b}, because there you catch Raw Rockscale Cod instead of the Raw Mithril Head Trout you cook next."] = "完成任務後，{b}繼續在塵泥沼澤的沼澤裡釣魚，直到釣魚技能達到 255。{/b}{b}不要在海裡釣{/b}，因為在那裡釣到的是生岩鱗鱈魚，而不是接下來要烹飪的生秘銀頭鮭魚。",
  ["Go back to Brackenwall Village (Horde) / Theramore Isle (Alliance) to cook your fish, or put down a campfire if you have one."] = "回到蕨牆村（部落）/ 塞拉摩島（聯盟）烹飪你的魚，或者如果你有營火就放一個。",
  ["Cook your {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} into {s:7755:inv_misc_fish_30:Bristle Whisker Catfish} if your Cooking skill is still below 175."] = "如果你的烹飪技能還低於 175，就把 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} 烹飪成 {s:7755:inv_misc_fish_30:Bristle Whisker Catfish}。",
  ["Learn {i:17062:inv_scroll_03:Recipe: Mithril Head Trout} and cook your {i:8365:inv_misc_fish_02:Raw Mithril Head Trout} into {s:20916:inv_misc_fish_02:Mithril Headed Trout} until 225. Keep the rest, you cook them after the Artisan Cooking quest."] = "學會 {i:17062:inv_scroll_03:Recipe: Mithril Head Trout}，把 {i:8365:inv_misc_fish_02:Raw Mithril Head Trout} 烹飪成 {s:20916:inv_misc_fish_02:Mithril Headed Trout} 直到 225。剩下的留著，完成工匠烹飪任務後再烹飪。",
  ["Artisan Cooking Quest"] = "工匠烹飪任務",
  ["Fly to Gadgetzan in Tanaris and pick up the quest {q:6610::Clamlette Surprise} from {n:0::Dirge Quikcleave}. The reward is Artisan Cooking. The quest requires {b}level 35{/b} and {b}Cooking 225{/b}. You will need these to complete the quest:"] = "飛到塔納利斯的加基森，向 {n:0::Dirge Quikcleave} 接取任務 {q:6610::Clamlette Surprise}。獎勵是工匠烹飪。任務需要{b}等級 35{/b}和{b}烹飪 225{/b}。完成任務需要以下物品：",
  ["12x {i:12207:inv_egg_03:Giant Egg} - dropped by the {n:5428::Rocs}, {n:5429::Fire Rocs} and {n:5430::Searing Rocs} in Tanaris."] = "12x {i:12207:inv_egg_03:Giant Egg} - 由塔納利斯的 {n:5428::Rocs}、{n:5429::Fire Rocs} 和 {n:5430::Searing Rocs} 掉落。",
  ["10x {i:7974:inv_misc_food_51:Zesty Clam Meat} - from Big-mouth Clams, dropped by {n:14123::Steeljaw Snappers} and {n:5431::Surf Gliders} in Tanaris."] = "10x {i:7974:inv_misc_food_51:Zesty Clam Meat} - 來自大嘴蚌，由塔納利斯的 {n:14123::Steeljaw Snappers} 和 {n:5431::Surf Gliders} 掉落。",
  ["20x {i:8932:inv_misc_food_37:Alterac Swiss} - you bought these earlier."] = "20x {i:8932:inv_misc_food_37:Alterac Swiss} - 你之前已經買好了。",
  ["Find {n:0::Gikkix} at Steamwheedle Port in Tanaris and buy {i:13945:inv_scroll_03:Recipe: Nightfin Soup}."] = "在塔納利斯的熱砂港找到 {n:0::Gikkix}，購買 {i:13945:inv_scroll_03:Recipe: Nightfin Soup}。",
  ["Fishing to 300 in Feralas"] = "在菲拉斯把釣魚練到 300",
  ["Fly to Camp Mojache (Horde) / Feathermoon Stronghold (Alliance) in Feralas."] = "飛到菲拉斯的莫沙徹營地（部落）/ 羽月要塞（聯盟）。",
  ["Buy 12 {i:6530:inv_misc_monstertail_03:Nightcrawlers} from {n:0:horde:Sheendra Tallgrass} / {n:0:alliance:Vivianna}."] = "向 {n:0:horde:Sheendra Tallgrass} / {n:0:alliance:Vivianna} 購買 12 個 {i:6530:inv_misc_monstertail_03:Nightcrawlers}。",
  ["Attach a {i:6530:inv_misc_monstertail_03:Nightcrawler} and fish in the marked lake until you reach Fishing 300, use a new one every 10 minutes. Any other lake or river in Feralas works too, {b}except Jademir Lake{/b}."] = "裝上 {i:6530:inv_misc_monstertail_03:Nightcrawler}，在標示的湖泊釣魚直到釣魚 300，每 10 分鐘換一個新的。菲拉斯的其他湖泊或河流也可以，{b}除了加德米爾湖{/b}。",
  ["Where to fish in Feralas from 255 to 300"] = "菲拉斯 255 到 300 的釣魚地點",
  ["Leveling Cooking to 300"] = "烹飪練到 300",
  ["Cook your remaining {i:8365:inv_misc_fish_02:Raw Mithril Head Trout} into {s:20916:inv_misc_fish_02:Mithril Headed Trout} until 250."] = "把剩下的 {i:8365:inv_misc_fish_02:Raw Mithril Head Trout} 烹飪成 {s:20916:inv_misc_fish_02:Mithril Headed Trout} 直到 250。",
  ["Learn {i:13941:inv_scroll_03:Recipe: Filet of Redgill} and cook your {i:13758:inv_misc_fish_06:Raw Redgill} into {s:18241:inv_misc_fish_06:Filet of Redgill} until 285."] = "學會 {i:13941:inv_scroll_03:Recipe: Filet of Redgill}，把 {i:13758:inv_misc_fish_06:Raw Redgill} 烹飪成 {s:18241:inv_misc_fish_06:Filet of Redgill} 直到 285。",
  ["Learn {i:13945:inv_scroll_03:Recipe: Nightfin Soup} and cook all your {i:13759:inv_misc_fish_23:Raw Nightfin Snapper} into {s:18243:inv_drink_17:Nightfin Soup}. You also need a {i:159:inv_drink_07:Refreshing Spring Water} for each soup, buy 20 from the innkeeper."] = "學會 {i:13945:inv_scroll_03:Recipe: Nightfin Soup}，把所有 {i:13759:inv_misc_fish_23:Raw Nightfin Snapper} 烹飪成 {s:18243:inv_drink_17:Nightfin Soup}。每碗湯還需要一個 {i:159:inv_drink_07:Refreshing Spring Water}，向旅店老闆買 20 個。",
  ["{i:13759:inv_misc_fish_23:Raw Nightfin Snapper} don't bite in the afternoon (12:00-18:00 game time). If you fished in the afternoon, you will probably not have enough, so cook the rest of your {i:13758:inv_misc_fish_06:Raw Redgill} into {s:18241:inv_misc_fish_06:Filet of Redgill} too, you might reach 300 with them."] = "{i:13759:inv_misc_fish_23:Raw Nightfin Snapper} 在下午（遊戲時間 12:00-18:00）不會上鉤。如果你是在下午釣魚，數量大概不夠，所以把剩下的 {i:13758:inv_misc_fish_06:Raw Redgill} 也烹飪成 {s:18241:inv_misc_fish_06:Filet of Redgill}，或許就能用它們升到 300。",
  ["If you still don't reach 300, fish a bit more outside the afternoon, or buy a few {i:13759:inv_misc_fish_23:Raw Nightfin Snapper} on the Auction House."] = "如果還是沒到 300，就在下午以外的時段再多釣一點，或在拍賣場買幾條 {i:13759:inv_misc_fish_23:Raw Nightfin Snapper}。",
  ["This WoW Forever Cooking leveling guide will show you the fastest way to level your Cooking skill from 1 to 300 as cheaply as possible. You will also find every trainer location, how the campfire works in Forever and where to train Cooking past 150 and 225."] = "這份 WoW Forever 烹飪升級指南將告訴你如何以最快、最省錢的方式將烹飪技能從 1 升到 300。你也能找到每位訓練師的位置、Forever 中營火的運作方式，以及在 150 和 225 之後要去哪裡繼續學習烹飪。",
  ["Cooking doesn't take up one of your two profession slots, so every character can learn it. Most of the recipes below only need the meat or fish that drops while you level, so the guide lists a few recipes for every skill range and you can make the one you have the ingredients for. If you also want to level Fishing but haven't leveled it yet, use my Fishing and Cooking leveling guide instead:"] = "烹飪不佔用你兩個專業欄位中的任何一個，所以每個角色都能學。下面大多數配方只需要你升級時掉落的肉或魚，所以指南在每個技能區間都列出幾個配方，你有哪種材料就做哪種。如果你也想練釣魚但還沒練，請改用我的釣魚與烹飪升級指南：",
  ["You need level 35 to go past 225, so I split the list in two. Buy this part first."] = "要超過 225 需要等級 35，所以我把清單分成兩部分。先買這一部分。",
  ["The Giant Eggs and the Zesty Clam Meat are for the Artisan Cooking quest."] = "巨蛋和美味蚌肉是工匠烹飪任務要用的。",
  ["Cooking Trainer Locations"] = "烹飪訓練師位置",
  ["Apprentice Cooking has no level requirement, so you can learn it on a fresh character. Every trainer also teaches Journeyman Cooking, so you don't have to find a different trainer at 50."] = "學徒烹飪沒有等級需求，所以新角色也能學。每位訓練師也都教熟手烹飪，所以到 50 時不必另找訓練師。",
  ["Orgrimmar: {n:0:horde:Zamja}"] = "奧格瑪：{n:0:horde:Zamja}",
  ["Undercity: {n:0:horde:Eunice Burch}"] = "幽暗城：{n:0:horde:Eunice Burch}",
  ["Thunder Bluff: {n:0:horde:Aska Mistrunner}"] = "雷霆崖：{n:0:horde:Aska Mistrunner}",
  ["Every starting zone has a Cooking trainer, most of them are inside the inn."] = "每個新手區都有烹飪訓練師，大多數在旅店裡。",
  ["{n:0:horde:Cook Torka} in Razor Hill"] = "剃刀嶺的 {n:0:horde:Cook Torka}",
  ["{n:0:horde:Pyall Silentstride} inside the big tent in Bloodhoof Village"] = "血蹄村大帳篷裡的 {n:0:horde:Pyall Silentstride}",
  ["{n:0:horde:William Pickman} inside the inn in Brill"] = "布瑞爾旅店裡的 {n:0:horde:William Pickman}",
  ["{n:0::Nyalah Brightfire} in Valanaar, {n:0::Zerril Softbreeze} in Shen'dar Village"] = "瓦拉納爾的 {n:0::Nyalah Brightfire}，申達爾村的 {n:0::Zerril Softbreeze}",
  ["Stormwind City: {n:0:alliance:Stephen Ryback}"] = "暴風城：{n:0:alliance:Stephen Ryback}",
  ["Ironforge: {n:0:alliance:Daryl Riknussun}"] = "鐵爐堡：{n:0:alliance:Daryl Riknussun}",
  ["Darnassus: {n:0:alliance:Alegorn}"] = "達納蘇斯：{n:0:alliance:Alegorn}",
  ["{n:0:alliance:Tomas} in the kitchen of the inn in Goldshire"] = "閃金鎮旅店廚房裡的 {n:0:alliance:Tomas}",
  ["{n:0:alliance:Gremlock Pilsnor} in the Thunderbrew Distillery in Kharanos"] = "卡拉諾斯雷酒釀酒廠裡的 {n:0:alliance:Gremlock Pilsnor}",
  ["{n:0:alliance:Zarrin} in Dolanaar"] = "多蘭納爾的 {n:0:alliance:Zarrin}",
  ["You can find every Cooking trainer for Horde and Alliance on my WoW Forever Cooking Trainers page."] = "你可以在我的 WoW Forever 烹飪訓練師頁面找到部落和聯盟的所有烹飪訓練師。",
  ["Campfire"] = "營火",
  ["You need a campfire to cook. There is often one burning next to the Cooking trainer, so look around before you make your own."] = "烹飪需要營火。烹飪訓練師旁邊常常就有一堆正在燃燒的營火，所以自己生火前先看看周圍。",
  ["In Forever the campfire is an item. You learn the {s:1229737:inv_camelot_camping_welcomingcampfire:Basic Campfire Kit} together with Cooking and place the fire from your bags, so you can make a stack of kits in advance. Other players can add their own camp items to your fire, you can read about the whole camping system in my WoW Forever Camping Guide."] = "在 Forever 中營火是一個物品。學會烹飪時你會一併學到 {s:1229737:inv_camelot_camping_welcomingcampfire:Basic Campfire Kit}，並從背包放置營火，所以你可以事先做好一疊工具包。其他玩家可以把他們自己的露營物品加到你的營火上，完整的露營系統說明請看我的 WoW Forever 露營指南。",
  ["To craft the kits you need {i:4470:inv_tradeskillitem_01:Simple Wood} and a {i:4471:inv_stone_11:Flint and Tinder}. The Flint and Tinder is only for crafting the kits, you don't need it to place the fire. Open your faction below to see who sells them near your trainer:"] = "製作工具包需要 {i:4470:inv_tradeskillitem_01:Simple Wood} 和一個 {i:4471:inv_stone_11:Flint and Tinder}。打火石只用於製作工具包，放置營火時不需要它。展開下方你的陣營，看看訓練師附近誰在賣：",
  ["{n:0:horde:Xen'to}, next to the trainer"] = "{n:0:horde:Xen'to}，在訓練師旁邊",
  ["{n:0:horde:Ronald Burch}, next to the trainer"] = "{n:0:horde:Ronald Burch}，在訓練師旁邊",
  ["{n:0:horde:Naal Mistrunner}, next to the trainer"] = "{n:0:horde:Naal Mistrunner}，在訓練師旁邊",
  ["{n:0:horde:Jark} in the Razor Hill barracks"] = "剃刀嶺兵營裡的 {n:0:horde:Jark}",
  ["{n:0:horde:Moorat Longstride} in Bloodhoof Village"] = "血蹄村的 {n:0:horde:Moorat Longstride}",
  ["{n:0:horde:Mrs. Winters} in Brill"] = "布瑞爾的 {n:0:horde:Mrs. Winters}",
  ["{n:0::Antelariaa Cloudgaze} in Valanaar {n:0::Zerril Softbreeze}, the Cooking trainer in Shen'dar Village"] = "瓦拉納爾的 {n:0::Antelariaa Cloudgaze} 申達爾村的烹飪訓練師 {n:0::Zerril Softbreeze}",
  ["{n:0:alliance:Erika Tate}, next to the trainer"] = "{n:0:alliance:Erika Tate}，在訓練師旁邊",
  ["{n:0:alliance:Emrul Riknussun}, next to the trainer"] = "{n:0:alliance:Emrul Riknussun}，在訓練師旁邊",
  ["{n:0:alliance:Fyldan}, next to the trainer"] = "{n:0:alliance:Fyldan}，在訓練師旁邊",
  ["{n:0:alliance:Brog Hamfist} in Goldshire"] = "閃金鎮的 {n:0:alliance:Brog Hamfist}",
  ["{n:0:alliance:Kreg Bilmn} in the Thunderbrew Distillery"] = "雷酒釀酒廠裡的 {n:0:alliance:Kreg Bilmn}",
  ["{n:0:alliance:Nyoma} in Dolanaar"] = "多蘭納爾的 {n:0:alliance:Nyoma}",
  ["Apprentice Cooking (1-50)"] = "學徒烹飪 (1-50)",
  ["{b}These are sold by Cooking Supply vendors near your trainer, don't buy them from the Auction House:{/b}"] = "{b}這些由訓練師附近的烹飪供應商出售，不要在拍賣場購買：{/b}",
  ["Make around 55 from one of these recipes. The two fish are usually the cheapest."] = "從以下其中一個配方做大約 55 個。兩種魚通常最便宜。",
  ["Food"] = "食物",
  ["Ingredients"] = "材料",
  ["Recipe Source"] = "配方來源",
  ["Mulgore: {n:0:horde:Harn Longcast} Thunder Bluff: {n:0:horde:Sewa Mistrunner} Tirisfal Glades: {n:0:horde:Martine Tramblay} Undercity: {n:0:horde:Lizbeth Cromwell} Dun Morogh: {n:0:alliance:Gretta Ganter} Elwynn Forest: {n:0:alliance:Tharynn Bouden} Loch Modan: {n:0:alliance:Khara Deepwater} Stormwind City: {n:0:alliance:Catherine Leland} Teldrassil: {n:0:alliance:Nyoma}"] = "莫高雷：{n:0:horde:Harn Longcast} 雷霆崖：{n:0:horde:Sewa Mistrunner} 提里斯法林地：{n:0:horde:Martine Tramblay} 幽暗城：{n:0:horde:Lizbeth Cromwell} 丹莫洛：{n:0:alliance:Gretta Ganter} 艾爾文森林：{n:0:alliance:Tharynn Bouden} 洛克莫丹：{n:0:alliance:Khara Deepwater} 暴風城：{n:0:alliance:Catherine Leland} 泰達希爾：{n:0:alliance:Nyoma}",
  ["Durotar: {n:0:horde:Zansoa} Tirisfal Glades: {n:0:horde:Martine Tramblay} Ironforge: {n:0:alliance:Tansy Puddlefizz} Teldrassil: {n:0:alliance:Nessa Shadowsong} Westfall: {n:0:alliance:Kriggon Talsone}"] = "杜洛塔：{n:0:horde:Zansoa} 提里斯法林地：{n:0:horde:Martine Tramblay} 鐵爐堡：{n:0:alliance:Tansy Puddlefizz} 泰達希爾：{n:0:alliance:Nessa Shadowsong} 西部荒野：{n:0:alliance:Kriggon Talsone}",
  ["Trainer"] = "訓練師",
  ["(Horde only) Make {s:15935:inv_misc_food_46:Crispy Bat Wing} if you have some {i:12223:inv_misc_pelt_bear_ruin_05:Meaty Bat Wing}. The recipe is sold by {n:0:horde:Abigail Shiel} in Tirisfal Glades."] = "（僅限部落）如果你有一些 {i:12223:inv_misc_pelt_bear_ruin_05:Meaty Bat Wing}，就做 {s:15935:inv_misc_food_46:Crispy Bat Wing}。配方由提里斯法林地的 {n:0:horde:Abigail Shiel} 出售。",
  ["(Horde only) Make {s:6413:inv_misc_food_10:Scorpid Surprise} if you have some {i:5466:spell_nature_nullifypoison:Scorpid Stinger}. The recipe is sold by {n:0:horde:Grimtak} in Durotar."] = "（僅限部落）如果你有一些 {i:5466:spell_nature_nullifypoison:Scorpid Stinger}，就做 {s:6413:inv_misc_food_10:Scorpid Surprise}。配方由杜洛塔的 {n:0:horde:Grimtak} 出售。",
  ["(Alliance only) Make {s:6412:inv_misc_food_68:Kaldorei Spider Kabob} if you have some {i:5465:inv_misc_monsterspidercarapace_01:Small Spider Leg}. The recipe is a reward from {q:4161::Recipe of the Kaldorei}. You can get the quest from {n:0:alliance:Zarrin} in Teldrassil."] = "（僅限聯盟）如果你有一些 {i:5465:inv_misc_monsterspidercarapace_01:Small Spider Leg}，就做 {s:6412:inv_misc_food_68:Kaldorei Spider Kabob}。配方是 {q:4161::Recipe of the Kaldorei} 的獎勵。你可以向泰達希爾的 {n:0:alliance:Zarrin} 接取這個任務。",
  ["Journeyman Cooking (50-150)"] = "熟手烹飪 (50-150)",
  ["{b}Visit your trainer again and learn Journeyman Cooking{/b}, it requires Cooking 50."] = "{b}再去找訓練師學習熟手烹飪{/b}，需要烹飪 50。",
  ["{b}Make sure to learn Journeyman Cooking before you start the next part{/b}, especially if you go AFK while cooking. Without it you stop getting skill points at 75 and keep cooking for nothing."] = "{b}開始下一部分之前，請務必先學會熟手烹飪{/b}，尤其是你掛機烹飪的時候。沒有它的話，到 75 就不會再獲得技能點，只是白白烹飪。",
  ["Make around 55 from any of the recipes below. The two fish are usually the cheapest. {s:8607:inv_misc_food_13:Smoked Bear Meat} turns yellow sooner than the rest, so make more of it, or cook it first if you have more than one type of meat."] = "從下列任一配方做大約 55 個。兩種魚通常最便宜。{s:8607:inv_misc_food_13:Smoked Bear Meat} 比其他的更早變黃，所以要多做一些，或者如果你有不只一種肉，就先烹飪它。",
  ["Mulgore: {n:0:horde:Harn Longcast} Silverpine Forest: {n:0:horde:Killian Sanatha} Thunder Bluff: {n:0:horde:Naal Mistrunner} Undercity: {n:0:horde:Lizbeth Cromwell} Elwynn Forest: {n:0:alliance:Tharynn Bouden} Ironforge: {n:0:alliance:Tansy Puddlefizz} Loch Modan: {n:0:alliance:Khara Deepwater} Teldrassil: {n:0:alliance:Nyoma}"] = "莫高雷：{n:0:horde:Harn Longcast} 銀松森林：{n:0:horde:Killian Sanatha} 雷霆崖：{n:0:horde:Naal Mistrunner} 幽暗城：{n:0:horde:Lizbeth Cromwell} 艾爾文森林：{n:0:alliance:Tharynn Bouden} 鐵爐堡：{n:0:alliance:Tansy Puddlefizz} 洛克莫丹：{n:0:alliance:Khara Deepwater} 泰達希爾：{n:0:alliance:Nyoma}",
  ["Durotar: {n:0:horde:Zansoa} Orgrimmar: {n:0:horde:Shankys} Silverpine Forest: {n:0:horde:Killian Sanatha} Undercity: {n:0:horde:Ronald Burch} Darkshore: {n:0:alliance:Heldan Galesong} Stormwind City: {n:0:alliance:Catherine Leland} Teldrassil: {n:0:alliance:Nessa Shadowsong} Westfall: {n:0:alliance:Kriggon Talsone} Wetlands: {n:0:alliance:Stuart Fleming} The Barrens: {n:0::Kilxx}"] = "杜洛塔：{n:0:horde:Zansoa} 奧格瑪：{n:0:horde:Shankys} 銀松森林：{n:0:horde:Killian Sanatha} 幽暗城：{n:0:horde:Ronald Burch} 黑海岸：{n:0:alliance:Heldan Galesong} 暴風城：{n:0:alliance:Catherine Leland} 泰達希爾：{n:0:alliance:Nessa Shadowsong} 西部荒野：{n:0:alliance:Kriggon Talsone} 濕地：{n:0:alliance:Stuart Fleming} 貧瘠之地：{n:0::Kilxx}",
  ["Silverpine Forest: {n:0:horde:Andrew Hilbert} Loch Modan: {n:0:alliance:Drac Roughcut}"] = "銀松森林：{n:0:horde:Andrew Hilbert} 洛克莫丹：{n:0:alliance:Drac Roughcut}",
  ["55x {i:5469:inv_misc_food_16:Strider Meat} 55x {i:4536:inv_misc_food_19:Shiny Red Apple} (Vendor)"] = "55x {i:5469:inv_misc_food_16:Strider Meat} 55x {i:4536:inv_misc_food_19:Shiny Red Apple}（商人）",
  ["The Barrens: {n:0:horde:Tari'qa} (Horde only) Reward from {q:2178::Easy Strider Living} (Alliance only)"] = "貧瘠之地：{n:0:horde:Tari'qa}（僅限部落） {q:2178::Easy Strider Living} 的獎勵（僅限聯盟）",
  ["Make around 30-35 from one of these two."] = "從這兩種中選一種做大約 30-35 個。",
  ["30x {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} (buy around 55, you will need 25 more at 130-150)"] = "30x {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}（買大約 55 條，130-150 還需要 25 條）",
  ["Hillsbrad Foothills: {n:0:horde:Derak Nightfall} Thunder Bluff: {n:0:horde:Naal Mistrunner} Thunder Bluff: {n:0:horde:Sewa Mistrunner} Undercity: {n:0:horde:Ronald Burch} Hillsbrad Foothills: {n:0:alliance:Lindea Rabonne} Stormwind City: {n:0:alliance:Catherine Leland} The Barrens: {n:0::Kilxx}"] = "希爾斯布萊德丘陵：{n:0:horde:Derak Nightfall} 雷霆崖：{n:0:horde:Naal Mistrunner} 雷霆崖：{n:0:horde:Sewa Mistrunner} 幽暗城：{n:0:horde:Ronald Burch} 希爾斯布萊德丘陵：{n:0:alliance:Lindea Rabonne} 暴風城：{n:0:alliance:Catherine Leland} 貧瘠之地：{n:0::Kilxx}",
  ["Stormwind City: {n:0:alliance:Kendor Kabonka} (Alliance only)"] = "暴風城：{n:0:alliance:Kendor Kabonka}（僅限聯盟）",
  ["Make around 20-25 from any of the recipes below."] = "從下列任一配方做大約 20-25 個。",
  ["See above"] = "見上方",
  ["Stormwind City: {n:0:alliance:Kendor Kabonka} (Alliance) Arathi Highlands: {n:0:horde:Keena} (Horde)"] = "暴風城：{n:0:alliance:Kendor Kabonka}（聯盟） 阿拉希高地：{n:0:horde:Keena}（部落）",
  ["The Barrens: {n:0:horde:Zargh} (Horde only)"] = "貧瘠之地：{n:0:horde:Zargh}（僅限部落）",
  ["Expert Cooking (150-225)"] = "專家烹飪 (150-225)",
  ["To learn Expert Cooking you need to reach Cooking 125, then buy the {i:16072:inv_misc_book_08:Expert Cookbook} from {n:0:horde:Wulan} (Horde) in Desolace at Shadowprey Village or from {n:0:alliance:Shandrina} (Alliance) in Ashenvale at Mystral Lake."] = "要學習專家烹飪，你需要達到烹飪 125，然後向淒涼之地葬影村的 {n:0:horde:Wulan}（部落）或梣谷密斯特拉湖的 {n:0:alliance:Shandrina}（聯盟）購買 {i:16072:inv_misc_book_08:Expert Cookbook}。",
  ["Make around 25-30 from one of these three."] = "從這三種中選一種做大約 25-30 個。",
  ["You can also keep making {s:7755:inv_misc_fish_30:Bristle Whisker Catfish}, but it's green from 160, so you need around 90 of them for these 25 points."] = "你也可以繼續做 {s:7755:inv_misc_fish_30:Bristle Whisker Catfish}，但它從 160 開始是綠色的，所以這 25 點大約需要 90 個。",
  ["Make around 55 from one of these. The Roast Raptor is usually the cheapest."] = "從其中一種做大約 55 個。烤迅猛龍肉通常最便宜。",
  ["Arathi Highlands: {n:0:alliance:Hammon Karwn} Arathi Highlands: {n:0:horde:Keena} Dustwallow Marsh: {n:0:horde:Ogg'marr}"] = "阿拉希高地：{n:0:alliance:Hammon Karwn} 阿拉希高地：{n:0:horde:Keena} 塵泥沼澤：{n:0:horde:Ogg'marr}",
  ["Ashenvale: {n:0:horde:Wik'Tar} Orgrimmar: {n:0:horde:Shankys} Stranglethorn Vale: {n:0::Kelsey Yance} Undercity: {n:0:horde:Lizbeth Cromwell} Ironforge: {n:0:alliance:Tansy Puddlefizz} Wetlands: {n:0:alliance:Stuart Fleming} Desolace: {n:0:horde:Wulan} Darkshore: {n:0:alliance:Heldan Galesong} Hillsbrad Foothills: {n:0:alliance:Lindea Rabonne}"] = "梣谷：{n:0:horde:Wik'Tar} 奧格瑪：{n:0:horde:Shankys} 荊棘谷：{n:0::Kelsey Yance} 幽暗城：{n:0:horde:Lizbeth Cromwell} 鐵爐堡：{n:0:alliance:Tansy Puddlefizz} 濕地：{n:0:alliance:Stuart Fleming} 淒涼之地：{n:0:horde:Wulan} 黑海岸：{n:0:alliance:Heldan Galesong} 希爾斯布萊德丘陵：{n:0:alliance:Lindea Rabonne}",
  ["Reward from a quest in Hillsbrad Foothills NPC: {n:0:horde:Christoph Jeffcoat}, quest: {q:7321::Soothing Turtle Bisque} NPC: {n:0:alliance:Chef Jessen}, quest: {q:555::Soothing Turtle Bisque}"] = "希爾斯布萊德丘陵任務獎勵 NPC：{n:0:horde:Christoph Jeffcoat}，任務：{q:7321::Soothing Turtle Bisque} NPC：{n:0:alliance:Chef Jessen}，任務：{q:555::Soothing Turtle Bisque}",
  ["Artisan Cooking (225-300)"] = "工匠烹飪 (225-300)",
  ["Artisan Cooking is the reward of the {q:6610::Clamlette Surprise} quest. You need {b}level 35{/b} and {b}Cooking 225{/b} for it."] = "工匠烹飪是 {q:6610::Clamlette Surprise} 任務的獎勵。你需要{b}等級 35{/b}和{b}烹飪 225{/b}。",
  ["Pick up the quest that sends you to Gadgetzan: Horde players take {q:6611::To Gadgetzan You Go!} from {n:0:horde:Zamja} in Orgrimmar, Alliance players take {q:6612::I Know A Guy...} from {n:0:alliance:Daryl Riknussun} in Ironforge."] = "接取把你送往加基森的任務：部落玩家向奧格瑪的 {n:0:horde:Zamja} 接取 {q:6611::To Gadgetzan You Go!}，聯盟玩家向鐵爐堡的 {n:0:alliance:Daryl Riknussun} 接取 {q:6612::I Know A Guy...}。",
  ["Collect 12x {i:12207:inv_egg_03:Giant Egg}, 10x {i:7974:inv_misc_food_51:Zesty Clam Meat} and 20x {i:8932:inv_misc_food_37:Alterac Swiss}. {b}Don't go to Gadgetzan before you have all of them{/b}, otherwise you make the trip twice."] = "收集 12x {i:12207:inv_egg_03:Giant Egg}、10x {i:7974:inv_misc_food_51:Zesty Clam Meat} 和 20x {i:8932:inv_misc_food_37:Alterac Swiss}。{b}在全部收集齊之前不要去加基森{/b}，否則你得跑兩趟。",
  ["Find {n:0::Dirge Quikcleave} in Gadgetzan, take Clamlette Surprise from him and hand in the three items. He teaches you Artisan Cooking on the spot. While you are in Tanaris, go to Steamwheedle Port and {b}buy {i:13939:inv_scroll_03:Recipe: Spotted Yellowtail} from {n:0::Gikkix}{/b}, you need it in the next step."] = "在加基森找到 {n:0::Dirge Quikcleave}，向他接取美味蚌肉蛋捲任務，並交上三樣物品。他會當場教你工匠烹飪。人在塔納利斯時，順便去熱砂港，{b}向 {n:0::Gikkix} 購買 {i:13939:inv_scroll_03:Recipe: Spotted Yellowtail}{/b}，下一步會用到。",
  ["Make around 140 from one of these two, buy the fish that is cheaper."] = "從這兩種中選一種做大約 140 個，買比較便宜的那種魚。",
  ["Tanaris: {n:0::Gikkix}"] = "塔納利斯：{n:0::Gikkix}",
  ["Stranglethorn Vale: {n:0::Kelsey Yance}"] = "荊棘谷：{n:0::Kelsey Yance}",
  ["This WoW Forever First Aid leveling guide will show you the fastest way to level your First Aid skill from 1 to 300. You will also find every trainer location and where to train First Aid past 150 and 225."] = "這份 WoW Forever 急救升級指南將告訴你如何以最快的方式將急救技能從 1 升到 300。你也能找到每位訓練師的位置，以及在 150 和 225 之後要去哪裡繼續學習急救。",
  ["First Aid does not take up one of your two profession slots, so every character can learn it. Bandages heal you between fights, and in Forever First Aid also makes the healing potions that used to be Alchemy recipes, so it's worth leveling on every character. Below you will find the shopping list, the First Aid trainers by starting zone and capital city, and the cheapest recipes for every skill range."] = "急救不佔用你兩個專業欄位中的任何一個，所以每個角色都能學。繃帶能在戰鬥之間治療你，而在 Forever 中急救還能製作以前屬於鍊金術配方的治療藥水，所以每個角色都值得練。下方有購物清單、依新手區與主城分類的急救訓練師，以及每個技能區間最便宜的配方。",
  ["First Aid Trainer Locations"] = "急救訓練師位置",
  ["Apprentice First Aid has no level requirement, so you can learn it on a fresh character. Every trainer also teaches Journeyman First Aid, so you don't have to find a different trainer at 50."] = "學徒急救沒有等級需求，所以新角色也能學。每位訓練師也都教熟手急救，所以到 50 時不必另找訓練師。",
  ["Orgrimmar: {n:0:horde:Arnok}"] = "奧格瑪：{n:0:horde:Arnok}",
  ["Undercity: {n:0:horde:Mary Edras}"] = "幽暗城：{n:0:horde:Mary Edras}",
  ["Thunder Bluff: {n:0:horde:Pand Stonebinder}"] = "雷霆崖：{n:0:horde:Pand Stonebinder}",
  ["Every starting zone has a First Aid trainer, most of them are inside the inn."] = "每個新手區都有急救訓練師，大多數在旅店裡。",
  ["{n:0:horde:Rawrk} in the barracks in Razor Hill"] = "剃刀嶺兵營裡的 {n:0:horde:Rawrk}",
  ["{n:0:horde:Vira Younghoof} inside the inn in Bloodhoof Village"] = "血蹄村旅店裡的 {n:0:horde:Vira Younghoof}",
  ["{n:0:horde:Nurse Neela} inside the inn in Brill"] = "布瑞爾旅店裡的 {n:0:horde:Nurse Neela}",
  ["{n:0::Melasa Fairmend} in Valanaar, {n:0::Naleeia Tattermend} in Shen'dar Village"] = "瓦拉納爾的 {n:0::Melasa Fairmend}，申達爾村的 {n:0::Naleeia Tattermend}",
  ["Stormwind City: {n:0:alliance:Shaina Fuller}"] = "暴風城：{n:0:alliance:Shaina Fuller}",
  ["Ironforge: {n:0:alliance:Nissa Firestone}"] = "鐵爐堡：{n:0:alliance:Nissa Firestone}",
  ["Darnassus: {n:0:alliance:Dannelor}"] = "達納蘇斯：{n:0:alliance:Dannelor}",
  ["{n:0:alliance:Michelle Belle} upstairs in the inn in Goldshire"] = "閃金鎮旅店樓上的 {n:0:alliance:Michelle Belle}",
  ["{n:0:alliance:Thamner Pol} in the Thunderbrew Distillery in Kharanos"] = "卡拉諾斯雷酒釀酒廠裡的 {n:0:alliance:Thamner Pol}",
  ["{n:0:alliance:Byancie} in Dolanaar, in the building north of the inn"] = "多蘭納爾旅店北邊建築裡的 {n:0:alliance:Byancie}",
  ["You can find every First Aid trainer for Horde and Alliance on my WoW Forever First Aid Trainers page."] = "你可以在我的 WoW Forever 急救訓練師頁面找到部落和聯盟的所有急救訓練師。",
  ["Apprentice First Aid (1-75)"] = "學徒急救 (1-75)",
  ["If you have Linen Cloth or bought some, pick the {b}Bandages{/b} tab. If you bought herbs, pick the {b}Healing Potions{/b} tab."] = "如果你有或買了亞麻布，請選{b}繃帶{/b}分頁。如果你買的是草藥，請選{b}治療藥水{/b}分頁。",
  ["Bandages"] = "繃帶",
  ["Healing Potions"] = "治療藥水",
  ["86x {s:1244431:inv_potion_49:Minor Healing Potion} - 86 Peacebloom, 86 Mild Spices, 86 Empty Vial"] = "86x {s:1244431:inv_potion_49:Minor Healing Potion} - 86 寧神花、86 溫和香料、86 空瓶",
  ["{i:2678:inv_misc_food_wheat_02:Mild Spices} are sold by Cooking supply vendors, {i:3371:inv_potion_84:Empty Vial} by Alchemy supply vendors. Open your faction below to see who sells them near your trainer:"] = "{i:2678:inv_misc_food_wheat_02:Mild Spices} 由烹飪供應商出售，{i:3371:inv_potion_84:Empty Vial} 由鍊金術供應商出售。展開下方你的陣營，看看訓練師附近誰在賣：",
  ["spices: {n:0:horde:Xen'to} vials: {n:0:horde:Kor'geld}"] = "香料：{n:0:horde:Xen'to} 空瓶：{n:0:horde:Kor'geld}",
  ["{n:0:horde:Felicia Doan} in the Trade Quarter"] = "商業區的 {n:0:horde:Felicia Doan}",
  ["spices: {n:0:horde:Naal Mistrunner} vials: {n:0:horde:Mani Winterhoof}"] = "香料：{n:0:horde:Naal Mistrunner} 空瓶：{n:0:horde:Mani Winterhoof}",
  ["{n:0:horde:Wunna Darkmane} in Bloodhoof Village"] = "血蹄村的 {n:0:horde:Wunna Darkmane}",
  ["{n:0:horde:Abigail Shiel} in Brill"] = "布瑞爾的 {n:0:horde:Abigail Shiel}",
  ["{n:0::Iallion Featherfall} in Valanaar {n:0::Belandiel Farflight} in Shen'dar Village"] = "瓦拉納爾的 {n:0::Iallion Featherfall} 申達爾村的 {n:0::Belandiel Farflight}",
  ["{n:0:alliance:Edna Mullby} in the Trade District"] = "貿易區的 {n:0:alliance:Edna Mullby}",
  ["spices: {n:0:alliance:Emrul Riknussun} vials: {n:0:alliance:Gwina Stonebranch}, right next to the trainer"] = "香料：{n:0:alliance:Emrul Riknussun} 空瓶：{n:0:alliance:Gwina Stonebranch}，就在訓練師旁邊",
  ["{n:0:alliance:Golorn Frostbeard} in Kharanos"] = "卡拉諾斯的 {n:0:alliance:Golorn Frostbeard}",
  ["{n:0:alliance:Narret Shadowgrove} in Dolanaar"] = "多蘭納爾的 {n:0:alliance:Narret Shadowgrove}",
  ["50x {s:3275:inv_misc_bandage_15:Linen Bandage} - 50 Linen Cloth"] = "50x {s:3275:inv_misc_bandage_15:Linen Bandage} - 50 亞麻布",
  ["49x {s:3276:inv_misc_bandage_18:Heavy Linen Bandage} - 98 Linen Cloth"] = "49x {s:3276:inv_misc_bandage_18:Heavy Linen Bandage} - 98 亞麻布",
  ["Journeyman First Aid (75-150)"] = "熟手急救 (75-150)",
  ["To train past 75, visit your trainer and learn Journeyman First Aid, it requires First Aid 50."] = "要學習 75 以上，請找訓練師學習熟手急救，需要急救 50。",
  ["16x {s:3276:inv_misc_bandage_18:Heavy Linen Bandage} - 32 Linen Cloth"] = "16x {s:3276:inv_misc_bandage_18:Heavy Linen Bandage} - 32 亞麻布",
  ["12x {s:3277:inv_misc_bandage_14:Wool Bandage} - 12 Wool Cloth"] = "12x {s:3277:inv_misc_bandage_14:Wool Bandage} - 12 毛料",
  ["If you have Wool Cloth, pick the {b}Bandages{/b} tab. If you have to buy everything, the {b}Healing Potions{/b} tab is cheaper."] = "如果你有毛料，請選{b}繃帶{/b}分頁。如果全部都要用買的，{b}治療藥水{/b}分頁比較便宜。",
  ["43x {s:3277:inv_misc_bandage_14:Wool Bandage} - 43 Wool Cloth"] = "43x {s:3277:inv_misc_bandage_14:Wool Bandage} - 43 毛料",
  ["54x {s:3278:inv_misc_bandage_17:Heavy Wool Bandage} - 108 Wool Cloth"] = "54x {s:3278:inv_misc_bandage_17:Heavy Wool Bandage} - 108 毛料",
  ["For this tab you need 54 {i:2678:inv_misc_food_wheat_02:Mild Spices}, 31 {i:2692:inv_misc_food_legion_dalapenopepper:Hot Spices}, 31 {i:3372:inv_potion_85:Leaded Vial} and 54 {i:2723:inv_drink_10:Bottle of Dalaran Noir}. Spices are sold by Cooking supply vendors, vials by Alchemy supply vendors and the bottles by barkeeps. The starting zone vendors don't sell Hot Spices or Leaded Vials, so buy them in a capital city. Open your faction below to see who sells them:"] = "這個分頁你需要 54 個 {i:2678:inv_misc_food_wheat_02:Mild Spices}、31 個 {i:2692:inv_misc_food_legion_dalapenopepper:Hot Spices}、31 個 {i:3372:inv_potion_85:Leaded Vial} 和 54 瓶 {i:2723:inv_drink_10:Bottle of Dalaran Noir}。香料由烹飪供應商出售，瓶子由鍊金術供應商出售，酒則由酒保出售。新手區的商人不賣辣味香料和鉛瓶，所以請在主城購買。展開下方你的陣營，看看誰在賣：",
  ["{i:2678:inv_misc_food_wheat_02:Mild Spices} and {i:2692:inv_misc_food_legion_dalapenopepper:Hot Spices}"] = "{i:2678:inv_misc_food_wheat_02:Mild Spices} 和 {i:2692:inv_misc_food_legion_dalapenopepper:Hot Spices}",
  ["Orgrimmar: {n:0:horde:Xen'to} Undercity: {n:0:horde:Felicia Doan} Thunder Bluff: {n:0:horde:Naal Mistrunner}"] = "奧格瑪：{n:0:horde:Xen'to} 幽暗城：{n:0:horde:Felicia Doan} 雷霆崖：{n:0:horde:Naal Mistrunner}",
  ["Orgrimmar: {n:0:horde:Kor'geld} Undercity: {n:0:horde:Felicia Doan} Thunder Bluff: {n:0:horde:Mani Winterhoof}"] = "奧格瑪：{n:0:horde:Kor'geld} 幽暗城：{n:0:horde:Felicia Doan} 雷霆崖：{n:0:horde:Mani Winterhoof}",
  ["Orgrimmar: {n:5611::Barkeep Morag} Booty Bay: {n:2832::Nixxrax Fillamug}"] = "奧格瑪：{n:5611::Barkeep Morag} 藏寶海灣：{n:2832::Nixxrax Fillamug}",
  ["Stormwind City: {n:0:alliance:Edna Mullby} Ironforge: {n:0:alliance:Emrul Riknussun} Darnassus: {n:0:alliance:Mythrin'dir}"] = "暴風城：{n:0:alliance:Edna Mullby} 鐵爐堡：{n:0:alliance:Emrul Riknussun} 達納蘇斯：{n:0:alliance:Mythrin'dir}",
  ["Stormwind City: {n:0:alliance:Edna Mullby} Ironforge: {n:0:alliance:Gwina Stonebranch} Darnassus: {n:0:alliance:Mythrin'dir}"] = "暴風城：{n:0:alliance:Edna Mullby} 鐵爐堡：{n:0:alliance:Gwina Stonebranch} 達納蘇斯：{n:0:alliance:Mythrin'dir}",
  ["Stormwind City: {n:277::Roberto Pupellyverbos} and {n:1328::Elly Langston} Ironforge: {n:5570::Bruuk Barleybeard} Booty Bay: {n:2832::Nixxrax Fillamug}"] = "暴風城：{n:277::Roberto Pupellyverbos} 和 {n:1328::Elly Langston} 鐵爐堡：{n:5570::Bruuk Barleybeard} 藏寶海灣：{n:2832::Nixxrax Fillamug}",
  ["54x {s:1259342:inv_10_alchemy2_quenchingfluid_color2:Simple Poultice} - 54 Spider Ichor, 54 Mild Spices, 54 Bottle of Dalaran Noir"] = "54x {s:1259342:inv_10_alchemy2_quenchingfluid_color2:Simple Poultice} - 54 蜘蛛之液、54 溫和香料、54 達拉然紅酒",
  ["31x {s:1244433:inv_potion_51:Healing Potion} - 31 Bruiseweed, 31 Hot Spices, 31 Leaded Vial"] = "31x {s:1244433:inv_potion_51:Healing Potion} - 31 跌打草、31 辣味香料、31 鉛瓶",
  ["Expert First Aid (150-225)"] = "專家急救 (150-225)",
  ["{b}Learn {s:7928:inv_misc_bandage_01:Silk Bandage} from your trainer before you leave{/b}, it's the last recipe the trainers teach."] = "{b}離開前先向訓練師學會 {s:7928:inv_misc_bandage_01:Silk Bandage}{/b}，這是訓練師教的最後一個配方。",
  ["How to learn Expert First Aid"] = "如何學習專家急救",
  ["To train past 150, buy the {i:16084:inv_misc_book_08:Expert First Aid - Under Wraps} book from {n:0:alliance:Deneb Walker} (Alliance) in Arathi Highlands or {n:0:horde:Balai Lok'Wein} (Horde) in Dustwallow Marsh. The book has {b}no level requirement{/b}, you only need First Aid 125."] = "要學習 150 以上，請向阿拉希高地的 {n:0:alliance:Deneb Walker}（聯盟）或塵泥沼澤的 {n:0:horde:Balai Lok'Wein}（部落）購買 {i:16084:inv_misc_book_08:Expert First Aid - Under Wraps} 這本書。這本書{b}沒有等級需求{/b}，只需要急救 125。",
  ["They also sell the next two manuals, so {b}buy all three{/b} while you are there, or get them from the Auction House if you are low level:"] = "他們也賣接下來的兩本手冊，所以趁在那裡時{b}三本都買{/b}，如果你等級低，也可以在拍賣場購買：",
  ["47x {s:7928:inv_misc_bandage_01:Silk Bandage} - 47 Silk Cloth"] = "47x {s:7928:inv_misc_bandage_01:Silk Bandage} - 47 絲綢",
  ["47x {s:7929:inv_misc_bandage_02:Heavy Silk Bandage} - 94 Silk Cloth"] = "47x {s:7929:inv_misc_bandage_02:Heavy Silk Bandage} - 94 絲綢",
  ["Use the Manual: Heavy Silk Bandage first to learn the recipe."] = "先使用手冊：厚絲綢繃帶來學會配方。",
  ["19x {s:10840:inv_misc_bandage_19:Mageweave Bandage} - 19 Mageweave Cloth"] = "19x {s:10840:inv_misc_bandage_19:Mageweave Bandage} - 19 魔紋布",
  ["Use the Manual: Mageweave Bandage first to learn the recipe."] = "先使用手冊：魔紋繃帶來學會配方。",
  ["Artisan First Aid (225-300)"] = "工匠急救 (225-300)",
  ["You can train First Aid past 225 by completing the Triage quest. It requires {b}First Aid 225{/b} and {b}level 35{/b}, even though the quest itself is level 45."] = "完成「急救」任務即可學習 225 以上的急救。它需要{b}急救 225{/b}和{b}等級 35{/b}，雖然任務本身是 45 級。",
  ["{b}Bring everything you need in order to skill up to 275{/b}, as you will learn the next two bandages from the same doctor, so bring around 90 Mageweave Cloth and 20 Runecloth with you."] = "{b}把升到 275 所需的所有材料都帶上{/b}，因為接下來的兩種繃帶也是向同一位醫生學，所以請帶大約 90 個魔紋布和 20 個符文布。",
  ["The {q:6622::Triage} quest is given by {n:0:horde:Doctor Gregory Victor} in Arathi Highlands at Hammerfall."] = "{q:6622::Triage} 任務由阿拉希高地落錘鎮的 {n:0:horde:Doctor Gregory Victor} 提供。",
  ["Hammerfall, Arathi Highlands"] = "阿拉希高地，落錘鎮",
  ["The {q:6624::Triage} quest is given by {n:0:alliance:Doctor Gustaf VanHowzen} in Dustwallow Marsh at Theramore."] = "{q:6624::Triage} 任務由塵泥沼澤塞拉摩的 {n:0:alliance:Doctor Gustaf VanHowzen} 提供。",
  ["Foothold Citadel, Dustwallow Marsh"] = "塵泥沼澤，據點要塞",
  ["You get a stack of triage bandages and have to save 15 patients, heal the critically injured ones first."] = "你會拿到一組急救繃帶，必須救活 15 位傷患，先治療傷勢危急的。",
  ["How to complete the Triage quest"] = "如何完成急救任務",
  ["Make sure you have about 10 minutes of spare time to do this with no interruptions."] = "請確保你有大約 10 分鐘的空閒時間，可以不被打擾地完成它。",
  ["Press CTRL + V to show the health bars over the patients, or turn on \"Show NPC names\" in the interface options."] = "按 CTRL + V 顯示傷患頭上的血條，或在介面選項中開啟「顯示 NPC 名稱」。",
  ["Zoom the camera out to third person, so you see as much of the room as you can."] = "把鏡頭拉遠到第三人稱，盡可能看到房間的全貌。",
  ["Put the Triage Bandages the doctor gave you on your action bar and use those, not your own bandages."] = "把醫生給你的急救繃帶放到快捷列上並使用它們，不要用你自己的繃帶。",
  ["Stand in the middle of the room."] = "站在房間中央。",
  ["When you see another patient, left-click on them to pre-select them, and as soon as your current heal has finished click the bandages in your action bar and the pre-selected one will begin to heal. Saves valuable seconds this way."] = "看到另一位傷患時，先左鍵點擊他預選，等目前的治療一結束就點快捷列上的繃帶，預選的傷患就會開始接受治療。這樣能省下寶貴的幾秒鐘。",
  ["When you have saved 15 patients, {b}turn in the quest immediately{/b}. I failed it on my druid because I waited, six patients died in the meantime and the quest went from completed to failed."] = "救活 15 位傷患後，{b}立刻交任務{/b}。我用德魯伊時就失敗了，因為我拖了一下，這期間有六位傷患死掉，任務從已完成變成失敗。",
  ["29x {s:10840:inv_misc_bandage_19:Mageweave Bandage} - 29 Mageweave Cloth"] = "29x {s:10840:inv_misc_bandage_19:Mageweave Bandage} - 29 魔紋布",
  ["30x {s:10841:inv_misc_bandage_20:Heavy Mageweave Bandage} - 60 Mageweave Cloth"] = "30x {s:10841:inv_misc_bandage_20:Heavy Mageweave Bandage} - 60 魔紋布",
  ["The doctor teaches it at 240."] = "醫生在 240 時教這個。",
  ["20x {s:18629:inv_misc_bandage_11:Runecloth Bandage} - 20 Runecloth"] = "20x {s:18629:inv_misc_bandage_11:Runecloth Bandage} - 20 符文布",
  ["The doctor teaches it at 260."] = "醫生在 260 時教這個。",
  ["30x {s:1244436:inv_potion_54:Major Healing Potion} - 30 Golden Sansam, 90 Soothing Spices, 30 Crystal Vial"] = "30x {s:1244436:inv_potion_54:Major Healing Potion} - 30 黃金參、90 舒緩香料、30 水晶瓶",
  ["The recipe is {i:255729:inv_misc_book_03:Manual: Major Healing Potion}. Check the Auction House first, and buy it there if it costs less than 8g."] = "配方是 {i:255729:inv_misc_book_03:Manual: Major Healing Potion}。先查看拍賣場，如果價格低於 8 金幣就在那裡買。",
  ["If it costs more, you can buy it from {n:0::Pexmit} in Mount Hyjal for 8g, but he can be tricky to find."] = "如果比較貴，你可以花 8 金幣向海加爾山的 {n:0::Pexmit} 購買，但他可能不太好找。",
  ["Horde players can also get it from Ortak Lomgok in Elderwild, Mount Hyjal, as the reward for {q:96622::A Rest Without Pain}. You have to complete his {q:96616::Herbs for the Bruised and Weary} quest first."] = "部落玩家也可以向海加爾山長青荒野的 Ortak Lomgok 取得，這是 {q:96622::A Rest Without Pain} 的獎勵。你必須先完成他的 {q:96616::Herbs for the Bruised and Weary} 任務。",
  ["This WoW Forever Fishing leveling guide will show you the fastest way to level Fishing from 1 to 300. Fishing takes a lot of patience, you will have to catch a lot of fish to get from start to finish, but you don't need any materials, only a Fishing Pole and a few lures."] = "這份 WoW Forever 釣魚升級指南將告訴你如何以最快的方式將釣魚從 1 升到 300。釣魚需要很多耐心，從頭到尾你得釣非常多的魚，但不需要任何材料，只要一根魚竿和一些魚餌。",
  ["Below you will find every Fishing trainer by starting zone and capital city, where to fish for each skill range, and how to learn Expert and Artisan Fishing. If you haven't leveled Cooking yet, use my Fishing and Cooking leveling guide instead, because the fish you catch will level your Cooking at the same time:"] = "下方有依新手區與主城分類的所有釣魚訓練師、每個技能區間的釣魚地點，以及如何學習專家和工匠釣魚。如果你還沒練烹飪，請改用我的釣魚與烹飪升級指南，因為你釣到的魚可以同時升級烹飪：",
  ["Fishing Trainer Locations"] = "釣魚訓練師位置",
  ["Apprentice Fishing has no level requirement in Forever, so you can learn it on a fresh character. Every trainer also teaches Journeyman Fishing, so you don't have to find a different trainer at 50."] = "在 Forever 中學習學徒釣魚沒有等級需求，所以新角色也能學。每位訓練師也都教熟手釣魚，所以到 50 時不必另找訓練師。",
  ["Orgrimmar: {n:0:horde:Lumak}"] = "奧格瑪：{n:0:horde:Lumak}",
  ["Undercity: {n:0:horde:Armand Cromwell}"] = "幽暗城：{n:0:horde:Armand Cromwell}",
  ["Thunder Bluff: {n:0:horde:Kah Mistrunner}"] = "雷霆崖：{n:0:horde:Kah Mistrunner}",
  ["Every starting zone has a Fishing trainer, and they all stand next to water, so you can start fishing right away."] = "每個新手區都有釣魚訓練師，而且都站在水邊，所以你可以馬上開始釣魚。",
  ["{n:0:horde:Lau'Tiki} on the coast at Sen'jin Village"] = "森金村海岸邊的 {n:0:horde:Lau'Tiki}",
  ["{n:0:horde:Uthan Stillwater} at Stonebull Lake, next to Bloodhoof Village"] = "血蹄村旁石牛湖邊的 {n:0:horde:Uthan Stillwater}",
  ["{n:0:horde:Clyde Kellen} at Brightwater Lake, east of Brill"] = "布瑞爾東邊清水湖邊的 {n:0:horde:Clyde Kellen}",
  ["{n:0::Baelann Swiftcurrent} in Valanaar, {n:0::Fenn Fairweather} in Shen'dar Village"] = "瓦拉納爾的 {n:0::Baelann Swiftcurrent}，申達爾村的 {n:0::Fenn Fairweather}",
  ["Stormwind City: {n:0:alliance:Arnold Leland}"] = "暴風城：{n:0:alliance:Arnold Leland}",
  ["Ironforge: {n:0:alliance:Grimnur Stonebrand}"] = "鐵爐堡：{n:0:alliance:Grimnur Stonebrand}",
  ["Darnassus: {n:0:alliance:Astaia}"] = "達納蘇斯：{n:0:alliance:Astaia}",
  ["{n:0:alliance:Lee Brown} at Crystal Lake, east of Goldshire"] = "閃金鎮東邊水晶湖邊的 {n:0:alliance:Lee Brown}",
  ["{n:0:alliance:Paxton Ganter} at Iceflow Lake, on the way to Gnomeregan"] = "前往諾莫瑞根路上冰流湖邊的 {n:0:alliance:Paxton Ganter}",
  ["{n:0:alliance:Androl Oakhand} in Rut'theran Village, on the shore next to the dock"] = "魯瑟蘭村碼頭旁岸邊的 {n:0:alliance:Androl Oakhand}",
  ["You can find every Fishing trainer for Horde and Alliance on my WoW Forever Fishing Trainers page."] = "你可以在我的 WoW Forever 釣魚訓練師頁面找到部落和聯盟的所有釣魚訓練師。",
  ["How to Fish in WoW Forever (1-75)"] = "如何在 WoW Forever 中釣魚 (1-75)",
  ["Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a few {i:6529:inv_misc_orb_03:Shiny Bauble} from a Fishing Supply or Trade Supply vendor. In the capital cities they stand next to the trainer, for every other zone open your faction below:"] = "向釣魚供應商或商業供應商購買一根 {i:6256:inv_fishingpole_02:Fishing Pole} 和幾個 {i:6529:inv_misc_orb_03:Shiny Bauble}。在主城他們就站在訓練師旁邊，其他區域請展開下方你的陣營：",
  ["{n:0:horde:Zansoa} in Sen'jin Village"] = "森金村的 {n:0:horde:Zansoa}",
  ["{n:0:horde:Martine Tramblay} at the Death's Watch Waystation, south-east of Brill"] = "布瑞爾東南方亡者哨站的 {n:0:horde:Martine Tramblay}",
  ["{n:0::Baelann Swiftcurrent} in Valanaar, {n:0::Belandiel Farflight} in Shen'dar Village"] = "瓦拉納爾的 {n:0::Baelann Swiftcurrent}，申達爾村的 {n:0::Belandiel Farflight}",
  ["{n:0:horde:Shankys}, next to the Fishing trainer"] = "{n:0:horde:Shankys}，在釣魚訓練師旁邊",
  ["{n:0:horde:Lizbeth Cromwell}, next to the Fishing trainer"] = "{n:0:horde:Lizbeth Cromwell}，在釣魚訓練師旁邊",
  ["{n:0:horde:Sewa Mistrunner}, next to the Fishing trainer"] = "{n:0:horde:Sewa Mistrunner}，在釣魚訓練師旁邊",
  ["{n:0:horde:Wik'Tar} in Zoram'gar Outpost"] = "佐拉姆加前哨站的 {n:0:horde:Wik'Tar}",
  ["{n:0:horde:Katoom the Angler}, the Fishing trainer in Revantusk Village"] = "惡齒村的釣魚訓練師 {n:0:horde:Katoom the Angler}",
  ["{n:0:alliance:Gretta Ganter} at Iceflow Lake"] = "冰流湖的 {n:0:alliance:Gretta Ganter}",
  ["{n:0:alliance:Nessa Shadowsong} in Rut'theran Village"] = "魯瑟蘭村的 {n:0:alliance:Nessa Shadowsong}",
  ["{n:0:alliance:Catherine Leland}, next to the Fishing trainer"] = "{n:0:alliance:Catherine Leland}，在釣魚訓練師旁邊",
  ["{n:0:alliance:Tansy Puddlefizz}, next to the Fishing trainer"] = "{n:0:alliance:Tansy Puddlefizz}，在釣魚訓練師旁邊",
  ["{n:0:alliance:Voloren}, next to the Fishing trainer"] = "{n:0:alliance:Voloren}，在釣魚訓練師旁邊",
  ["{n:0:alliance:Khara Deepwater} at the Loch"] = "洛克湖畔的 {n:0:alliance:Khara Deepwater}",
  ["{n:0:alliance:Stuart Fleming} in Menethil Harbor"] = "米奈希爾港的 {n:0:alliance:Stuart Fleming}",
  ["Redridge Mountains"] = "赤脊山",
  ["{n:0:alliance:Vernon Hale} at Lake Everstill"] = "止水湖的 {n:0:alliance:Vernon Hale}",
  ["{n:0:alliance:Lindea Rabonne} in Southshore"] = "南海鎮的 {n:0:alliance:Lindea Rabonne}",
  ["Open the Professions window."] = "打開專業視窗。",
  ["Click on the {b}hammer button{/b} in the row of buttons on the right side of your screen, {b}NOT the Fishing tab{/b}."] = "點擊畫面右側那排按鈕中的{b}錘子按鈕{/b}，{b}不是釣魚分頁{/b}。",
  ["Drag the {s:7731:trade_fishing:Fishing} button from the Fishing box to your action bar."] = "把 {s:7731:trade_fishing:Fishing} 按鈕從釣魚欄位拖到你的快捷列上。",
  ["Equip your Fishing Pole and apply the {i:6529:inv_misc_orb_03:Shiny Bauble} lure."] = "裝備魚竿並裝上 {i:6529:inv_misc_orb_03:Shiny Bauble} 魚餌。",
  ["Go to any starting zone and look for a lake, pond or river. Stand in front of the water and press the fishing button."] = "前往任何新手區，找一座湖泊、池塘或河流。站在水邊按下釣魚按鈕。",
  ["Mouse over the bobber in the water, and when it splashes, right-click on it."] = "把滑鼠移到水中的浮標上，當它濺起水花時，右鍵點擊它。",
  ["Fish until you reach Fishing 75."] = "一直釣到釣魚 75。",
  ["{b}Starting zones:{/b} Dun Morogh, Durotar, Elwynn Forest, Mulgore, Teldrassil, Tirisfal Glades, Zephras Isle"] = "{b}新手區：{/b}丹莫洛、杜洛塔、艾爾文森林、莫高雷、泰達希爾、提里斯法林地、澤弗拉斯島",
  ["{b}Remember, starting zones do not include capital cities!{/b}"] = "{b}請記住，新手區不包含主城！{/b}",
  ["If you can't find the Fishing button, I show it with pictures in my how to fish in WoW Forever guide."] = "如果你找不到釣魚按鈕，我在 WoW Forever 釣魚教學指南中有附圖說明。",
  ["Go back to your trainer and learn Journeyman Fishing. It requires {b}Fishing 50{/b} and {b}level 10{/b}."] = "回到訓練師那裡學習熟手釣魚。需要{b}釣魚 50{/b}和{b}等級 10{/b}。",
  ["Fish until 150 in one of the capital cities:"] = "在以下其中一座主城釣到 150：",
  ["You can fish in any of these zones too: The Barrens, Darkshore, Ironforge, Loch Modan, Silverpine Forest, Westfall."] = "你也可以在這些區域釣魚：貧瘠之地、黑海岸、鐵爐堡、洛克莫丹、銀松森林、西部荒野。",
  ["If the fish keep getting away, buy {i:6530:inv_misc_monstertail_03:Nightcrawlers} from a Fishing Supply vendor. They need Fishing 50."] = "如果魚一直脫鉤，就向釣魚供應商購買 {i:6530:inv_misc_monstertail_03:Nightcrawlers}。它們需要釣魚 50。",
  ["You can learn Expert Fishing from the {i:16083:inv_misc_book_08:Expert Fishing - The Bass and You} book (requires {b}level 20{/b} and {b}Fishing 125{/b}) sold by {n:0::Old Man Heming} at Booty Bay in Stranglethorn Vale. He is in the middle of Booty Bay at the very bottom, near the fishing sign. You can also buy the book from the Auction House."] = "你可以從 {i:16083:inv_misc_book_08:Expert Fishing - The Bass and You} 這本書學習專家釣魚（需要{b}等級 20{/b}和{b}釣魚 125{/b}），由荊棘谷藏寶海灣的 {n:0::Old Man Heming} 出售。他在藏寶海灣中央的最底層，釣魚招牌附近。你也可以在拍賣場買到這本書。",
  ["Buy a bunch of {i:6532:inv_misc_gem_variety_02:Bright Baubles} from Old Man Heming before you leave."] = "離開前向老海明購買一批 {i:6532:inv_misc_gem_variety_02:Bright Baubles}。",
  ["Go to {b}Dustwallow Marsh{/b}, apply {i:6532:inv_misc_gem_variety_02:Bright Baubles} to your Fishing Pole and fish until 225."] = "前往{b}塵泥沼澤{/b}，在魚竿上裝上 {i:6532:inv_misc_gem_variety_02:Bright Baubles}，一直釣到 225。",
  ["I recommend fishing in Dustwallow because the Artisan Fishing quest starts there, but you can fish in these zones too: Alterac Mountains, Arathi Highlands, Desolace, Stranglethorn Vale, Swamp of Sorrows, and Thousand Needles."] = "我推薦在塵泥沼澤釣魚，因為工匠釣魚任務就從那裡開始，但你也可以在這些區域釣：奧特蘭克山脈、阿拉希高地、淒涼之地、荊棘谷、悲傷沼澤和千針石林。",
  ["Learning Artisan Fishing"] = "學習工匠釣魚",
  ["To train Fishing past 225, you must complete the quest {q:6607::Nat Pagle, Angler Extreme} from {n:0::Nat Pagle} in Dustwallow Marsh."] = "要學習 225 以上的釣魚，你必須完成塵泥沼澤 {n:0::Nat Pagle} 的任務 {q:6607::Nat Pagle, Angler Extreme}。",
  ["It requires {b}level 35{/b} and {b}Fishing 225{/b}."] = "它需要{b}等級 35{/b}和{b}釣魚 225{/b}。",
  ["To complete the quest, you have to catch 4 quest fish in four different zones:"] = "要完成任務，你必須在四個不同區域釣到 4 條任務魚：",
  ["{i:16967:inv_misc_monsterhead_02:Feralas Ahi} - Feralas"] = "{i:16967:inv_misc_monsterhead_02:Feralas Ahi} - 菲拉斯",
  ["Use {i:6532:inv_misc_gem_variety_02:Bright Baubles} when you are fishing in {b}Feralas{/b} to stop the fish from getting away. You don't need any lures in the other zones because your Fishing skill is high enough by then."] = "在{b}菲拉斯{/b}釣魚時使用 {i:6532:inv_misc_gem_variety_02:Bright Baubles} 防止魚脫鉤。其他區域不需要任何魚餌，因為那時你的釣魚技能已經夠高了。",
  ["Nat Pagle, Angler Extreme quest"] = "納特·帕格：釣魚大師 任務",
  ["After you completed the quest, fish in any of these zones:"] = "完成任務後，在以下任一區域釣魚：",
  ["Feralas"] = "菲拉斯",
  ["Western Plaguelands"] = "西瘟疫之地",
  ["You will have to use {i:6532:inv_misc_gem_variety_02:Bright Baubles} in these zones to stop the fish from getting away!"] = "在這些區域你必須使用 {i:6532:inv_misc_gem_variety_02:Bright Baubles} 防止魚脫鉤！",
  ["This WoW Forever Lockpicking leveling guide will show you the fastest way to level Lockpicking from 1 to 300, with the best place to pick locks for each skill range."] = "這份 WoW Forever 開鎖升級指南將告訴你如何以最快的方式將開鎖從 1 升到 300，以及每個技能區間最適合開鎖的地點。",
  ["Max Lockpicking Skill by Level"] = "各等級的開鎖技能上限",
  ["{b}Your Lockpicking skill can't go higher than 5 times your level{/b}, so you have to level your character to level Lockpicking. This is the level you need for each part of the guide:"] = "{b}你的開鎖技能不能超過等級的 5 倍{/b}，所以必須練角色等級才能練開鎖。以下是指南各部分所需的等級：",
  ["Your level"] = "你的等級",
  ["Max Lockpicking skill"] = "開鎖技能上限",
  ["I originally made this guide with my rogue in Classic. In WoW Forever I'm leveling a hunter, so a friend of mine checks the spots on his rogue, and he confirmed the Horde 1-100 part. Readers told me where they leveled from 150 to 300. I'm assuming the rest is the same as in Classic, but I will confirm it later. If something looks off, send me feedback."] = "這份指南最初是我在經典版用盜賊做的。在 WoW Forever 中我練的是獵人，所以由一位朋友用他的盜賊確認這些地點，他確認了部落 1-100 的部分。150 到 300 是讀者告訴我他們在哪裡練的。其餘部分我假設和經典版相同，但之後會再確認。如果有什麼不對，請告訴我。",
  ["Go to the ship near Ratchet in The Barrens. The Buccaneer's Strongboxes there respawn after a few seconds, so even two rogues can skill up there at the same time. {b}They are inside the ship{/b}, at the spot marked on the map below."] = "前往貧瘠之地棘齒城附近的船。那裡的海盜保險箱幾秒鐘就會重生，所以即使兩個盜賊也能同時在那裡練。{b}它們在船裡面{/b}，位置在下方地圖上標示的地方。",
  ["There is another chest at the bottom of the ship called The Jewel of the Southsea. Don't open it if you are low level, because it spawns a mob that will kill you."] = "船底還有另一個箱子叫南海之寶。如果你等級低就不要打開，因為它會召喚出一隻會殺掉你的怪物。",
  ["There are a bunch of Practice Lockboxes in Redridge Mountains, north of Lake Everstill. They respawn really fast, so you can get to 100 there easily."] = "赤脊山止水湖北邊有一堆練習用保險箱。它們重生非常快，所以你可以輕鬆在那裡升到 100。",
  ["Go to Zoram Strand in Ashenvale and look for Waterlogged Footlockers along the shore, on land."] = "前往梣谷的佐拉姆海岸，沿著岸邊的陸地上尋找浸水的提箱。",
  ["Go to Angor Fortress in Badlands. There are two kinds of footlockers there, the Battered Footlockers upstairs need 150, and the Dented Footlockers downstairs need {b}175{/b}."] = "前往荒蕪之地的安戈爾要塞。那裡有兩種提箱，樓上的破損的提箱需要 150，樓下的凹陷的提箱需要{b}175{/b}。",
  ["The footlockers downstairs give a skill point every time until 215, so you can stay here until 225."] = "樓下的提箱到 215 之前每次都會給一個技能點，所以你可以在這裡待到 225。",
  ["Don't bother pickpocketing the mobs there, because their boxes are too low level to give any skill."] = "不用費心偷竊那裡怪物的口袋，因為牠們的箱子等級太低，不會給任何技能點。",
  ["Go to The Slag Pit, the cave in the middle of Searing Gorge, and pick the footlockers there. The ones on the upper part give skill points all the way to 300. They stay yellow until 290 and turn green after that, so the last 10 points take longer."] = "前往灼熱峽谷中央的洞穴熔渣之池，開那裡的提箱。上層的提箱一直到 300 都會給技能點。它們到 290 之前都是黃色，之後變綠，所以最後 10 點會花比較久。",
  ["{b}There are two kinds of Dented Footlockers in the Slag Pit{/b}, with the same name. The ones on the lower part need 200 and the ones on the upper part need 225. Pick both until the lower ones stop giving skill points, then stay on the upper part."] = "{b}熔渣之池裡有兩種凹陷的提箱{/b}，名稱相同。下層的需要 200，上層的需要 225。兩種都開，直到下層的不再給技能點，然後就待在上層。",
  ["Don't bother pickpocketing the mobs there, because their boxes are too low level to give much skill."] = "不用費心偷竊那裡怪物的口袋，因為牠們的箱子等級太低，給不了多少技能點。",
  ["This WoW Forever camping guide will show you how camping works, how to make a campfire and every camp item and buff of every profession."] = "這份 WoW Forever 露營指南將告訴你露營如何運作、如何製作營火，以及每種專業的所有露營物品和增益效果。",
  ["Three night elves sitting at a campfire in Dolanaar, Teldrassil, in WoW Forever"] = "WoW Forever 中三位夜精靈坐在泰達希爾多蘭納爾的營火旁",
  ["How Camping Works"] = "露營如何運作",
  ["Someone puts down a campfire, and everyone around it can place a camp item of their own profession. {b}Sit (/sit) next to the fire for a minute{/b}, you will see a buff start counting down. Then you get Camp Benefits, one buff with everything the camp items give, for an hour."] = "有人放下營火後，周圍的每個人都可以放置一個自己專業的露營物品。{b}在營火旁坐下（/sit）一分鐘{/b}，你會看到一個增益效果開始倒數。之後你會獲得營地效益，這是一個整合所有露營物品效果的增益，持續一小時。",
  ["{b}Each player can place one camp item{/b}, and it puts all your camp items on a 1 hour cooldown. A campfire holds 3, 5 or 10 camp items, depending on how big it is (see How to Make a Campfire below). The buffs are weaker class buffs and don't stack with them."] = "{b}每位玩家可以放置一個露營物品{/b}，放置後你所有的露營物品都會進入 1 小時冷卻。一堆營火可以容納 3、5 或 10 個露營物品，取決於營火的大小（見下方「如何製作營火」）。這些增益是較弱的職業增益，不會與職業增益疊加。",
  ["The intro quests in the starting zones, The Great Outdoors and Camping 101, are optional, the buffs work without them. The quest givers' fires always give the Camp Tent's rested experience."] = "新手區的入門任務「The Great Outdoors」和「Camping 101」是選擇性的，沒有完成增益也能生效。任務提供者的營火總是會提供露營帳篷的休息經驗值。",
  ["How to Make a Campfire"] = "如何製作營火",
  ["Learn Cooking from any Cooking trainer, the Basic Campfire Kit comes with it at skill 1. {i:4470:inv_tradeskillitem_01:Simple Wood} is sold by the trade and general goods vendors in most towns. Open your Professions window (the hammer and pick button in the menu bar), craft the kit from 1 Simple Wood under Cooking, then use it from your bags to place the campfire."] = "向任何烹飪訓練師學習烹飪，技能 1 時就會附帶基礎營火工具包。{i:4470:inv_tradeskillitem_01:Simple Wood} 在大多數城鎮的商業和雜貨商人都有賣。打開專業視窗（選單列上的錘子與十字鎬按鈕），在烹飪下用 1 個簡易木材製作工具包，然後從背包使用它來放置營火。",
  ["{b}Tip:{/b} you don't have to carry Flint and Tinder and wood around any more, craft a stack of Basic Campfire Kits at home and carry only those, they take one bag slot. You can also hand them to others."] = "{b}提示：{/b}你再也不用隨身帶著打火石和木材了，在家先做一疊基礎營火工具包，只帶這些就好，它們只佔一個背包格。你也可以把它們送給別人。",
  ["The bigger campfires hold more camp items, but they need a Blueprint."] = "較大的營火可以容納更多露營物品，但需要藍圖。",
  ["The Expert Campfire Kit needs more Cooking to use than to learn (220 against 200). It's usually the other way around, so maybe it's a bug."] = "專家營火工具包使用時需要的烹飪技能比學習時還高（220 對 200）。通常是反過來的，所以可能是個錯誤。",
  ["Learn at"] = "學習技能",
  ["Use at"] = "使用技能",
  ["Camp items"] = "露營物品",
  ["Made from"] = "製作材料",
  ["Comes with Cooking"] = "學會烹飪時附帶",
  ["{i:273087:inv_garrison_blueprints3:Blueprint: Journeyman Campfire} Dropped by: {n:3673::Lord Serpentis} in Wailing Caverns"] = "{i:273087:inv_garrison_blueprints3:Blueprint: Journeyman Campfire} 掉落自：哀嚎洞穴的 {n:3673::Lord Serpentis}",
  ["{i:273101:inv_garrison_blueprints3:Blueprint: Expert Campfire} I don't know yet where it drops"] = "{i:273101:inv_garrison_blueprints3:Blueprint: Expert Campfire} 我還不知道從哪裡掉落",
  ["Camp Items"] = "露營物品",
  ["Every profession has three camp items, at skill 20, 140 and 300 (Cooking has two), and each one replaces the one before. The tier 1 item comes from your profession trainer, {b}tier 2 and 3 need a Blueprint{/b}, a recipe item. The tier 2 and 3 blueprints drop from bosses, most of them in dungeons, the tabs show which one. Only the Herbalism one at 300 is not known yet."] = "每種專業有三個露營物品，分別在技能 20、140 和 300（烹飪有兩個），每一個都會取代前一個。第 1 階物品向你的專業訓練師學習，{b}第 2 和第 3 階需要藍圖{/b}，也就是一種配方物品。第 2 和第 3 階的藍圖由首領掉落，大多在地城裡，分頁中會列出是哪一個。只有草藥學 300 的那個目前還不清楚。",
  ["{b}Every item also gives the buff of the tier 1 item of its profession{/b}, so you never have to choose between a buff and a crafting station. A Master Forge still gives the Strength buff of the Sharpening Wheel. Whether a tier 3 item also gives what the tier 2 item gives (an anvil from a Master Forge) is not confirmed yet. The tabs only list what each tier adds."] = "{b}每個物品也會提供該專業第 1 階物品的增益{/b}，所以你永遠不必在增益和製作設施之間做選擇。大師鍛爐仍然會提供磨刀輪的力量增益。第 3 階物品是否也提供第 2 階物品的功能（大師鍛爐是否附帶鐵砧）尚未確認。分頁只列出每一階新增的內容。",
  ["Alchemy"] = "鍊金術",
