  ["Mana regeneration buff, doesn't stack with Blessing of Wisdom"] = "法力恢復增益，不與智慧祝福疊加",
  ["Trainer or the Camping 101 quest"] = "訓練師或 Camping 101 任務",
  ["A Fermenter, needed for a few Alchemy recipes"] = "一台發酵器，部分鍊金術配方需要",
  ["{i:273085:inv_garrison_blueprints3:Blueprint: Fermenter} Dropped by: {n:250657::Rath'mael} in the Ruins of Lordaeron"] = "{i:273085:inv_garrison_blueprints3:Blueprint: Fermenter} 掉落自：羅德隆廢墟的 {n:250657::Rath'mael}",
  ["An Alchemy Lab, needed for some Alchemy recipes"] = "一座鍊金實驗室，部分鍊金術配方需要",
  ["{i:273112:inv_garrison_blueprints3:Blueprint: Alchemy Laboratory} Dropped by: {n:10508::Ras Frostwhisper} in Scholomance"] = "{i:273112:inv_garrison_blueprints3:Blueprint: Alchemy Laboratory} 掉落自：通靈學院的 {n:10508::Ras Frostwhisper}",
  ["Strength buff, doesn't stack with Strength of Earth Totem"] = "力量增益，不與大地之力圖騰疊加",
  ["An anvil"] = "一座鐵砧",
  ["{i:273086:inv_garrison_blueprints3:Blueprint: Anvil} Dropped by: {n:1763::Gilnid} in The Deadmines"] = "{i:273086:inv_garrison_blueprints3:Blueprint: Anvil} 掉落自：死亡礦坑的 {n:1763::Gilnid}",
  ["A Master Forge, needed for many Blacksmithing recipes"] = "一座大師鍛爐，許多鍛造配方需要",
